impl TestPg {
    async fn start_if_enabled() -> Option<Self> {
        Self::start_if_enabled_with_tag("16-alpine").await
    }

    async fn start_if_enabled_with_tag(tag: &str) -> Option<Self> {
        if std::env::var("BROCADE_RUN_PG_TESTS").as_deref() != Ok("1") {
            eprintln!("skipping Postgres integration test; set BROCADE_RUN_PG_TESTS=1 to run");
            return None;
        }

        let container = Postgres::default()
            .with_tag(tag)
            .start()
            .await
            .expect("start postgres container");
        let port = container
            .get_host_port_ipv4(5432)
            .await
            .expect("postgres mapped port");
        let database_url = format!("postgres://postgres:postgres@127.0.0.1:{port}/postgres");
        let store = PgStore::connect(&database_url)
            .await
            .expect("connect postgres");
        Some(Self {
            _container: container,
            store,
            url: database_url,
        })
    }

    /// The same server, a different database name.
    fn url_for(&self, database: &str) -> String {
        let (prefix, _) = self.url.rsplit_once('/').expect("URL 末尾是 /<库名>");
        format!("{prefix}/{database}")
    }

    fn pool(&self) -> &PgPool {
        self.store.pool()
    }
}

async fn wait_for_advisory_waiters(pool: &PgPool, minimum: i64) {
    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let waiting: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM pg_locks
                  WHERE locktype = 'advisory' AND NOT granted",
            )
            .fetch_one(pool)
            .await
            .unwrap();
            if waiting >= minimum {
                break;
            }
            tokio::task::yield_now().await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("timed out waiting for {minimum} advisory lock waiter(s)"));
}

