/// Delivery is asynchronous, so an earlier snapshot may finish its POST after a newer one. The
/// server must acknowledge that retry without moving the current runtime state backwards.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn delayed_runtime_report_cannot_overwrite_a_newer_snapshot() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    db.store.issue_node_token("n1").await.unwrap();
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let report = |observed_at_unix_secs, agent: &str| NodeRuntimeReport {
        observed_at_unix_secs,
        certificate: Default::default(),
        versions: NodeVersions {
            unlock_ip_families: None,
            unlock_connection_trace: None,
            agent: agent.to_owned(),
            xray: None,
            xray_installed_sha256: None,
            xray_running_sha256: None,
            xray_handoff: None,
            kernel_tls_module: None,
            phantun: None,
            openvpn: None,
            vpngate_catalog_probe_workers: None,
            wg_tools: None,
            wg_backend: None,
        },
        geodata: None,
        local_reconcile: None,
        wireguard_health: None,
        traffic: None,
        online_sources: None,
        xray_upgrade: None,
        spool: SpoolBacklog {
            observation: 0,
            usage: 0,
            load: 0,
            dropped: 0,
            usage_dropped: Some(0),
            observation_dropped: Some(0),
            load_dropped: Some(0),
        },
    };

    db.store
        .record_node_runtime("n1", &report(now + 1, "new"))
        .await
        .unwrap();
    db.store
        .record_node_runtime("n1", &report(now, "old"))
        .await
        .unwrap();

    let stored: serde_json::Value =
        sqlx::query_scalar("SELECT runtime_versions FROM node_agent_state WHERE node_id = 'n1'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(stored["agent"], "new");
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn config_xray_force_retirement_is_exact_idempotent_and_settled_by_runtime() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    db.store.issue_node_token("n1").await.unwrap();

    let revision_id: i64 =
        sqlx::query_scalar("SELECT current_revision FROM control_state WHERE id = TRUE")
            .fetch_one(db.pool())
            .await
            .unwrap();
    let deployment_id: i64 = sqlx::query_scalar(
        "INSERT INTO deployments (
             revision_id, status, active, kind, activation_status, settlement_status
         ) VALUES ($1, 'succeeded', NULL, 'config', 'activated', 'converged')
         RETURNING id",
    )
    .bind(revision_id)
    .fetch_one(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO deployment_targets (deployment_id, node_id, status)
         VALUES ($1, 'n1', 'succeeded')",
    )
    .bind(deployment_id)
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO deployment_target_state (
             deployment_id, node_id, wave, disruptive, desired_structure,
             desired_grants, claim_generation
         ) VALUES ($1, 'n1', 0, TRUE, '{}'::jsonb, '{}'::jsonb, 7)",
    )
    .bind(deployment_id)
    .execute(db.pool())
    .await
    .unwrap();

    let runtime = XrayUpgradeRuntime {
        source: brocade_deployment::protocol::XrayUpgradeSource::ConfigDeployment {
            deployment_id,
            claim_generation: 7,
        },
        release_id: deployment_id.saturating_neg(),
        attempt: 0,
        strategy: XrayReleaseStrategy::Handoff,
        phase: XrayUpgradePhase::Blocked,
        old: XrayUpgradeProcess {
            pid: 101,
            pid_start_ticks: 1_001,
            boot_id: "01234567-89ab-cdef-0123-456789abcdef".to_owned(),
            sha256: "a".repeat(64),
            alive: true,
            accepting: Some(false),
            active_connections: Some(14),
        },
        candidate: Some(XrayUpgradeProcess {
            pid: 202,
            pid_start_ticks: 1_002,
            boot_id: "01234567-89ab-cdef-0123-456789abcdef".to_owned(),
            sha256: "b".repeat(64),
            alive: true,
            accepting: Some(true),
            active_connections: Some(2),
        }),
        drain_deadline_unix_secs: Some(1),
        blocked_reason: Some("old generation still has 14 connections".to_owned()),
    };
    sqlx::query(
        "UPDATE node_agent_state
            SET agent_protocol_version = $2,
                runtime_reported_at = now(),
                xray_upgrade = $3
          WHERE node_id = $1",
    )
    .bind("n1")
    .bind(
        i32::try_from(brocade_deployment::protocol::CONFIG_XRAY_FORCE_RETIREMENT_PROTOCOL_VERSION)
            .unwrap(),
    )
    .bind(serde_json::to_value(&runtime).unwrap())
    .execute(db.pool())
    .await
    .unwrap();

    assert!(matches!(
        db.store
            .force_config_xray_retirement(&publisher("platform.acme"), deployment_id, "n1")
            .await,
        Err(StoreError::Forbidden(_))
    ));
    let first = db
        .store
        .force_config_xray_retirement(&system_admin(), deployment_id, "n1")
        .await
        .unwrap();
    assert_eq!(first.claim_generation, 7);
    assert_eq!(first.active_connections, 14);
    assert!(!first.reused);
    let repeated = db
        .store
        .force_config_xray_retirement(&system_admin(), deployment_id, "n1")
        .await
        .unwrap();
    assert!(repeated.reused);
    assert_eq!(
        db.store
            .config_xray_force_retirement_command("n1")
            .await
            .unwrap()
            .unwrap(),
        brocade_deployment::protocol::ConfigXrayForceRetirementCommand {
            deployment_id,
            claim_generation: 7,
        }
    );

    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    db.store
        .record_node_runtime(
            "n1",
            &NodeRuntimeReport {
                observed_at_unix_secs: now + 1,
                certificate: Default::default(),
                versions: NodeVersions {
                    unlock_ip_families: None,
                    unlock_connection_trace: None,
                    agent: "force-retirement-test".to_owned(),
                    xray: None,
                    xray_installed_sha256: None,
                    xray_running_sha256: None,
                    xray_handoff: None,
                    kernel_tls_module: None,
                    phantun: None,
                    openvpn: None,
                    vpngate_catalog_probe_workers: None,
                    wg_tools: None,
                    wg_backend: None,
                },
                geodata: None,
                local_reconcile: None,
                wireguard_health: None,
                traffic: None,
                online_sources: None,
                xray_upgrade: None,
                spool: SpoolBacklog {
                    observation: 0,
                    usage: 0,
                    load: 0,
                    dropped: 0,
                    usage_dropped: Some(0),
                    observation_dropped: Some(0),
                    load_dropped: Some(0),
                },
            },
        )
        .await
        .unwrap();
    assert!(db
        .store
        .config_xray_force_retirement_command("n1")
        .await
        .unwrap()
        .is_none());
    // The next block intentionally reuses the same synthetic handoff identity to isolate the
    // automatic path. Production identities never reappear after their runtime reaches None.
    sqlx::query("DELETE FROM config_xray_force_retirements WHERE node_id = 'n1'")
        .execute(db.pool())
        .await
        .unwrap();

    // A later configuration release is itself authorization to clear the preceding generation.
    // It must not wait for the preceding runtime's remaining grace window, and it must retain the
    // preceding deployment/claim identity rather than copying the new release identity.
    let next = db
        .store
        .create_deployment(
            &system_admin(),
            create_deployment_request(
                u64::try_from(revision_id).unwrap(),
                "config-force-next-release",
            ),
        )
        .await
        .unwrap();
    // The same revision is a no-op in this fixture. Turn its already compiled target into a
    // synthetic eligible Xray work order so this test isolates the retirement-command boundary.
    sqlx::query(
        "UPDATE deployments
            SET status = 'planned', active = TRUE, finished_at = NULL
          WHERE id = $1",
    )
    .bind(next.deployment_id)
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "UPDATE deployment_targets SET status = 'pending' WHERE deployment_id = $1 AND node_id = 'n1'",
    )
    .bind(next.deployment_id)
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "UPDATE deployment_target_state
            SET desired_structure = jsonb_set(
                desired_structure, '{actions}', '[\"apply-xray\"]'::jsonb, TRUE
            )
          WHERE deployment_id = $1 AND node_id = 'n1'",
    )
    .bind(next.deployment_id)
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO deployment_wave_confirmations (deployment_id, wave, actor)
         SELECT deployment_id, wave, 'test-system'
           FROM deployment_target_state
          WHERE deployment_id = $1 AND node_id = 'n1'
         ON CONFLICT DO NOTHING",
    )
    .bind(next.deployment_id)
    .execute(db.pool())
    .await
    .unwrap();
    let due = db
        .store
        .load_desired_for_node("n1")
        .await
        .unwrap()
        .expect("synthetic next configuration is executable");
    assert_eq!(due.deployment_id, next.deployment_id);
    let mut draining = runtime;
    draining.phase = XrayUpgradePhase::Draining;
    draining.drain_deadline_unix_secs = Some(now + 300);
    sqlx::query(
        "UPDATE node_agent_state
            SET runtime_reported_at = now(), xray_upgrade = $2
          WHERE node_id = $1",
    )
    .bind("n1")
    .bind(serde_json::to_value(draining).unwrap())
    .execute(db.pool())
    .await
    .unwrap();
    assert_eq!(
        db.store
            .config_xray_force_retirement_command("n1")
            .await
            .unwrap()
            .unwrap(),
        brocade_deployment::protocol::ConfigXrayForceRetirementCommand {
            deployment_id,
            claim_generation: 7,
        }
    );
    assert_eq!(
        sqlx::query_scalar::<_, String>(
            "SELECT requested_by
               FROM config_xray_force_retirements
              WHERE node_id = 'n1' AND settled_at IS NULL",
        )
        .fetch_one(db.pool())
        .await
        .unwrap(),
        format!("deployment:{}", next.deployment_id)
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn online_sources_store_raw_public_ips_and_follow_latest_snapshot() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    db.store.issue_node_token("n1").await.unwrap();

    fn report(
        observed_at_unix_secs: i64,
        online_sources: Option<Vec<UserOnlineSources>>,
    ) -> NodeRuntimeReport {
        NodeRuntimeReport {
            observed_at_unix_secs,
            certificate: Default::default(),
            versions: NodeVersions {
                unlock_ip_families: None,
                unlock_connection_trace: None,
                agent: "online-source-test".to_owned(),
                xray: None,
                xray_installed_sha256: None,
                xray_running_sha256: None,
                xray_handoff: None,
                kernel_tls_module: None,
                phantun: None,
                openvpn: None,
                vpngate_catalog_probe_workers: None,
                wg_tools: None,
                wg_backend: None,
            },
            geodata: None,
            local_reconcile: None,
            wireguard_health: None,
            traffic: None,
            online_sources,
            xray_upgrade: None,
            spool: SpoolBacklog {
                observation: 0,
                usage: 0,
                load: 0,
                dropped: 0,
                usage_dropped: Some(0),
                observation_dropped: Some(0),
                load_dropped: Some(0),
            },
        }
    }

    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let initial = vec![UserOnlineSources {
        label: "alice@platform.acme#ing-a1b2".to_owned(),
        sources: vec![
            OnlineSource {
                ip: "1.1.1.1".to_owned(),
                last_seen_unix_secs: now,
                protocols: Some(vec![
                    brocade_deployment::protocol::OnlineSourceProtocol::Vless,
                ]),
                online_since_unix_secs: Some(now - 60),
                session_uplink_bytes: Some(1_024),
                session_downlink_bytes: Some(2_048),
            },
            OnlineSource {
                ip: "1.1.1.1".to_owned(),
                last_seen_unix_secs: now,
                protocols: Some(vec![
                    brocade_deployment::protocol::OnlineSourceProtocol::AnyTls,
                ]),
                online_since_unix_secs: Some(now - 60),
                session_uplink_bytes: Some(1_024),
                session_downlink_bytes: Some(2_048),
            },
            OnlineSource {
                ip: "2606:4700:4700::1111".to_owned(),
                last_seen_unix_secs: now,
                protocols: None,
                online_since_unix_secs: None,
                session_uplink_bytes: None,
                session_downlink_bytes: None,
            },
            OnlineSource {
                ip: "192.168.1.20".to_owned(),
                last_seen_unix_secs: now,
                protocols: None,
                online_since_unix_secs: None,
                session_uplink_bytes: None,
                session_downlink_bytes: None,
            },
        ],
    }];
    db.store
        .record_node_runtime("n1", &report(now, Some(initial)))
        .await
        .unwrap();

    let raw_ips: Vec<String> = sqlx::query_scalar(
        "SELECT host(source_ip)
           FROM user_online_sources
          WHERE active
          ORDER BY host(source_ip)",
    )
    .fetch_all(db.pool())
    .await
    .unwrap();
    assert_eq!(
        raw_ips,
        ["1.1.1.1".to_owned(), "2606:4700:4700::1111".to_owned()],
        "public source addresses must be stored verbatim and deduplicated"
    );

    let presence = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = presence
        .users
        .iter()
        .find(|user| user.tenant_id == "platform.acme" && user.user_id == "alice")
        .unwrap();
    assert_eq!(alice.state, UserPresenceState::Complete);
    assert_eq!(alice.expected_nodes, 1);
    assert_eq!(alice.reporting_nodes, 1);
    assert!(alice.missing_nodes.is_empty());
    assert_eq!(alice.sources.len(), 2);
    let v4 = alice
        .sources
        .iter()
        .find(|source| source.ip == "1.1.1.1")
        .unwrap();
    assert_eq!(v4.session_uplink_bytes, Some(1_024));
    assert_eq!(v4.session_downlink_bytes, Some(2_048));
    assert!(v4.online_since_at.is_some());
    assert_eq!(v4.accesses.len(), 1);
    assert_eq!(v4.accesses[0].node_id, "n1");
    assert_eq!(v4.accesses[0].ingress_id, "ing-a1b2");
    assert_eq!(v4.accesses[0].last_observed_at, v4.last_observed_at);
    assert_eq!(v4.accesses[0].online_since_at, v4.online_since_at);
    assert_eq!(v4.accesses[0].session_uplink_bytes, Some(1_024));
    assert_eq!(v4.accesses[0].session_downlink_bytes, Some(2_048));
    assert_eq!(
        v4.accesses[0].protocols,
        Some(vec![
            brocade_deployment::protocol::OnlineSourceProtocol::Vless,
            brocade_deployment::protocol::OnlineSourceProtocol::AnyTls,
        ])
    );
    let v4_accesses = v4.accesses.clone();
    assert_eq!(
        alice
            .sources
            .iter()
            .find(|source| source.ip.contains(':'))
            .unwrap()
            .accesses[0]
            .protocols,
        None
    );
    let current_only = db
        .store
        .user_online_source_history(&system_admin(), "platform.acme", "alice")
        .await
        .unwrap();
    assert!(
        current_only.sources.is_empty(),
        "currently online addresses must not be duplicated in history"
    );
    let outside_scope = db
        .store
        .user_online_source_history(&tenant_admin("other"), "platform.acme", "alice")
        .await
        .unwrap_err();
    assert!(matches!(outside_scope, StoreError::Forbidden(_)));

    let reported_at: String = sqlx::query_scalar(
        "SELECT online_sources_reported_at::text FROM node_agent_state WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    db.store
        .record_node_runtime("n1", &report(now + 1, None))
        .await
        .unwrap();
    let unchanged_reported_at: String = sqlx::query_scalar(
        "SELECT online_sources_reported_at::text FROM node_agent_state WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(unchanged_reported_at, reported_at);
    let active_after_unavailable: i64 =
        sqlx::query_scalar("SELECT count(*) FROM user_online_sources WHERE active")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(
        active_after_unavailable, 2,
        "None must not fabricate an offline event"
    );

    db.store
        .record_node_runtime("n1", &report(now + 2, Some(Vec::new())))
        .await
        .unwrap();
    let presence = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = presence
        .users
        .iter()
        .find(|user| user.tenant_id == "platform.acme" && user.user_id == "alice")
        .unwrap();
    assert_eq!(alice.state, UserPresenceState::Complete);
    assert!(
        alice.missing_nodes.is_empty(),
        "a successful empty report is fresh"
    );
    assert!(
        alice.sources.is_empty(),
        "an empty successful snapshot means zero online sources"
    );
    let history = db
        .store
        .user_online_source_history(&system_admin(), "platform.acme", "alice")
        .await
        .unwrap();
    assert_eq!(history.retention_days, 30);
    let historical_v4 = history
        .sources
        .iter()
        .find(|source| source.ip == "1.1.1.1")
        .unwrap();
    assert_eq!(historical_v4.accesses.len(), 1);
    let historical_access = &historical_v4.accesses[0];
    assert_eq!(historical_access.node_id, v4_accesses[0].node_id);
    assert_eq!(historical_access.ingress_id, v4_accesses[0].ingress_id);
    assert_eq!(historical_access.protocols, v4_accesses[0].protocols);
    assert_eq!(
        historical_access.online_since_at,
        v4_accesses[0].online_since_at
    );
    assert_eq!(historical_access.session_uplink_bytes, Some(1_024));
    assert_eq!(historical_access.session_downlink_bytes, Some(2_048));
    assert_eq!(
        historical_access.last_observed_at,
        historical_v4.last_observed_at
    );
    assert!(!history.truncated);
    assert_eq!(
        history
            .sources
            .iter()
            .map(|source| source.ip.as_str())
            .collect::<Vec<_>>(),
        ["1.1.1.1", "2606:4700:4700::1111"]
    );
    sqlx::query(
        "UPDATE user_online_sources
            SET active = TRUE,
                first_observed_at = now() - interval '31 days',
                last_observed_at = now() - interval '31 days',
                xray_last_seen_at = now() - interval '31 days',
                online_since_at = NULL,
                session_uplink_bytes = NULL,
                session_downlink_bytes = NULL,
                offline_at = NULL
          WHERE source_ip = '1.1.1.1'::inet",
    )
    .execute(db.pool())
    .await
    .unwrap();
    assert_eq!(db.store.prune_user_online_sources(30).await.unwrap(), 1);
    let expired_ip_exists: bool = sqlx::query_scalar(
        "SELECT EXISTS (
            SELECT 1 FROM user_online_sources WHERE source_ip = '1.1.1.1'::inet
         )",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert!(
        !expired_ip_exists,
        "a stale active row must not outlive the history retention window"
    );

    let stale = vec![UserOnlineSources {
        label: "alice@platform.acme#ing-a1b2".to_owned(),
        sources: vec![OnlineSource {
            ip: "8.8.8.8".to_owned(),
            last_seen_unix_secs: now + 1,
            protocols: None,
            online_since_unix_secs: None,
            session_uplink_bytes: None,
            session_downlink_bytes: None,
        }],
    }];
    db.store
        .record_node_runtime("n1", &report(now + 1, Some(stale)))
        .await
        .unwrap();
    let active_after_stale: i64 =
        sqlx::query_scalar("SELECT count(*) FROM user_online_sources WHERE active")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(
        active_after_stale, 0,
        "an older report must not reactivate a source"
    );
    sqlx::query(
        "UPDATE node_agent_state SET online_sources_reported_at = now() - interval '13 minutes'
          WHERE node_id = 'n1'",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let expired = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = expired
        .users
        .iter()
        .find(|user| user.user_id == "alice")
        .unwrap();
    assert_eq!(alice.state, UserPresenceState::Unavailable);
    assert_eq!(alice.missing_nodes.len(), 1);
    assert_eq!(alice.missing_nodes[0].node_id, "n1");
    assert!(alice.missing_nodes[0].last_reported_at.is_some());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn online_sources_protocols_replace_per_node_and_ingress_without_inflating_counts() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    sqlx::query(
        "INSERT INTO nodes (id, tenant_id, name, public_ipv4, overlay_addr,
                            wg_private_key, wg_public_key, wg_listen_port, api_port,
                            overlay, egress_allowed, dns_kind, dns_servers)
         SELECT 'n2', tenant_id, 'Node 2', 'n2.example.net', '10.66.0.2',
                'wg-private-2', 'wg-public-2', wg_listen_port, api_port,
                overlay, egress_allowed, dns_kind, dns_servers FROM nodes WHERE id = 'n1'",
    )
    .execute(db.pool())
    .await
    .unwrap();
    for (id, node, port) in [("ing-c3d4", "n1", 8443), ("ing-e5f6", "n2", 443)] {
        sqlx::query(
            "INSERT INTO ingresses (id, app_id, chain_id, node_id, bind, port, transport_kind,
                                    reality_private_key, reality_public_key, reality_short_ids,
                                    reality_dest, reality_server_names, reality_flow, reality_fallback_mode)
             SELECT $1, app_id, chain_id, $2, bind, $3, transport_kind,
                    reality_private_key, reality_public_key, reality_short_ids,
                    reality_dest, reality_server_names, reality_flow, reality_fallback_mode
               FROM ingresses WHERE id = 'ing-a1b2'",
        ).bind(id).bind(node).bind(port).execute(db.pool()).await.unwrap();
        sqlx::query(
            "INSERT INTO grants (app_id, tenant_id, user_id, ingress_id)
                     VALUES ('app-main', 'platform.acme', 'alice', $1)",
        )
        .bind(id)
        .execute(db.pool())
        .await
        .unwrap();
    }
    for node in ["n1", "n2"] {
        db.store.issue_node_token(node).await.unwrap();
    }
    let initial = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = initial
        .users
        .iter()
        .find(|user| user.user_id == "alice")
        .unwrap();
    assert_eq!(
        alice.expected_nodes, 2,
        "count machines, not their three ingresses"
    );
    assert_eq!(alice.missing_nodes.len(), 2);
    assert_eq!(alice.missing_nodes[0].node_id, "n1");
    assert_eq!(alice.missing_nodes[1].node_id, "n2");
    assert!(alice
        .missing_nodes
        .iter()
        .all(|node| node.last_reported_at.is_none()));
    assert!(db
        .store
        .list_user_presence(&tenant_admin("other"))
        .await
        .unwrap()
        .users
        .is_empty());
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let snapshot = |at, entries: &[(&str, serde_json::Value)]| -> NodeRuntimeReport {
        serde_json::from_value(json!({
            "observed_at_unix_secs": at,
            "certificate": {"t": "unmanaged"},
            "versions": {"agent": "protocol-test", "xray": null, "phantun": null, "wg_tools": null, "wg_backend": null},
            "spool": {"observation": 0, "usage": 0, "dropped": 0},
            "online_sources": entries.iter().map(|(ingress, protocols)| json!({
                "label": format!("alice@platform.acme#{ingress}"),
                "sources": [{"ip": "1.1.1.1", "last_seen_unix_secs": at, "protocols": protocols}],
            })).collect::<Vec<_>>()
        })).unwrap()
    };
    db.store
        .record_node_runtime(
            "n1",
            &snapshot(
                now,
                &[
                    ("ing-a1b2", json!(["vless", "anytls"])),
                    ("ing-c3d4", json!(["hysteria2"])),
                    // An Agent must not attach its own protocol observations to another node's ingress.
                    ("ing-e5f6", json!(["vless"])),
                ],
            ),
        )
        .await
        .unwrap();
    let partial = db
        .store
        .list_user_presence(&tenant_admin("platform.acme"))
        .await
        .unwrap();
    let alice = partial
        .users
        .iter()
        .find(|user| user.user_id == "alice")
        .unwrap();
    assert_eq!(alice.state, UserPresenceState::Partial);
    assert_eq!(alice.reporting_nodes, 1);
    assert_eq!(alice.missing_nodes.len(), 1);
    assert_eq!(alice.missing_nodes[0].node_id, "n2");
    db.store
        .record_node_runtime("n2", &snapshot(now, &[("ing-e5f6", json!(["anytls"]))]))
        .await
        .unwrap();
    let current = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = current
        .users
        .iter()
        .find(|user| user.user_id == "alice")
        .unwrap();
    assert_eq!(alice.sources.len(), 1);
    assert!(alice.missing_nodes.is_empty());
    assert_eq!(alice.sources[0].node_ids, ["n1", "n2"]);
    let compact_accesses = |accesses: &[brocade_store::UserOnlineSourceAccess]| {
        accesses
            .iter()
            .map(|access| {
                json!({
                    "node_id": access.node_id,
                    "ingress_id": access.ingress_id,
                    "protocols": access.protocols,
                })
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        serde_json::Value::Array(compact_accesses(&alice.sources[0].accesses)),
        json!([
            {"node_id": "n1", "ingress_id": "ing-a1b2", "protocols": ["vless", "anytls"]},
            {"node_id": "n1", "ingress_id": "ing-c3d4", "protocols": ["hysteria2"]},
            {"node_id": "n2", "ingress_id": "ing-e5f6", "protocols": ["anytls"]},
        ])
    );
    // A newer snapshot replaces the protocol set, retires missing ingresses, and represents
    // an older Agent/Xray explicitly as unknown rather than keeping stale protocol labels.
    db.store
        .record_node_runtime("n1", &snapshot(now + 1, &[("ing-a1b2", json!(["vless"]))]))
        .await
        .unwrap();
    db.store
        .record_node_runtime(
            "n2",
            &snapshot(now + 1, &[("ing-e5f6", serde_json::Value::Null)]),
        )
        .await
        .unwrap();
    let current = db.store.list_user_presence(&system_admin()).await.unwrap();
    let alice = current
        .users
        .iter()
        .find(|user| user.user_id == "alice")
        .unwrap();
    assert_eq!(
        serde_json::Value::Array(compact_accesses(&alice.sources[0].accesses)),
        json!([
            {"node_id": "n1", "ingress_id": "ing-a1b2", "protocols": ["vless"]},
            {"node_id": "n2", "ingress_id": "ing-e5f6", "protocols": null},
        ])
    );
    // A failed malformed snapshot rolls the whole transaction back, preserving current data.
    assert!(db
        .store
        .record_node_runtime(
            "n1",
            &snapshot(now + 2, &[("ing-a1b2", json!(vec!["vless"; 9]))])
        )
        .await
        .is_err());
    let after = db.store.list_user_presence(&system_admin()).await.unwrap();
    assert_eq!(after, current);
    for invalid in [
        json!([]),
        json!({}),
        json!(["tls"]),
        json!(["vless", "vless", "vless", "vless", "vless", "vless"]),
    ] {
        assert!(
            sqlx::query("UPDATE user_online_sources SET protocols = $1 WHERE active")
                .bind(invalid)
                .execute(db.pool())
                .await
                .is_err()
        );
    }
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn online_sources_documented_compatibility_preserves_legacy_rows_and_is_repeatable() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let definition_sql = "SELECT pg_get_constraintdef(oid) FROM pg_constraint
                          WHERE conrelid = 'user_online_sources'::regclass
                            AND conname = 'user_online_sources_protocols_shape'";
    let expected: String = sqlx::query_scalar(definition_sql)
        .fetch_one(db.pool())
        .await
        .unwrap();
    sqlx::query("INSERT INTO user_online_sources
                 (node_id, tenant_id, user_id, ingress_id, source_ip, first_observed_at,
                  last_observed_at, xray_last_seen_at)
                 VALUES ('n1', 'platform.acme', 'alice', 'ing-a1b2', '1.1.1.1', now(), now(), now())")
        .execute(db.pool()).await.unwrap();
    // Simulate the pre-feature schema only in this disposable PostgreSQL container.
    sqlx::query("ALTER TABLE user_online_sources DROP COLUMN protocols")
        .execute(db.pool())
        .await
        .unwrap();
    let runbook = include_str!("../../../.agents/runbooks/console-deployment.md");
    let section = runbook.split_once("### 在线来源协议字段兼容").unwrap().1;
    let sql = section
        .split_once("```sql\n")
        .unwrap()
        .1
        .split_once("```")
        .unwrap()
        .0;
    for _ in 0..2 {
        sqlx::raw_sql(sql).execute(db.pool()).await.unwrap();
    }
    sqlx::query(
        "ALTER TABLE user_online_sources VALIDATE CONSTRAINT user_online_sources_protocols_shape",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let actual: String = sqlx::query_scalar(definition_sql)
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(
        actual, expected,
        "manual compatibility must match the fresh-install constraint"
    );
    let unknown_rows: i64 =
        sqlx::query_scalar("SELECT count(*) FROM user_online_sources WHERE protocols IS NULL")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(
        unknown_rows, 1,
        "legacy sources must survive without invented protocol data"
    );
}

async fn assert_online_source_session_constraint(pool: &PgPool) {
    for mask in 0_u8..8 {
        let result = sqlx::query(
            "UPDATE user_online_sources
                SET online_since_at = CASE WHEN $1 THEN last_observed_at ELSE NULL END,
                    session_uplink_bytes = $2,
                    session_downlink_bytes = $3",
        )
        .bind(mask & 1 != 0)
        .bind((mask & 2 != 0).then_some(0_i64))
        .bind((mask & 4 != 0).then_some(0_i64))
        .execute(pool)
        .await;
        if mask == 0 || mask == 7 {
            assert!(
                result.is_ok(),
                "complete or legacy metrics: {mask}: {result:?}"
            );
        } else {
            let error = result.expect_err("partial session metrics must be rejected");
            let database = error.as_database_error().unwrap();
            assert_eq!(database.code().as_deref(), Some("23514"));
            assert_eq!(
                database.constraint(),
                Some("user_online_sources_session_shape")
            );
        }
    }
    for invalid in [
        "UPDATE user_online_sources SET session_uplink_bytes = -1",
        "UPDATE user_online_sources SET session_downlink_bytes = -1",
        "UPDATE user_online_sources
            SET online_since_at = last_observed_at + interval '1 second'",
    ] {
        let error = sqlx::query(invalid).execute(pool).await.unwrap_err();
        assert_eq!(
            error.as_database_error().unwrap().constraint(),
            Some("user_online_sources_session_shape")
        );
    }
}

