/// A machine with no valid token may not write runtime state. The same gate as
/// `record_node_poll` — both endpoints are called unattended from the agent side, and one gate
/// missing is as good as none.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn node_runtime_report_is_rejected_without_an_active_token() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;

    let report = NodeRuntimeReport {
        observed_at_unix_secs: usage_report_base_unix(),
        certificate: Default::default(),
        versions: NodeVersions {
            unlock_ip_families: None,
            unlock_connection_trace: None,
            agent: "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef".to_owned(),
            xray: None,
            xray_installed_sha256: None,
            xray_running_sha256: None,
            xray_handoff: None,
            kernel_tls_module: None,
            phantun: None,
            openvpn: None,
            vpngate_catalog_probe_workers: None,
            wg_tools: None,
            wg_backend: None,
        },
        geodata: None,
        local_reconcile: None,
        wireguard_health: None,
        traffic: None,
        online_sources: None,
        xray_upgrade: None,
        spool: SpoolBacklog {
            observation: 0,
            usage: 0,
            load: 0,
            dropped: 0,
            usage_dropped: Some(0),
            observation_dropped: Some(0),
            load_dropped: Some(0),
        },
    };

    // No token has been signed yet
    let error = db
        .store
        .record_node_runtime("n1", &report)
        .await
        .unwrap_err();
    assert!(matches!(error, StoreError::Unauthorized(_)), "{error:?}");

    // Signed and then revoked
    db.store.issue_node_token("n1").await.unwrap();
    db.store.record_node_runtime("n1", &report).await.unwrap();
    db.store.revoke_node_token("n1").await.unwrap();
    let error = db
        .store
        .record_node_runtime("n1", &report)
        .await
        .unwrap_err();
    assert!(matches!(error, StoreError::Unauthorized(_)), "{error:?}");
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn mtproxy_compatibility_matches_fresh_schema_and_preserves_existing_rows() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;

    let schema_signature = "SELECT jsonb_build_object(
        'columns', (SELECT jsonb_agg(jsonb_build_object(
            'table', table_name, 'name', column_name, 'type', data_type,
            'nullable', is_nullable, 'default', column_default
        ) ORDER BY table_name, column_name)
        FROM information_schema.columns
        WHERE table_schema = 'public' AND (table_name, column_name) IN (
            ('control_state', 'port_mtproto_base'), ('ingresses', 'mtproto_port')
        )),
        'constraints', (SELECT jsonb_agg(jsonb_build_object(
            'table', relname, 'name', conname, 'validated', convalidated,
            'definition', pg_get_constraintdef(pg_constraint.oid)
        ) ORDER BY relname, conname)
        FROM pg_constraint JOIN pg_class ON pg_class.oid = conrelid
        WHERE conname IN (
            'control_state_port_mtproto_base_range',
            'ingresses_mtproto_port_range',
            'ingresses_mtproto_vless_port_distinct',
            'ingresses_mtproto_anytls_port_distinct',
            'ingresses_mtproto_vless_encryption_port_distinct',
            'ingresses_has_a_wire',
            'user_online_sources_protocols_shape'
        ))
    )";
    let expected: serde_json::Value = sqlx::query_scalar(schema_signature)
        .fetch_one(db.pool())
        .await
        .unwrap();

    sqlx::raw_sql(
        "ALTER TABLE user_online_sources DROP CONSTRAINT user_online_sources_protocols_shape;
         ALTER TABLE user_online_sources ADD CONSTRAINT user_online_sources_protocols_shape CHECK (
             protocols IS NULL OR CASE WHEN jsonb_typeof(protocols) = 'array' THEN
                 jsonb_array_length(protocols) BETWEEN 1 AND 4
                 AND protocols <@ '[\"vless\", \"anytls\", \"hysteria2\", \"unknown\"]'::jsonb
             ELSE FALSE END
         );
         ALTER TABLE ingresses
             DROP CONSTRAINT ingresses_mtproto_port_range,
             DROP CONSTRAINT ingresses_mtproto_vless_port_distinct,
             DROP CONSTRAINT ingresses_mtproto_anytls_port_distinct,
             DROP CONSTRAINT ingresses_mtproto_vless_encryption_port_distinct,
             DROP CONSTRAINT ingresses_has_a_wire;
         ALTER TABLE ingresses DROP COLUMN mtproto_port;
         ALTER TABLE ingresses ADD CONSTRAINT ingresses_has_a_wire CHECK (
             transport_kind IS NOT NULL OR anytls_enabled OR hy2_enabled
             OR vless_encryption_port IS NOT NULL
         );
         ALTER TABLE control_state DROP CONSTRAINT control_state_port_mtproto_base_range;
         ALTER TABLE control_state DROP COLUMN port_mtproto_base;",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let compatibility = include_str!("../../../scripts/compat-mtproxy.sql")
        .replace("\\set ON_ERROR_STOP on", "")
        .replace("SET LOCAL ROLE :\"app_role\";", "SET LOCAL ROLE postgres;");
    sqlx::raw_sql(&compatibility)
        .execute(db.pool())
        .await
        .unwrap();

    let actual: serde_json::Value = sqlx::query_scalar(schema_signature)
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(actual, expected);
    let port_base: i32 = sqlx::query_scalar("SELECT port_mtproto_base FROM control_state")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(port_base, 28_800);
    let populated_ingresses: i64 =
        sqlx::query_scalar("SELECT count(*) FROM ingresses WHERE mtproto_port IS NOT NULL")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(populated_ingresses, 0);

    let mut connection = db.pool().acquire().await.unwrap();
    assert!(sqlx::raw_sql(&compatibility)
        .execute(&mut *connection)
        .await
        .is_err());
    sqlx::query("ROLLBACK")
        .execute(&mut *connection)
        .await
        .unwrap();
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn node_token_issue_authenticate_and_record_poll() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;

    let issued = db.store.issue_node_token("n1").await.unwrap();
    assert_eq!(issued.node_id, "n1");
    assert!(issued.token.starts_with(NODE_TOKEN_PREFIX));
    assert_eq!(
        issued.token_prefix,
        node_token_display_prefix(&issued.token)
    );

    let stored = sqlx::query(
        "SELECT token_hash, token_prefix,
                token_created_at IS NOT NULL AS created,
                token_last_used_at IS NULL AS never_used,
                token_revoked_at IS NULL AS active
         FROM node_agent_state
         WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        stored.try_get::<String, _>("token_hash").unwrap(),
        node_token_hash(&issued.token)
    );
    assert_ne!(
        stored.try_get::<String, _>("token_hash").unwrap(),
        issued.token
    );
    assert_eq!(
        stored.try_get::<String, _>("token_prefix").unwrap(),
        issued.token_prefix
    );
    assert!(stored.try_get::<bool, _>("created").unwrap());
    assert!(stored.try_get::<bool, _>("never_used").unwrap());
    assert!(stored.try_get::<bool, _>("active").unwrap());

    assert!(db
        .store
        .authenticate_node_token("broc_node_wrong")
        .await
        .unwrap()
        .is_none());

    let authenticated = db
        .store
        .authenticate_node_token(&issued.token)
        .await
        .unwrap()
        .expect("issued token should authenticate");
    assert_eq!(authenticated.node_id, "n1");
    assert_eq!(authenticated.token_prefix, Some(issued.token_prefix));

    let token_used: bool = sqlx::query(
        "SELECT token_last_used_at IS NOT NULL AS used
         FROM node_agent_state
         WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap()
    .try_get("used")
    .unwrap();
    assert!(token_used);

    db.store
        .record_node_poll("n1", Some(AGENT_BUILD))
        .await
        .unwrap();
    let poll = sqlx::query(
        "SELECT agent_version, last_poll_at IS NOT NULL AS polled
         FROM node_agent_state
         WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        poll.try_get::<Option<String>, _>("agent_version").unwrap(),
        Some(AGENT_BUILD.to_owned())
    );
    assert!(poll.try_get::<bool, _>("polled").unwrap());
}

