#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn redeem_node_enrollment_issues_node_token_and_rejects_reuse() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.acme', 'Platform Acme')")
        .execute(db.pool())
        .await
        .unwrap();
    let result = db
        .store
        .provision_node(&system_admin(), provision_node_request("n-enroll"))
        .await
        .unwrap();

    let issued = db
        .store
        .redeem_node_enrollment(&result.enrollment.token)
        .await
        .unwrap();
    assert_eq!(issued.node_id, "n-enroll");
    assert!(issued.token.starts_with(NODE_TOKEN_PREFIX));
    assert!(db
        .store
        .authenticate_node_token(&issued.token)
        .await
        .unwrap()
        .is_some());
    let waiting: String =
        sqlx::query_scalar("SELECT status FROM node_presence_state WHERE node_id = 'n-enroll'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(waiting, "waiting");
    db.store
        .record_node_poll("n-enroll", Some(AGENT_BUILD))
        .await
        .unwrap();
    let first_online: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM machine_events
          WHERE node_id = 'n-enroll'
            AND event_kind = 'node_online'
            AND previous_value = 'waiting'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(first_online, 1);

    let reused = db
        .store
        .redeem_node_enrollment(&result.enrollment.token)
        .await;
    assert!(matches!(reused, Err(StoreError::Unauthorized(_))));

    let used: bool = sqlx::query(
        "SELECT used_at IS NOT NULL AS used
         FROM node_enrollments
         WHERE node_id = 'n-enroll'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap()
    .try_get("used")
    .unwrap();
    assert!(used);
}

