#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn visitor_access_can_be_enabled_disabled_and_enabled_again() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query(
        "INSERT INTO tenants (id, name)
         VALUES ('platform', 'Platform'), ('platform.child', 'Child')",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let administrator = db
        .store
        .init_admin(AdminInitRequest {
            operator_id: "admin".to_owned(),
            display_name: "管理员".to_owned(),
            password: "admin-password".to_owned(),
        })
        .await
        .unwrap();
    assert!(db.store.public_identity().await.unwrap().is_none());

    let enabled = db
        .store
        .set_public_access(&system_admin(), true)
        .await
        .unwrap();
    assert!(enabled.public_open);
    let sessions_before: i64 = sqlx::query_scalar("SELECT count(*) FROM admin_sessions")
        .fetch_one(db.pool())
        .await
        .unwrap();
    for _ in 0..20 {
        let visitor = db.store.public_identity().await.unwrap().unwrap();
        assert_eq!(visitor.operator_id, "public");
        assert_eq!(visitor.role, AdminRole::Readonly);
        assert_eq!(visitor.tenant_scope.as_deref(), Some("platform"));
        assert!(visitor.token_prefix.is_none());
        assert!(visitor.self_user.is_none());
    }
    let sessions_after: i64 = sqlx::query_scalar("SELECT count(*) FROM admin_sessions")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(sessions_after, sessions_before);
    let tenants = db.store.list_tenants(&system_admin()).await.unwrap();
    assert!(tenants
        .tenants
        .iter()
        .all(|tenant| tenant.operator_count == 1));

    let legacy_token = "legacy-public-session-test-only";
    sqlx::query(
        "INSERT INTO admin_sessions (token_hash, operator_id, expires_at)
         VALUES ($1, 'public', now() + interval '1 hour')",
    )
    .bind(brocade_store::admin_session_token_hash(legacy_token))
    .execute(db.pool())
    .await
    .unwrap();
    assert!(db
        .store
        .authenticate_admin_session(legacy_token)
        .await
        .unwrap()
        .is_none());
    db.store.migrate().await.unwrap();
    let legacy_sessions: i64 =
        sqlx::query_scalar("SELECT count(*) FROM admin_sessions WHERE operator_id = 'public'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(legacy_sessions, 0);
    assert!(db
        .store
        .authenticate_admin_session(&administrator.session.token)
        .await
        .unwrap()
        .is_some());

    let disabled = db
        .store
        .set_public_access(&system_admin(), false)
        .await
        .unwrap();
    assert!(!disabled.public_open);
    assert!(db.store.public_identity().await.unwrap().is_none());
    assert!(db
        .store
        .set_public_access(&tenant_admin("platform"), true)
        .await
        .is_err());
    assert!(
        db.store
            .set_public_access(&system_admin(), true)
            .await
            .unwrap()
            .public_open
    );
    assert!(db.store.public_identity().await.unwrap().is_some());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn admin_operator_token_issue_authenticate_and_revoke() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.acme', 'Platform Acme')")
        .execute(db.pool())
        .await
        .unwrap();

    let invalid = db
        .store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "bad-system".to_owned(),
                display_name: "Bad System".to_owned(),
                role: AdminRole::SystemAdmin,
                tenant_scope: Some("platform.acme".to_owned()),
                password: None,
            },
        )
        .await;
    assert!(invalid.is_err(), "system-admin must not carry tenant_scope");

    let operator = db
        .store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "publisher-1".to_owned(),
                display_name: "Publisher One".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.acme".to_owned()),
                password: Some("publisher-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    assert_eq!(operator.role, AdminRole::Publisher);
    assert_eq!(operator.tenant_scope.as_deref(), Some("platform.acme"));

    let issued = db
        .store
        .issue_admin_token(&system_admin(), "publisher-1")
        .await
        .unwrap();
    assert!(issued.token.starts_with("broc_admin_"));
    assert!(db
        .store
        .authenticate_node_token(&issued.token)
        .await
        .unwrap()
        .is_none());

    let authenticated = db
        .store
        .authenticate_admin_token(&issued.token)
        .await
        .unwrap()
        .expect("issued admin token should authenticate");
    assert_eq!(authenticated.operator_id, "publisher-1");
    assert_eq!(authenticated.role, AdminRole::Publisher);
    assert_eq!(authenticated.tenant_scope.as_deref(), Some("platform.acme"));

    let first_used: Option<String> = sqlx::query_scalar(
        "SELECT token_last_used_at::text FROM admin_operators WHERE id = 'publisher-1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    db.store
        .authenticate_admin_token(&issued.token)
        .await
        .unwrap()
        .unwrap();
    let second_used: Option<String> = sqlx::query_scalar(
        "SELECT token_last_used_at::text FROM admin_operators WHERE id = 'publisher-1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(first_used, second_used, "last_used 写入应按分钟限频");

    let used: bool = sqlx::query(
        "SELECT token_last_used_at IS NOT NULL AS used
         FROM admin_operators
         WHERE id = 'publisher-1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap()
    .try_get("used")
    .unwrap();
    assert!(used);

    assert!(db
        .store
        .revoke_admin_token(&system_admin(), "publisher-1")
        .await
        .unwrap());
    assert!(db
        .store
        .authenticate_admin_token(&issued.token)
        .await
        .unwrap()
        .is_none());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn active_admin_session_slides_its_idle_expiry_without_reviving_expired_sessions() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    let login = db
        .store
        .init_admin(AdminInitRequest {
            operator_id: "admin".to_owned(),
            display_name: "Administrator".to_owned(),
            password: "admin-password".to_owned(),
        })
        .await
        .unwrap();

    sqlx::query(
        "UPDATE admin_sessions
         SET last_used_at = now() - interval '2 minutes',
             expires_at = now() + interval '1 hour'
         WHERE operator_id = 'admin'",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let authentication = db
        .store
        .authenticate_admin_session_with_refresh(&login.session.token)
        .await
        .unwrap()
        .expect("live session should authenticate");
    assert!(authentication.refreshed);
    assert_eq!(authentication.admin.operator_id, "admin");
    let extended: bool = sqlx::query_scalar(
        "SELECT expires_at > now() + interval '11 hours 59 minutes'
         FROM admin_sessions
         WHERE operator_id = 'admin'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert!(extended, "activity should restore the full idle window");

    let throttled = db
        .store
        .authenticate_admin_session_with_refresh(&login.session.token)
        .await
        .unwrap()
        .expect("recently refreshed session should remain valid");
    assert!(
        !throttled.refreshed,
        "refresh writes should remain rate-limited"
    );

    sqlx::query(
        "UPDATE admin_sessions
         SET last_used_at = now() - interval '2 minutes',
             expires_at = now() - interval '1 second'
         WHERE operator_id = 'admin'",
    )
    .execute(db.pool())
    .await
    .unwrap();
    assert!(db
        .store
        .authenticate_admin_session_with_refresh(&login.session.token)
        .await
        .unwrap()
        .is_none());
}

