#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn tenant_admin_manages_only_operator_subtree() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query(
        "INSERT INTO tenants (id, name)
         VALUES
            ('platform.acme', 'Platform Acme'),
            ('platform.acme.child', 'Platform Acme Child'),
            ('platform.other', 'Platform Other')",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let acme_admin = tenant_admin("platform.acme");
    let operator = db
        .store
        .create_admin_operator(
            &acme_admin,
            CreateAdminOperatorRequest {
                id: "acme-publisher".to_owned(),
                display_name: "Acme Publisher".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.acme.child".to_owned()),
                password: Some("publisher-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    assert_eq!(
        operator.tenant_scope.as_deref(),
        Some("platform.acme.child")
    );

    let issued = db
        .store
        .issue_admin_token(&acme_admin, "acme-publisher")
        .await
        .unwrap();
    assert_eq!(issued.operator_id, "acme-publisher");
    assert!(db
        .store
        .revoke_admin_token(&acme_admin, "acme-publisher")
        .await
        .unwrap());

    let outside = db
        .store
        .create_admin_operator(
            &acme_admin,
            CreateAdminOperatorRequest {
                id: "other-publisher".to_owned(),
                display_name: "Other Publisher".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.other".to_owned()),
                password: Some("publisher-secret".to_owned()),
            },
        )
        .await;
    assert!(matches!(outside, Err(StoreError::Forbidden(_))));

    let system = db
        .store
        .create_admin_operator(
            &acme_admin,
            CreateAdminOperatorRequest {
                id: "system-2".to_owned(),
                display_name: "System Two".to_owned(),
                role: AdminRole::SystemAdmin,
                tenant_scope: None,
                password: None,
            },
        )
        .await;
    assert!(matches!(system, Err(StoreError::Forbidden(_))));

    let public = db
        .store
        .create_admin_operator(
            &acme_admin,
            CreateAdminOperatorRequest {
                id: "public".to_owned(),
                display_name: "Public".to_owned(),
                role: AdminRole::Readonly,
                tenant_scope: Some("platform.acme".to_owned()),
                password: None,
            },
        )
        .await;
    assert!(matches!(public, Err(StoreError::Forbidden(_))));

    db.store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "other-publisher".to_owned(),
                display_name: "Other Publisher".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.other".to_owned()),
                password: Some("publisher-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    let revoke_outside = db
        .store
        .revoke_admin_token(&acme_admin, "other-publisher")
        .await;
    assert!(matches!(revoke_outside, Err(StoreError::Forbidden(_))));
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn admin_operator_password_set_reset_and_change() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.acme', 'Platform Acme')")
        .execute(db.pool())
        .await
        .unwrap();

    // A privileged account may never be made passwordless.
    let rejected = db
        .store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "editor-1".to_owned(),
                display_name: "Editor One".to_owned(),
                role: AdminRole::Editor,
                tenant_scope: Some("platform.acme".to_owned()),
                password: None,
            },
        )
        .await;
    assert!(matches!(rejected, Err(StoreError::InvalidData(_))));

    let editor = db
        .store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "editor-1".to_owned(),
                display_name: "Editor One".to_owned(),
                role: AdminRole::Editor,
                tenant_scope: Some("platform.acme".to_owned()),
                password: Some("editor-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    assert!(!editor.passwordless);
    let denied = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "editor-1".to_owned(),
            password: String::new(),
        })
        .await;
    assert!(matches!(denied, Err(StoreError::Unauthorized(_))));

    // A password given at creation means signing in immediately
    let with_password = db
        .store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "publisher-1".to_owned(),
                display_name: "Publisher One".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.acme".to_owned()),
                password: Some("initial-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    assert!(!with_password.passwordless);
    let session = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "publisher-1".to_owned(),
            password: "initial-secret".to_owned(),
        })
        .await
        .unwrap();
    assert_eq!(session.admin.role, AdminRole::Publisher);
    let publisher_token = db
        .store
        .issue_admin_token(&system_admin(), "publisher-1")
        .await
        .unwrap();

    // Changing a display name must not erase the password
    db.store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "publisher-1".to_owned(),
                display_name: "Publisher Renamed".to_owned(),
                role: AdminRole::Publisher,
                tenant_scope: Some("platform.acme".to_owned()),
                password: None,
            },
        )
        .await
        .unwrap();
    db.store
        .login_admin(AdminLoginRequest {
            operator_id: "publisher-1".to_owned(),
            password: "initial-secret".to_owned(),
        })
        .await
        .unwrap();

    // Setting a password on someone's behalf: the old password is void and the old sessions
    // with it
    let reset = db
        .store
        .reset_admin_password(&system_admin(), "editor-1")
        .await
        .unwrap();
    assert_eq!(reset.operator_id, "editor-1");
    let reset_publisher = db
        .store
        .reset_admin_password(&system_admin(), "publisher-1")
        .await
        .unwrap();
    assert!(reset_publisher.sessions_revoked >= 1);
    assert!(db
        .store
        .authenticate_admin_session(&session.session.token)
        .await
        .unwrap()
        .is_none());
    assert!(db
        .store
        .authenticate_admin_token(&publisher_token.token)
        .await
        .unwrap()
        .is_none());
    let stale = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "publisher-1".to_owned(),
            password: "initial-secret".to_owned(),
        })
        .await;
    assert!(matches!(stale, Err(StoreError::Unauthorized(_))));

    // A self-service change: a wrong old password does not change anything
    let wrong = db
        .store
        .change_admin_password(
            "editor-1",
            None,
            ChangeAdminPasswordRequest {
                current_password: "not-the-password".to_owned(),
                new_password: "chosen-by-me".to_owned(),
            },
        )
        .await;
    assert!(matches!(wrong, Err(StoreError::Unauthorized(_))));

    // The session that made the change survives; the others are dropped
    let live = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "editor-1".to_owned(),
            password: reset.password.clone(),
        })
        .await
        .unwrap();
    let elsewhere = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "editor-1".to_owned(),
            password: reset.password.clone(),
        })
        .await
        .unwrap();
    let revoked = db
        .store
        .change_admin_password(
            "editor-1",
            Some(&live.session.token),
            ChangeAdminPasswordRequest {
                current_password: reset.password.clone(),
                new_password: "chosen-by-me".to_owned(),
            },
        )
        .await
        .unwrap();
    assert_eq!(revoked, 1);
    assert!(db
        .store
        .authenticate_admin_session(&live.session.token)
        .await
        .unwrap()
        .is_some());
    assert!(db
        .store
        .authenticate_admin_session(&elsewhere.session.token)
        .await
        .unwrap()
        .is_none());
    db.store
        .login_admin(AdminLoginRequest {
            operator_id: "editor-1".to_owned(),
            password: "chosen-by-me".to_owned(),
        })
        .await
        .unwrap();

    // Too short a password is blocked on both paths
    let short = db
        .store
        .change_admin_password(
            "editor-1",
            None,
            ChangeAdminPasswordRequest {
                current_password: "chosen-by-me".to_owned(),
                new_password: "short".to_owned(),
            },
        )
        .await;
    assert!(matches!(short, Err(StoreError::InvalidData(_))));

    // A tenant-admin setting a password outside their scope must be blocked
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.other', 'Platform Other')")
        .execute(db.pool())
        .await
        .unwrap();
    db.store
        .create_admin_operator(
            &system_admin(),
            CreateAdminOperatorRequest {
                id: "other-editor".to_owned(),
                display_name: "Other Editor".to_owned(),
                role: AdminRole::Editor,
                tenant_scope: Some("platform.other".to_owned()),
                password: Some("editor-secret".to_owned()),
            },
        )
        .await
        .unwrap();
    let acme_admin = tenant_admin("platform.acme");
    assert!(db
        .store
        .reset_admin_password(&acme_admin, "editor-1")
        .await
        .is_ok());
    let outside = db
        .store
        .reset_admin_password(&acme_admin, "other-editor")
        .await;
    assert!(matches!(outside, Err(StoreError::Forbidden(_))));
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn user_login_is_bound_to_one_user_and_resets_in_place() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    // Deliberately use a non-`platform` tenant id: the shortcut is enabled by tenant count,
    // never by a distinguished tenant name.
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('customer.alpha', 'Customer Alpha')")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO users (tenant_id, id, uuid) VALUES
             ('customer.alpha', 'alice', gen_random_uuid()),
             ('customer.alpha', 'bob', gen_random_uuid())",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let profile = db
        .store
        .update_user_profile(
            &system_admin(),
            "customer.alpha",
            "alice",
            UpdateUserProfileRequest {
                account_type: UserAccountType::Test,
                traffic_accounting_mode: None,
            },
        )
        .await
        .unwrap();
    assert_eq!(profile.account_type, UserAccountType::Test);

    let issued = db
        .store
        .issue_user_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();
    assert_eq!(issued.operator_id, "customer.alpha/alice");
    // With one tenant the short alias is accepted, while the authenticated identity remains
    // the durable tenant-qualified operator id.
    let session = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "alice".to_owned(),
            password: issued.password.clone(),
        })
        .await
        .unwrap();
    assert_eq!(session.admin.operator_id, issued.operator_id);
    assert_eq!(session.admin.role, AdminRole::User);
    let self_user = session.admin.self_user.as_ref().unwrap();
    assert_eq!(self_user.tenant_id, "customer.alpha");
    assert_eq!(self_user.user_id, "alice");

    let actor = AdminContext::from_authenticated(&session.admin);
    let own_profile = db.store.self_user_profile(&actor).await.unwrap();
    assert_eq!(own_profile.account_type, UserAccountType::Test);

    let operators = db
        .store
        .list_admin_operators(&system_admin())
        .await
        .unwrap();
    assert!(operators
        .iter()
        .all(|operator| operator.id != issued.operator_id));

    let reset = db
        .store
        .issue_user_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();
    assert_eq!(reset.operator_id, issued.operator_id);
    assert_eq!(reset.sessions_revoked, 1);
    assert!(db
        .store
        .authenticate_admin_session(&session.session.token)
        .await
        .unwrap()
        .is_none());
    let old_password = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: issued.operator_id,
            password: issued.password,
        })
        .await;
    assert!(matches!(old_password, Err(StoreError::Unauthorized(_))));
    db.store
        .login_admin(AdminLoginRequest {
            operator_id: reset.operator_id.clone(),
            password: reset.password.clone(),
        })
        .await
        .unwrap();

    // The shortcut closes as soon as a second tenant exists; the qualified login is unchanged.
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('customer.beta', 'Customer Beta')")
        .execute(db.pool())
        .await
        .unwrap();
    let ambiguous_short = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "alice".to_owned(),
            password: reset.password.clone(),
        })
        .await;
    assert!(matches!(ambiguous_short, Err(StoreError::Unauthorized(_))));
    let qualified_session = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: reset.operator_id.clone(),
            password: reset.password.clone(),
        })
        .await
        .unwrap();

    let changed = db
        .store
        .set_user_password(
            &system_admin(),
            "customer.alpha",
            "alice",
            SetUserPasswordRequest {
                new_password: "chosen-user-password".to_owned(),
            },
        )
        .await
        .unwrap();
    assert_eq!(changed.operator_id, reset.operator_id);
    assert_eq!(changed.sessions_revoked, 2);
    assert!(db
        .store
        .authenticate_admin_session(&qualified_session.session.token)
        .await
        .unwrap()
        .is_none());
    let reset_password = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: reset.operator_id.clone(),
            password: reset.password,
        })
        .await;
    assert!(matches!(reset_password, Err(StoreError::Unauthorized(_))));
    db.store
        .login_admin(AdminLoginRequest {
            operator_id: reset.operator_id,
            password: "chosen-user-password".to_owned(),
        })
        .await
        .unwrap();

    let short = db
        .store
        .set_user_password(
            &system_admin(),
            "customer.alpha",
            "alice",
            SetUserPasswordRequest {
                new_password: "short".to_owned(),
            },
        )
        .await;
    assert!(matches!(short, Err(StoreError::InvalidData(_))));
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn user_direct_login_requires_uuid_and_rotating_token_invalidates_the_old_page() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('customer.alpha', 'Customer Alpha')")
        .execute(db.pool())
        .await
        .unwrap();
    let uuid = "2d2304da-f114-4574-8d44-625afdb1db5c";
    sqlx::query(
        "INSERT INTO users (tenant_id, id, uuid) VALUES ('customer.alpha', 'alice', $1::uuid)",
    )
    .bind(uuid)
    .execute(db.pool())
    .await
    .unwrap();

    let issued = db
        .store
        .issue_user_direct_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();
    assert_eq!(issued.uuid, uuid);
    assert_eq!(issued.operator_id, "customer.alpha/alice");
    assert!(issued.token.starts_with("broc_login_"));

    let stored: (String, Option<String>) = sqlx::query_as(
        "SELECT users.direct_login_token_hash, operator.password_hash
         FROM users
         JOIN admin_operators operator
           ON operator.user_tenant_id = users.tenant_id AND operator.user_id = users.id
         WHERE users.tenant_id = 'customer.alpha' AND users.id = 'alice'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_ne!(
        stored.0, issued.token,
        "the direct token must not be stored in plaintext"
    );
    assert_eq!(stored.0.len(), 64);
    assert!(
        stored.1.is_none(),
        "issuing a direct page must not invent a password"
    );

    let listed = db
        .store
        .list_users(&system_admin(), Some("customer.alpha"), true)
        .await
        .unwrap();
    assert!(!listed.users[0].login_enabled);
    assert!(listed.users[0].direct_login_enabled);

    let password_attempt = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: issued.operator_id.clone(),
            password: String::new(),
        })
        .await;
    assert!(matches!(password_attempt, Err(StoreError::Unauthorized(_))));
    assert!(db
        .store
        .authenticate_admin_token(&issued.token)
        .await
        .unwrap()
        .is_none());

    for request in [
        UserDirectLoginRequest {
            uuid: "00000000-0000-4000-8000-000000000000".to_owned(),
            token: issued.token.clone(),
        },
        UserDirectLoginRequest {
            uuid: issued.uuid.clone(),
            token: "broc_login_wrong".to_owned(),
        },
    ] {
        assert!(matches!(
            db.store.login_user_direct(request).await,
            Err(StoreError::Unauthorized(_))
        ));
    }

    let session = db
        .store
        .login_user_direct(UserDirectLoginRequest {
            uuid: issued.uuid.clone(),
            token: issued.token.clone(),
        })
        .await
        .unwrap();
    assert_eq!(session.admin.role, AdminRole::User);
    assert_eq!(
        session.admin.self_user.as_ref().unwrap(),
        &brocade_store::AuthenticatedUser {
            tenant_id: "customer.alpha".to_owned(),
            user_id: "alice".to_owned(),
        }
    );
    assert!(db
        .store
        .authenticate_admin_session(&session.session.token)
        .await
        .unwrap()
        .is_some());

    let replacement = db
        .store
        .issue_user_direct_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();
    assert_ne!(replacement.token, issued.token);
    assert!(matches!(
        db.store
            .login_user_direct(UserDirectLoginRequest {
                uuid: issued.uuid,
                token: issued.token,
            })
            .await,
        Err(StoreError::Unauthorized(_))
    ));
    db.store
        .login_user_direct(UserDirectLoginRequest {
            uuid: replacement.uuid.clone(),
            token: replacement.token.clone(),
        })
        .await
        .unwrap();

    let rotated = db
        .store
        .rotate_user_uuid(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();
    assert_ne!(rotated.user.uuid, replacement.uuid);
    assert!(matches!(
        db.store
            .login_user_direct(UserDirectLoginRequest {
                uuid: replacement.uuid,
                token: replacement.token,
            })
            .await,
        Err(StoreError::Unauthorized(_))
    ));
    assert!(
        !db.store
            .list_users(&system_admin(), Some("customer.alpha"), true)
            .await
            .unwrap()
            .users[0]
            .direct_login_enabled
    );

    db.store
        .issue_user_direct_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap();

    assert!(db
        .store
        .revoke_user_direct_login(&system_admin(), "customer.alpha", "alice")
        .await
        .unwrap());
    assert!(
        !db.store
            .list_users(&system_admin(), Some("customer.alpha"), true)
            .await
            .unwrap()
            .users[0]
            .direct_login_enabled
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn stateless_visitors_cannot_log_in_or_hold_api_tokens() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.acme', 'Platform Acme')")
        .execute(db.pool())
        .await
        .unwrap();
    db.store
        .set_public_access(&system_admin(), true)
        .await
        .unwrap();
    assert!(db.store.public_identity().await.unwrap().is_some());

    // The visitor configuration remains the only non-user identity without a password.
    let invalid = sqlx::query(
        "INSERT INTO admin_operators (id, display_name, role, tenant_scope, password_hash)
         VALUES ('passwordless-editor', 'Passwordless Editor', 'editor', 'platform.acme', NULL)",
    )
    .execute(db.pool())
    .await;
    assert!(invalid.is_err());
    for password in ["", "whatever"] {
        let denied = db
            .store
            .login_admin(AdminLoginRequest {
                operator_id: "public".to_owned(),
                password: password.to_owned(),
            })
            .await;
        assert!(matches!(denied, Err(StoreError::Unauthorized(_))));
    }
    let denied = db.store.issue_admin_token(&system_admin(), "public").await;
    assert!(matches!(denied, Err(StoreError::Forbidden(_))));
    let legacy_token = "legacy-public-api-token-test-only";
    sqlx::query("UPDATE admin_operators SET token_hash = $1 WHERE id = 'public'")
        .bind(brocade_store::admin_token_hash(legacy_token))
        .execute(db.pool())
        .await
        .unwrap();
    assert!(db
        .store
        .authenticate_admin_token(legacy_token)
        .await
        .unwrap()
        .is_none());

    // A credential accidentally assigned to the reserved identity must not enable account login.
    sqlx::query("UPDATE admin_operators SET password_hash = 'fixture' WHERE id = 'public'")
        .execute(db.pool())
        .await
        .unwrap();
    assert!(!db.store.admin_auth_state().await.unwrap().public_open);
    assert!(db.store.public_identity().await.unwrap().is_none());
    let denied = db
        .store
        .login_admin(AdminLoginRequest {
            operator_id: "public".to_owned(),
            password: "fixture".to_owned(),
        })
        .await;
    assert!(matches!(denied, Err(StoreError::Unauthorized(_))));
    let sessions: i64 = sqlx::query_scalar("SELECT count(*) FROM admin_sessions")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(sessions, 0);
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn tenant_path_constraint_rejects_invalid_paths() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();

    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.ac_me', 'Acme Underscore')")
        .execute(db.pool())
        .await
        .unwrap();

    let invalid = sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform.%bad', 'Bad')")
        .execute(db.pool())
        .await;
    assert!(
        invalid.is_err(),
        "tenant ids must reject SQL wildcard characters"
    );

    let empty_segment =
        sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform..bad', 'Bad')")
            .execute(db.pool())
            .await;
    assert!(
        empty_segment.is_err(),
        "tenant ids must reject empty path segments"
    );
}

