#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn later_sequence_in_the_same_second_is_a_benign_usage_noop() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let base = usage_report_base_unix();
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), base - 60).await;

    let first = db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 1, base, "boot-a:100", 100, 200),
        )
        .await
        .unwrap();
    assert_eq!(first.accepted_readings, 1);

    // A release's pre-change sample and the periodic sampler can run serially but still share
    // one whole-second timestamp. The later sequence is neither an old report nor a counter
    // regression, and must not raise the node page's rejected-counter warning.
    let same_second = db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 2, base, "boot-a:100", 130, 240),
        )
        .await
        .unwrap();
    assert_eq!(same_second.accepted_readings, 0);
    assert_eq!(same_second.inserted_samples, 0);
    assert_eq!(same_second.rejected_counters, 0);

    let later = db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 3, base + 30, "boot-a:100", 160, 300),
        )
        .await
        .unwrap();
    assert_eq!(later.accepted_readings, 1);
    assert_eq!(later.inserted_samples, 1);
    assert_eq!(later.rejected_counters, 0);

    let bytes: (i64, i64) = sqlx::query_as(
        "SELECT uplink_bytes, downlink_bytes FROM usage_samples ORDER BY id DESC LIMIT 1",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(bytes, (60, 100), "same-second growth is deferred, not lost");
    let node_rollup: (i64, i64, i64, i64) = sqlx::query_as(
        "SELECT user_uplink_bytes, user_downlink_bytes,
                relay_uplink_bytes, relay_downlink_bytes
           FROM usage_node_rollups
          WHERE tenant_id = 'platform.acme' AND node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        node_rollup,
        (60, 100, 0, 0),
        "a duplicate/no-op report must not increment the daily projection"
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn frozen_usage_generation_survives_model_removal_and_raw_retention() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let now = usage_report_base_unix();
    let old = now - 3 * 86_400;
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), old - 60).await;
    let first = db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 1, old, "boot-a:100", 100, 200),
        )
        .await
        .unwrap();
    assert_eq!(first.usage_generation_id, generation);

    // The model no longer owns this label, but a delayed report from the already-running
    // generation still has an immutable, auditable owner.
    sqlx::query("DELETE FROM grants WHERE user_id = 'alice' AND ingress_id = 'ing-a1b2'")
        .execute(db.pool())
        .await
        .unwrap();
    let delayed_report = current_usage(generation, 2, old + 30, "boot-a:100", 160, 290);
    let delayed = db
        .store
        .record_usage_report("n1", delayed_report.clone())
        .await
        .unwrap();
    assert_eq!(delayed.inserted_samples, 1);
    assert_eq!(delayed.skipped_counters, 0);

    // Three-day-old response receipts must survive the new 24-hour raw-history policy.
    sqlx::query("UPDATE usage_report_receipts SET received_at = read_at")
        .execute(db.pool())
        .await
        .unwrap();
    let deleted = db.store.prune_usage_readings(1).await.unwrap();
    assert_eq!(deleted, 2);
    assert_eq!(db.store.prune_usage_report_receipts(7).await.unwrap(), 0);
    let retry = db
        .store
        .record_usage_report("n1", delayed_report)
        .await
        .unwrap();
    assert!(
        retry.duplicate,
        "raw retention must not expire replay responses"
    );
    let heads: i64 = sqlx::query_scalar("SELECT count(*) FROM usage_counter_heads")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(
        heads, 1,
        "retention must never delete the accounting baseline"
    );

    let current = current_usage(generation, 3, now, "boot-a:100", 200, 350);
    let current = db.store.record_usage_report("n1", current).await.unwrap();
    assert_eq!(
        current.inserted_samples, 1,
        "head survives raw history pruning"
    );
    let bytes: (i64, i64) = sqlx::query_as(
        "SELECT uplink_bytes, downlink_bytes FROM usage_samples ORDER BY id DESC LIMIT 1",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(bytes, (40, 60));

    // The independent seven-day receipt sweep removes only expired responses, not raw data or
    // the permanent sequence fence. Even an expired receipt cannot make an old report bill twice.
    sqlx::query(
        "UPDATE usage_report_receipts SET received_at = now() - interval '8 days' WHERE sequence = 1",
    )
    .execute(db.pool())
    .await
    .unwrap();
    assert_eq!(db.store.prune_usage_report_receipts(7).await.unwrap(), 1);
    let counts: (i64, i64, i64) = sqlx::query_as(
        "SELECT (SELECT count(*) FROM usage_readings),
                (SELECT count(*) FROM usage_report_receipts),
                (SELECT count(*) FROM usage_counter_heads)",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(counts, (1, 2, 1));
    assert!(db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 1, old, "boot-a:100", 100, 200)
        )
        .await
        .is_err());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn raw_usage_retention_is_bounded_skips_locks_and_keeps_recent_readings() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    sqlx::query(
        "INSERT INTO usage_readings
            (node_id, label, read_at, xray_started_at, uplink_bytes, downlink_bytes)
         SELECT 'n1', 'old-' || n, now() - interval '25 hours', now() - interval '2 days', 100, 200
           FROM generate_series(1, 50002) n",
    )
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO usage_readings
            (node_id, label, read_at, xray_started_at, uplink_bytes, downlink_bytes)
         VALUES ('n1', 'recent', now() - interval '23 hours 59 minutes', now() - interval '2 days', 100, 200)",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let mut held = db.pool().begin().await.unwrap();
    sqlx::query("SELECT id FROM usage_readings WHERE label='old-1' FOR UPDATE")
        .fetch_one(&mut *held)
        .await
        .unwrap();
    assert_eq!(db.store.prune_usage_readings(1).await.unwrap(), 50_000);
    assert_eq!(db.store.prune_usage_readings(1).await.unwrap(), 1);
    held.rollback().await.unwrap();
    assert_eq!(db.store.prune_usage_readings(1).await.unwrap(), 1);
    assert_eq!(db.store.prune_usage_readings(1).await.unwrap(), 0);
    let remaining: Vec<String> = sqlx::query_scalar("SELECT label FROM usage_readings")
        .fetch_all(db.pool())
        .await
        .unwrap();
    assert_eq!(remaining, ["recent"]);
}

