// ── Automatic quota enforcement ─────────────────────────────────────────
// These cases all use the fixture's n1, which never converged, so a release is necessarily stopped
// by the gate (the plan is nothing but ApplyXray / ApplyWireGuard). That is exactly half of what
// is asserted: the model changed and not one byte was pushed to a machine.

/// Insert one already-booked usage sample into this month (app_id hardcoded, as it is frozen at
/// insert). `minute` is the window's offset within the month — (node, label, window) is the unique
/// key, so a second insert in one test needs a different window or it collides with the constraint
/// rather than the assertion.
async fn insert_month_sample(
    pool: &PgPool,
    ingress: &str,
    app: &str,
    minute: i32,
    up: i64,
    down: i64,
) {
    sqlx::query(
        "INSERT INTO usage_samples (
            window_start, window_end, node_id, tenant_id, user_id, ingress_id,
            app_id, grant_label, uplink_bytes, downlink_bytes, has_gap
         )
         VALUES (
            (date_trunc('month', now() AT TIME ZONE 'Asia/Hong_Kong')
                + make_interval(mins => $3)) AT TIME ZONE 'Asia/Hong_Kong',
            (date_trunc('month', now() AT TIME ZONE 'Asia/Hong_Kong')
                + make_interval(mins => $3 + 1)) AT TIME ZONE 'Asia/Hong_Kong',
            'n1', 'platform.acme', 'alice', $1, $2,
            'alice@platform.acme#' || $1, $4, $5, FALSE
         )",
    )
    .bind(ingress)
    .bind(app)
    .bind(minute)
    .bind(up)
    .bind(down)
    .execute(pool)
    .await
    .unwrap();
    rebuild_usage_rollups(pool).await;
}

async fn rebuild_usage_rollups(pool: &PgPool) {
    sqlx::query("DELETE FROM usage_rollups")
        .execute(pool)
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO usage_rollups (
            tenant_id, user_id, app_id, period_start, period_end,
            uplink_bytes, downlink_bytes, has_gap
         )
         SELECT s.tenant_id, s.user_id, coalesce(s.app_id, i.app_id),
                date_trunc('day', s.window_start AT TIME ZONE 'Asia/Hong_Kong')
                    AT TIME ZONE 'Asia/Hong_Kong',
                (date_trunc('day', s.window_start AT TIME ZONE 'Asia/Hong_Kong')
                    + INTERVAL '1 day') AT TIME ZONE 'Asia/Hong_Kong',
                sum(s.uplink_bytes)::bigint, sum(s.downlink_bytes)::bigint,
                bool_or(s.has_gap)
           FROM usage_samples s
           LEFT JOIN ingresses i ON i.id = s.ingress_id
          WHERE coalesce(s.app_id, i.app_id) IS NOT NULL
          GROUP BY s.tenant_id, s.user_id, coalesce(s.app_id, i.app_id),
                   date_trunc('day', s.window_start AT TIME ZONE 'Asia/Hong_Kong')",
    )
    .execute(pool)
    .await
    .unwrap();
    rebuild_usage_node_rollups(pool).await;
}

async fn rebuild_usage_node_rollups(pool: &PgPool) {
    sqlx::query("DELETE FROM usage_node_windows")
        .execute(pool)
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO usage_node_windows
            (tenant_id, node_id, window_end, user_uplink_bytes, user_downlink_bytes,
             relay_uplink_bytes, relay_downlink_bytes)
         SELECT tenant_id, node_id, window_end,
                sum(user_up), sum(user_down), sum(relay_up), sum(relay_down)
         FROM (
            SELECT tenant_id, node_id, window_end, uplink_bytes AS user_up,
                   downlink_bytes AS user_down, 0::bigint AS relay_up, 0::bigint AS relay_down
            FROM usage_samples
            UNION ALL
            SELECT tenant_id, node_id, window_end, 0, 0, uplink_bytes, downlink_bytes
            FROM usage_chain_samples
         ) detail GROUP BY tenant_id, node_id, window_end",
    )
    .execute(pool)
    .await
    .unwrap();
    sqlx::query("DELETE FROM usage_node_rollups")
        .execute(pool)
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO usage_node_rollups (
            tenant_id, node_id, period_start, period_end,
            user_uplink_bytes, user_downlink_bytes,
            relay_uplink_bytes, relay_downlink_bytes, has_gap
         )
         WITH detail AS (
             SELECT tenant_id, node_id, window_start,
                    uplink_bytes AS user_uplink_bytes,
                    downlink_bytes AS user_downlink_bytes,
                    0::bigint AS relay_uplink_bytes,
                    0::bigint AS relay_downlink_bytes,
                    has_gap
               FROM usage_samples
             UNION ALL
             SELECT tenant_id, node_id, window_start,
                    0::bigint, 0::bigint, uplink_bytes, downlink_bytes, has_gap
               FROM usage_chain_samples
         )
         SELECT tenant_id, node_id,
                date_trunc('day', window_start AT TIME ZONE 'Asia/Hong_Kong')
                    AT TIME ZONE 'Asia/Hong_Kong',
                (date_trunc('day', window_start AT TIME ZONE 'Asia/Hong_Kong')
                    + INTERVAL '1 day') AT TIME ZONE 'Asia/Hong_Kong',
                sum(user_uplink_bytes)::bigint,
                sum(user_downlink_bytes)::bigint,
                sum(relay_uplink_bytes)::bigint,
                sum(relay_downlink_bytes)::bigint,
                bool_or(has_gap)
           FROM detail
          GROUP BY tenant_id, node_id,
                   date_trunc('day', window_start AT TIME ZONE 'Asia/Hong_Kong')",
    )
    .execute(pool)
    .await
    .unwrap();
}

