#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn migration_enforces_reality_client_policy_shape() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();

    let bad_min = sqlx::query(
        "UPDATE control_state
         SET reality_min_client_ver = '1.x.0'
         WHERE id = TRUE",
    )
    .execute(db.pool())
    .await;
    assert!(bad_min.is_err(), "invalid min client version should fail");

    let bad_range = sqlx::query(
        "UPDATE control_state
         SET reality_min_client_ver = '1.10.0',
             reality_max_client_ver = '1.9.9'
         WHERE id = TRUE",
    )
    .execute(db.pool())
    .await;
    assert!(bad_range.is_err(), "min > max should fail");

    for accepted in [
        86_400_001_u64,
        brocade_core::model::MAX_REALITY_TIME_DIFF_MS,
    ] {
        let accepted = i64::try_from(accepted).unwrap();
        sqlx::query("UPDATE control_state SET reality_max_time_diff_ms=$1 WHERE id=TRUE")
            .bind(accepted)
            .execute(db.pool())
            .await
            .unwrap();
    }
    let bad_time = sqlx::query(
        "UPDATE control_state
         SET reality_max_time_diff_ms = $1
         WHERE id = TRUE",
    )
    .bind(i64::try_from(brocade_core::model::MAX_REALITY_TIME_DIFF_MS + 1).unwrap())
    .execute(db.pool())
    .await;
    assert!(bad_time.is_err(), "excessive max time diff should fail");
}

