async fn base_of(pool: &PgPool, deployment_id: i64) -> Option<i64> {
    sqlx::query("SELECT base_revision_id FROM deployments WHERE id = $1")
        .bind(deployment_id)
        .fetch_one(pool)
        .await
        .unwrap()
        .try_get::<Option<i64>, _>("base_revision_id")
        .unwrap()
}

/// Where only the fact that a deployment became the serving baseline is needed, the state is
/// written directly. Execution success alone is deliberately insufficient after activation and
/// settlement became separate dimensions.
async fn mark_succeeded(pool: &PgPool, deployment_id: i64) {
    sqlx::query(
        "UPDATE deployments
            SET status = 'succeeded',
                active = NULL,
                activation_status = 'activated',
                activated_at = now()
          WHERE id = $1",
    )
    .bind(deployment_id)
    .execute(pool)
    .await
    .unwrap();
}

fn create_deployment_request(revision_id: u64, idempotency_key: &str) -> CreateDeploymentRequest {
    CreateDeploymentRequest {
        revision_id,
        idempotency_key: idempotency_key.to_owned(),
        actor: Some("tester".to_owned()),
        note: None,
        // A configuration deployment: the button somebody presses on the release page. Grants
        // deployments are constructed separately.
        kind: DeploymentKind::Config,
    }
}

fn create_grants_deployment_request(
    revision_id: u64,
    idempotency_key: &str,
) -> CreateDeploymentRequest {
    CreateDeploymentRequest {
        kind: DeploymentKind::Grants,
        ..create_deployment_request(revision_id, idempotency_key)
    }
}

fn assert_no_alice(grants: &DesiredGrants) {
    let DesiredGrants::Present { inbounds } = grants else {
        panic!("权限目标应该是已启用的入站客户端列表");
    };
    assert!(
        inbounds
            .iter()
            .flat_map(|inbound| &inbound.clients)
            .all(|client| client.email != "alice@platform.acme#ing-a1b2"),
        "权限目标仍带着已撤销的 Alice"
    );
}

fn create_rollback_request(
    target_deployment_id: i64,
    idempotency_key: &str,
) -> CreateRollbackRequest {
    CreateRollbackRequest {
        target_deployment_id,
        idempotency_key: idempotency_key.to_owned(),
        actor: Some("tester".to_owned()),
        note: None,
    }
}

/// A release with no note gets a sentence from the server about the deployment itself.
///
/// The console used to fill this in as `console · revision 71` — repeating a number already
/// displayed to its right, so that every row of the release list read identically while the list
/// is precisely what distinguishes one deployment from another by its note.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn deployment_note_says_what_changed_and_how_many_nodes() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;

    async fn note_of(db: &TestPg, deployment_id: i64) -> String {
        sqlx::query("SELECT note FROM deployments WHERE id = $1")
            .bind(deployment_id)
            .fetch_one(db.pool())
            .await
            .unwrap()
            .try_get::<Option<String>, _>("note")
            .unwrap()
            .unwrap_or_default()
    }

    // Stamp a revision whose note is the draft layer's assembled `提交：机器 n1`.
    let applied = db
        .store
        .apply_draft(
            &system_admin(),
            vec![brocade_store::ModelOp::UpdateNode {
                node_id: "n1".to_owned(),
                node: UpdateNodeRequest {
                    name: Some("香港入口".to_owned()),
                    ..Default::default()
                },
            }],
            None,
        )
        .await
        .unwrap();

    let created = db
        .store
        .create_deployment(
            &system_admin(),
            create_deployment_request(applied.revision_id, "deploy-note-auto"),
        )
        .await
        .unwrap();
    assert_eq!(
        note_of(&db, created.deployment_id).await,
        "机器 n1 · 1 台",
        "改了什么（去掉草稿层的「提交：」）· 有产物变更的机器数"
    );

    // Notes people wrote are kept verbatim — rewriting somebody's note is worse than writing
    // none.
    let mut request = create_deployment_request(applied.revision_id, "deploy-note-written");
    request.note = Some("  港新线路换落地  ".to_owned());
    // The previous deployment on this revision still holds the single-flight lock; clear it
    // first.
    db.store
        .cancel_deployment(&system_admin(), created.deployment_id)
        .await
        .unwrap();
    let written = db
        .store
        .create_deployment(&system_admin(), request)
        .await
        .unwrap();
    assert_eq!(
        note_of(&db, written.deployment_id).await,
        "港新线路换落地",
        "人写的话只收两头空白，不动内容"
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn load_unknown_probe_peers_do_not_block_nic_windows_or_replay() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    sqlx::query("INSERT INTO nodes (id,tenant_id,name,public_ipv4,overlay_addr,wg_private_key,wg_public_key,wg_listen_port,api_port,overlay,egress_allowed,dns_kind) VALUES ('n2','platform.acme','Peer','n2.example.net','10.66.0.2','peer-private','peer-public',51820,10085,TRUE,TRUE,'system')")
        .execute(db.pool()).await.unwrap();
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let hop = |peer: &str, start: i64| {
        serde_json::from_value(json!({
            "chain_id":"app-main/chn-a1b2-c3d4", "peer_node_id":peer,
            "window_start_unix_secs":start, "window_end_unix_secs":start+30,
            "conns":1,"conns_measured":0,"btlbw_p50_bps":null,"btlbw_p90_bps":null,
            "min_rtt_us":1000,"rtt_p50_us":1000,"rtt_p90_us":1000,
            "retrans_pct":0,"busy_pct":0,"rwnd_limited_pct":0,"sndbuf_limited_pct":0
        }))
        .unwrap()
    };
    for (read_at, start) in [(now - 900, now - 930), (now, now - 30)] {
        let mut report = minute_load_report(read_at, vec![minute_load_sample(start)]);
        report.sent_at_unix_secs = Some(now);
        report.hops = vec![
            hop("n2", start),
            hop("n2:probe-v4", start),
            hop("deleted-peer", start),
            hop("n1", start),
        ];
        let accepted = db
            .store
            .record_load_report("n1", report.clone())
            .await
            .expect("an unknown optional hop must not roll back a real NIC window");
        assert_eq!(accepted.accepted_samples, 1);
        assert_eq!(accepted.accepted_hops, 1);
        assert_eq!(accepted.rejected_hops, 3);
        let retry = db.store.record_load_report("n1", report).await.unwrap();
        assert_eq!(retry.accepted_samples, 0);
        assert_eq!(retry.skipped_samples, 1);
        assert_eq!(retry.accepted_hops, 0);
        assert_eq!(retry.rejected_hops, 4);
    }
    let rows:Vec<(i64,i64)>=sqlx::query_as("SELECT nic_rx_bps,nic_tx_bps FROM node_load_samples WHERE node_id='n1' ORDER BY window_start")
        .fetch_all(db.pool()).await.unwrap();
    assert_eq!(rows, vec![(30, 60), (30, 60)]);
    let peers: Vec<String> = sqlx::query_scalar(
        "SELECT DISTINCT peer_node_id FROM node_hop_link_samples WHERE node_id='n1'",
    )
    .fetch_all(db.pool())
    .await
    .unwrap();
    assert_eq!(peers, vec!["n2"]);
    let observed:i64=sqlx::query_scalar("SELECT extract(epoch FROM load_reported_at)::bigint FROM node_agent_state WHERE node_id='n1'")
        .fetch_one(db.pool()).await.unwrap();
    assert_eq!(observed, now);
}

fn minute_load_sample(start: i64) -> LoadSample {
    serde_json::from_value(json!({
        "window_start_unix_secs": start, "window_end_unix_secs": start + 30, "has_gap": false,
        "cpu_user_pct": 10, "cpu_sys_pct": 5, "cpu_softirq_pct": 1, "cpu_peak_pct": 90,
        "cpu_steal_pct": 0, "load1": 1, "mem_available_bytes": 100, "swap_used_bytes": 0,
        "oom_kills": 1, "disk_free_bytes": 200, "disk_inode_free_pct": 90,
        "nic_rx_bps": 30, "nic_tx_bps": 60, "nic_rx_drop": 2, "nic_tx_drop": 3,
        "nic_err": 4, "conntrack_count": 8, "uptime_secs": 36000,
        "network_detail": {"tcp_retrans_segs": 3}
    }))
    .unwrap()
}

fn minute_load_report(now: i64, samples: Vec<LoadSample>) -> LoadReportRequest {
    LoadReportRequest {
        read_at_unix_secs: now,
        sent_at_unix_secs: Some(now),
        btime_unix_secs: now - 36000,
        host: serde_json::from_value(json!({
            "kernel": "test", "cpu_model": "test", "cores": 2, "cc_algo": "bbr",
            "available_cc": ["bbr"], "default_qdisc": "fq", "nic_qdisc": "fq", "nic": "eth0",
            "mem_total_bytes": 4096, "disk_total_bytes": 8192, "sysctl_managed": true,
            "arch": "x86_64", "os_pretty": "Linux", "virt": "KVM", "rmem_max": 4096,
            "wmem_max": 4096, "somaxconn": 4096
        }))
        .unwrap(),
        samples,
        processes: vec![],
        hops: vec![],
    }
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn load_minute_compaction_is_bounded_atomic_retry_safe_and_query_aligned() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let now: i64 =
        sqlx::query_scalar("SELECT extract(epoch FROM date_trunc('minute', now()))::bigint")
            .fetch_one(db.pool())
            .await
            .unwrap();
    let start = now - 6 * 3600;
    let history = (0..512)
        .map(|n| minute_load_sample(start + n * 30))
        .collect::<Vec<_>>();
    for chunk in history.chunks(60) {
        let result = db
            .store
            .record_load_report("n1", minute_load_report(now, chunk.to_vec()))
            .await
            .unwrap();
        assert_eq!(result.accepted_samples, chunk.len() as u64);
    }
    let recent = vec![
        minute_load_sample(now - 120),
        minute_load_sample(now - 90),
        minute_load_sample(now - 30),
    ];
    db.store
        .record_load_report("n1", minute_load_report(now, recent.clone()))
        .await
        .unwrap();
    let selection = LoadSeriesQuery::Absolute {
        start_unix_secs: now - 86400,
        end_unix_secs: now,
    };
    let mut before = db
        .store
        .node_load_view(&system_admin(), "n1", selection, 4096)
        .await
        .unwrap();
    assert_eq!(
        before.series.len(),
        258,
        "long reads compact recent raw windows too"
    );
    assert_eq!(before.latest_sample.as_ref(), recent.last());
    let edge_selection = LoadSeriesQuery::Absolute {
        start_unix_secs: start + 37,
        end_unix_secs: now - 85,
    };
    let mut before_edges = db
        .store
        .node_load_view(&system_admin(), "n1", edge_selection, 4096)
        .await
        .unwrap();
    let first_pass = db.store.compact_load_history().await.unwrap();
    assert!(
        first_pass > 0 && first_pass <= 240,
        "bounded maintenance batch"
    );
    let alert_before: serde_json::Value =
        sqlx::query_scalar("SELECT to_jsonb(s) FROM node_cpu_steal_state s WHERE node_id='n1'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    let (second, replay, third) = tokio::join!(
        db.store.compact_load_history(),
        db.store.record_load_report(
            "n1",
            minute_load_report(now, vec![history[0].clone(), recent[2].clone()])
        ),
        db.store.compact_load_history(),
    );
    assert_eq!(first_pass + second.unwrap() + third.unwrap(), 512);
    assert_eq!(replay.unwrap().skipped_samples, 2);
    assert_eq!(db.store.compact_load_history().await.unwrap(), 0);
    let alert_after: serde_json::Value =
        sqlx::query_scalar("SELECT to_jsonb(s) FROM node_cpu_steal_state s WHERE node_id='n1'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(
        alert_before, alert_after,
        "compaction and retries do not replay CPU steal alerts"
    );
    let counts: (i64, i64) = sqlx::query_as("SELECT count(*) FILTER (WHERE is_rollup), count(*) FILTER (WHERE NOT is_rollup) FROM node_load_samples WHERE node_id='n1'").fetch_one(db.pool()).await.unwrap();
    assert_eq!(counts, (256, 3));
    let after = db
        .store
        .node_load_view(&system_admin(), "n1", selection, 4096)
        .await
        .unwrap();
    // The concurrent replay refreshes the measured clock skew, even with identical payloads.
    // Compare all stable data, not the live server-clock diagnostic (the test can cross a second).
    before.clock_skew_secs = after.clock_skew_secs;
    before_edges.clock_skew_secs = after.clock_skew_secs;
    assert_eq!(
        before, after,
        "query results are independent of background compaction progress"
    );
    assert_eq!(
        before_edges,
        db.store
            .node_load_view(&system_admin(), "n1", edge_selection, 4096)
            .await
            .unwrap(),
        "unaligned range edges include the same complete minute before and after compaction"
    );
    let overview = db
        .store
        .node_load_overview(&system_admin(), "n1", selection, 4096)
        .await
        .unwrap();
    let metrics = db
        .store
        .node_load_metrics(
            &system_admin(),
            "n1",
            selection,
            4096,
            &["network.tcp_retrans_segs".to_owned()],
        )
        .await
        .unwrap();
    assert_eq!(
        metrics.window_end_unix_secs,
        overview
            .series
            .iter()
            .map(|s| s.window_end_unix_secs)
            .collect::<Vec<_>>()
    );
    assert_eq!(metrics.metrics["network.tcp_retrans_segs"][0], Some(6.0));
    let short = db
        .store
        .node_load_view(
            &system_admin(),
            "n1",
            LoadSeriesQuery::Absolute {
                start_unix_secs: now - 3600,
                end_unix_secs: now,
            },
            4096,
        )
        .await
        .unwrap();
    assert_eq!(
        short.series, recent,
        "one-hour history retains raw precision"
    );
    let list = db
        .store
        .list_node_load(&system_admin(), selection, 4096)
        .await
        .unwrap();
    assert_eq!(
        list.nodes
            .iter()
            .find(|v| v.node_id == "n1")
            .unwrap()
            .series,
        after.series
    );
    let latest = db
        .store
        .node_load_view(
            &system_admin(),
            "n1",
            LoadSeriesQuery::LatestWindows { windows: 4096 },
            4096,
        )
        .await
        .unwrap();
    assert_eq!(latest.latest_sample, after.latest_sample);
    assert_eq!(latest.series, after.series);
    assert_eq!(db.store.prune_load_samples(0).await.unwrap(), 259);
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn load_minute_compaction_preserves_offline_latest_and_rolls_back_on_overflow() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let now: i64 =
        sqlx::query_scalar("SELECT extract(epoch FROM date_trunc('minute', now()))::bigint")
            .fetch_one(db.pool())
            .await
            .unwrap();
    let start = now - 7200;
    let mut samples = (0..3)
        .map(|n| minute_load_sample(start + n * 30))
        .collect::<Vec<_>>();
    samples[0].oom_kills = i64::MAX as u64;
    db.store
        .record_load_report("n1", minute_load_report(now, samples.clone()))
        .await
        .unwrap();
    assert!(db.store.compact_load_history().await.is_err());
    let counts: (i64, i64) = sqlx::query_as("SELECT count(*), count(*) FILTER (WHERE is_rollup) FROM node_load_samples WHERE node_id='n1'").fetch_one(db.pool()).await.unwrap();
    assert_eq!(
        counts,
        (3, 0),
        "failed aggregation never deletes raw inputs"
    );
    let fence: i64 = sqlx::query_scalar("SELECT extract(epoch FROM sealed_through)::bigint FROM node_load_compaction_state WHERE node_id='n1'").fetch_one(db.pool()).await.unwrap();
    assert_eq!(fence, 0);
    sqlx::query("UPDATE node_load_samples SET oom_kills=1 WHERE node_id='n1'")
        .execute(db.pool())
        .await
        .unwrap();
    assert_eq!(db.store.compact_load_history().await.unwrap(), 2);
    let view = db
        .store
        .node_load_view(
            &system_admin(),
            "n1",
            LoadSeriesQuery::LatestWindows { windows: 5 },
            5,
        )
        .await
        .unwrap();
    assert_eq!(
        view.latest_sample,
        samples.last().cloned(),
        "offline latest is not widened to a minute"
    );
    assert_eq!(view.series.len(), 2);
    let replay = db
        .store
        .record_load_report("n1", minute_load_report(now, samples))
        .await
        .unwrap();
    assert_eq!(replay.skipped_samples, 3);
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn load_minute_retention_and_ingestion_do_not_race_replacement() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let now: i64 =
        sqlx::query_scalar("SELECT extract(epoch FROM date_trunc('minute', now()))::bigint")
            .fetch_one(db.pool())
            .await
            .unwrap();
    let old = (0..5)
        .map(|n| minute_load_sample(now - 7200 + n * 30))
        .collect::<Vec<_>>();
    db.store
        .record_load_report("n1", minute_load_report(now, old))
        .await
        .unwrap();
    // Start two real waiters behind the same retention lock, then release both together.
    let mut blocker = db.pool().begin().await.unwrap();
    sqlx::query("SELECT pg_advisory_xact_lock(1280262468)")
        .execute(&mut *blocker)
        .await
        .unwrap();
    let compact_store = db.store.clone();
    let compactor = tokio::spawn(async move { compact_store.compact_load_history().await });
    let prune_store = db.store.clone();
    let pruner = tokio::spawn(async move { prune_store.prune_load_samples(0).await });
    wait_for_advisory_waiters(db.pool(), 2).await;
    blocker.commit().await.unwrap();
    compactor.await.unwrap().unwrap();
    pruner.await.unwrap().unwrap();
    let remaining: i64 = sqlx::query_scalar("SELECT count(*) FROM node_load_samples")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(
        remaining, 0,
        "compaction cannot resurrect rows removed by retention"
    );
    let fresh = minute_load_sample(now - 30);
    let (compacted, report) = tokio::join!(
        db.store.compact_load_history(),
        db.store
            .record_load_report("n1", minute_load_report(now, vec![fresh.clone()]))
    );
    compacted.unwrap();
    assert_eq!(report.unwrap().accepted_samples, 1);
    let view = db
        .store
        .node_load_view(
            &system_admin(),
            "n1",
            LoadSeriesQuery::LatestWindows { windows: 10 },
            10,
        )
        .await
        .unwrap();
    assert_eq!(view.latest_sample, Some(fresh));
}

fn find_target<'a>(plan: &'a DeploymentPlan, node_id: &str) -> &'a PlannedTarget {
    plan.targets
        .iter()
        .find(|target| target.node_id == node_id)
        .unwrap()
}

fn artifact_sha(artifact: &DesiredArtifact) -> &str {
    let DesiredArtifact::Present { sha256, .. } = artifact else {
        panic!("expected present artifact");
    };
    sha256
}

fn artifact_content(artifact: &DesiredArtifact) -> &str {
    let DesiredArtifact::Present { content, .. } = artifact else {
        panic!("expected present artifact");
    };
    content
}

/// The shape that lands in `node_applied_state.grants_observed`: it carries `(email, uuid, flow)`
/// and no level.
fn grants_observed(grants: &DesiredGrants) -> serde_json::Value {
    match grants {
        DesiredGrants::Present { .. } => {
            let AppliedGrantsState::Present { inbounds } = reported_grants_from_desired(grants)
            else {
                unreachable!("Present 映射过去还是 Present")
            };
            json!({ "inbounds": inbounds })
        }
        DesiredGrants::Disabled { .. } | DesiredGrants::Unmanaged { .. } => {
            json!({ "inbounds": [] })
        }
    }
}

fn applied_report(desired: &NodeDesiredDeployment) -> TargetConvergenceReport {
    TargetConvergenceReport {
        claim_generation: desired.claim_generation,
        deployment_id: desired.deployment_id,
        node_id: desired.node_id.clone(),
        result: TargetApplyResult::Applied,
        observed_before: unknown_reported_state(),
        observed_after: reported_state_from_desired(desired),
        error: None,
        usage_activated_at_unix_secs: None,
    }
}

fn failed_recovered_report(desired: &NodeDesiredDeployment) -> TargetConvergenceReport {
    let recovered = unknown_reported_state();
    TargetConvergenceReport {
        claim_generation: desired.claim_generation,
        deployment_id: desired.deployment_id,
        node_id: desired.node_id.clone(),
        result: TargetApplyResult::FailedRecovered,
        observed_before: recovered.clone(),
        observed_after: recovered,
        error: Some("apply failed and local rollback restored previous state".to_owned()),
        usage_activated_at_unix_secs: None,
    }
}

fn reported_state_from_desired(desired: &NodeDesiredDeployment) -> ReportedNodeState {
    ReportedNodeState {
        phantun: reported_artifact_from_desired(&desired.desired.phantun),
        hy2_port_hop: reported_artifact_from_desired(&desired.desired.hy2_port_hop),
        wireguard: reported_artifact_from_desired(&desired.desired.wireguard),
        xray: reported_artifact_from_desired(&desired.desired.xray),
        grants: reported_grants_from_desired(&desired.desired.grants),
    }
}

fn reported_artifact_from_desired(artifact: &DesiredArtifact) -> AppliedArtifactState {
    match artifact {
        DesiredArtifact::Present { sha256, .. } => AppliedArtifactState::Present {
            sha256: sha256.clone(),
        },
        DesiredArtifact::Disabled { .. } => AppliedArtifactState::Disabled,
        DesiredArtifact::Unmanaged { .. } => AppliedArtifactState::Unmanaged,
    }
}

/// The observation an agent reports after converging. It must be lossy — `inbounduser` supplies
/// `(email, uuid, flow)` and no level. The fixture's ingress carries `xtls-rprx-vision`, so
/// copying the expectation wholesale here would leave a mistaken comparison on the judging side
/// untested.
fn reported_grants_from_desired(grants: &DesiredGrants) -> AppliedGrantsState {
    match grants {
        DesiredGrants::Present { inbounds } => AppliedGrantsState::Present {
            inbounds: inbounds
                .iter()
                .map(|inbound| ObservedInbound {
                    tag: inbound.tag.clone(),
                    clients: inbound
                        .clients
                        .iter()
                        .map(|client| ObservedClient {
                            email: client.email.clone(),
                            uuid: client.uuid.clone(),
                            flow: client.flow.clone(),
                        })
                        .collect(),
                })
                .collect(),
        },
        DesiredGrants::Disabled { .. } => AppliedGrantsState::Disabled,
        DesiredGrants::Unmanaged { .. } => AppliedGrantsState::Unmanaged,
    }
}

fn unknown_reported_state() -> ReportedNodeState {
    ReportedNodeState {
        hy2_port_hop: AppliedArtifactState::Unmanaged,
        phantun: AppliedArtifactState::Unmanaged,
        wireguard: AppliedArtifactState::Unknown,
        xray: AppliedArtifactState::Unknown,
        grants: AppliedGrantsState::Unknown,
    }
}

