#[tokio::test]
async fn deep_network_observation_round_trips_as_one_optional_window_detail() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform', 'Platform')")
        .execute(db.pool())
        .await
        .unwrap();
    insert_basic_node(db.pool(), "net-observe", "platform", "10.66.0.90", 51990).await;
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let network = NetworkDetailSample {
        tcp_curr_estab: Some(82),
        tcp_inuse: Some(95),
        tcp_time_wait: Some(31),
        tcp_orphan: Some(0),
        tcp_alloc: Some(142),
        tcp_mem_bytes: Some(512 * 1024),
        udp_inuse: Some(18),
        udp_mem_bytes: Some(64 * 1024),
        tcp_active_opens: Some(41),
        tcp_passive_opens: Some(36),
        tcp_attempt_fails: Some(2),
        tcp_estab_resets: Some(1),
        tcp_retrans_segs: Some(3),
        tcp_syn_retrans: Some(1),
        tcp_in_errors: Some(0),
        tcp_out_resets: Some(2),
        tcp_timeouts: Some(0),
        tcp_listen_overflows: Some(0),
        tcp_listen_drops: Some(0),
        udp_in_errors: Some(0),
        udp_no_ports: Some(1),
        udp_rcvbuf_errors: Some(0),
        udp_sndbuf_errors: Some(0),
        ..Default::default()
    };
    let disk = DiskDetailSample {
        total_bytes: Some(8 * 1024 * 1024),
        inode_total: Some(100_000),
        inode_free: Some(90_000),
        read_bps: Some(2048),
        write_bps: Some(4096),
        read_iops: Some(1.5),
        write_iops: Some(2.5),
        read_await_ms: Some(0.8),
        write_await_ms: Some(1.2),
        busy_pct: Some(12.0),
        queue_depth: Some(0.4),
        in_flight: Some(1),
        pressure_some_pct: Some(0.2),
        pressure_full_pct: Some(0.0),
    };
    let sample = LoadSample {
        window_start_unix_secs: now - 30,
        window_end_unix_secs: now,
        has_gap: false,
        cpu_user_pct: 1.0,
        cpu_sys_pct: 1.0,
        cpu_softirq_pct: 1.0,
        cpu_peak_pct: 4.0,
        cpu_steal_pct: 0.0,
        load1: 0.1,
        cpu_detail: None,
        mem_available_bytes: 1024,
        swap_used_bytes: 0,
        memory_detail: None,
        oom_kills: 0,
        disk_free_bytes: 2048,
        disk_inode_free_pct: 99.0,
        disk_detail: Some(disk.clone()),
        nic_rx_bps: 100,
        nic_tx_bps: 200,
        nic_rx_drop: 0,
        nic_tx_drop: 0,
        nic_err: 0,
        conntrack_count: Some(1200),
        network_detail: Some(network.clone()),
        uptime_secs: 3600,
    };
    let report = LoadReportRequest {
        read_at_unix_secs: now,
        sent_at_unix_secs: Some(now),
        btime_unix_secs: now - 3600,
        host: HostFacts {
            kernel: "6.8.0".to_owned(),
            cpu_model: "test".to_owned(),
            cores: 2,
            cpu_freq_max_mhz: None,
            cpu_governor: None,
            cc_algo: "bbr".to_owned(),
            available_cc: vec!["bbr".to_owned()],
            default_qdisc: "fq".to_owned(),
            nic_qdisc: "fq".to_owned(),
            nic: "eth0".to_owned(),
            nic_mtu: Some(1500),
            mem_total_bytes: 4096,
            disk_total_bytes: 8192,
            disk_mount: None,
            disk_filesystem: None,
            disk_device: None,
            disk_read_only: None,
            conntrack_max: Some(262_144),
            ephemeral_port_low: None,
            ephemeral_port_high: None,
            ephemeral_port_capacity: None,
            sysctl_managed: true,
            arch: "aarch64".to_owned(),
            os_pretty: "Linux".to_owned(),
            virt: "KVM".to_owned(),
            rmem_max: 4096,
            wmem_max: 4096,
            somaxconn: 4096,
        },
        samples: vec![sample.clone()],
        processes: vec![],
        hops: vec![],
    };
    let mut history_report = report.clone();

    let accepted = db
        .store
        .record_load_report("net-observe", report)
        .await
        .unwrap();
    assert_eq!(accepted.accepted_samples, 1);
    let view = db
        .store
        .node_load_view(
            &system_admin(),
            "net-observe",
            LoadSeriesQuery::Absolute {
                start_unix_secs: now - 60,
                end_unix_secs: now + 1,
            },
            64,
        )
        .await
        .unwrap();
    assert_eq!(view.range_start_unix_secs, now - 60);
    assert_eq!(view.range_end_unix_secs, now + 1);
    assert_eq!(view.series.len(), 1);
    assert_eq!(view.series[0].network_detail.as_ref(), Some(&network));
    assert_eq!(view.series[0].disk_detail.as_ref(), Some(&disk));
    assert_eq!(view.series[0].conntrack_count, Some(1200));
    assert_eq!(view.latest_sample.as_ref(), view.series.last());

    let overview = db
        .store
        .node_load_overview(
            &system_admin(),
            "net-observe",
            LoadSeriesQuery::Absolute {
                start_unix_secs: now - 60,
                end_unix_secs: now + 1,
            },
            64,
        )
        .await
        .unwrap();
    assert_eq!(overview.series.len(), 1);
    assert!(overview.series[0].network_detail.is_none());
    assert!(overview.series[0].disk_detail.is_none());
    assert_eq!(
        overview
            .latest_sample
            .as_ref()
            .and_then(|sample| sample.network_detail.as_ref()),
        Some(&network)
    );

    let metrics = db
        .store
        .node_load_metrics(
            &system_admin(),
            "net-observe",
            LoadSeriesQuery::Absolute {
                start_unix_secs: now - 60,
                end_unix_secs: now + 1,
            },
            64,
            &[
                "network.tcp_curr_estab".to_owned(),
                "disk.read_bps".to_owned(),
            ],
        )
        .await
        .unwrap();
    assert_eq!(metrics.window_end_unix_secs, vec![now]);
    assert_eq!(metrics.metrics["network.tcp_curr_estab"], vec![Some(82.0)]);
    assert_eq!(metrics.metrics["disk.read_bps"], vec![Some(2048.0)]);

    let stale = db
        .store
        .node_load_view(
            &system_admin(),
            "net-observe",
            LoadSeriesQuery::Absolute {
                start_unix_secs: now + 60,
                end_unix_secs: now + 120,
            },
            64,
        )
        .await
        .unwrap();
    assert!(stale.series.is_empty());
    assert_eq!(stale.latest_sample, view.latest_sample);

    let latest = db
        .store
        .node_load_view(
            &system_admin(),
            "net-observe",
            LoadSeriesQuery::LatestWindows { windows: 1 },
            64,
        )
        .await
        .unwrap();
    assert_eq!(latest.series.len(), 1);
    assert_eq!(latest.latest_sample.as_ref(), latest.series.last());
    assert_eq!(latest.range_start_unix_secs, now - 30);
    assert_eq!(latest.range_end_unix_secs, now);

    let list = db
        .store
        .list_node_load(
            &system_admin(),
            LoadSeriesQuery::LatestWindows { windows: 1 },
            64,
        )
        .await
        .unwrap();
    let listed = list
        .nodes
        .iter()
        .find(|node| node.node_id == "net-observe")
        .unwrap();
    assert_eq!(listed.series, latest.series);
    assert_eq!(listed.latest_sample, latest.latest_sample);
    assert_eq!(listed.host, latest.host);

    history_report.samples = vec![
        LoadSample {
            window_start_unix_secs: now - 90,
            window_end_unix_secs: now - 60,
            nic_rx_bps: 10,
            nic_tx_bps: 20,
            ..sample.clone()
        },
        LoadSample {
            window_start_unix_secs: now - 60,
            window_end_unix_secs: now - 30,
            nic_rx_bps: 30,
            nic_tx_bps: 40,
            ..sample
        },
    ];
    let mut delayed_report = history_report.clone();
    let accepted = db
        .store
        .record_load_report("net-observe", history_report)
        .await
        .unwrap();
    assert_eq!(accepted.accepted_samples, 2);

    let nic = db
        .store
        .list_node_nic(&system_admin(), 2, 64)
        .await
        .unwrap();
    let listed = nic
        .nodes
        .iter()
        .find(|node| node.node_id == "net-observe")
        .unwrap();
    assert_eq!(listed.series.len(), 2);
    assert_eq!(listed.series[0].window_start_unix_secs, now - 60);
    assert_eq!(listed.series[0].nic_rx_bps, 30);
    assert_eq!(listed.series[1].window_start_unix_secs, now - 30);
    assert_eq!(listed.series[1].nic_rx_bps, 100);
    let json = serde_json::to_string(listed).unwrap();
    assert!(!json.contains("cpu_detail"));
    assert!(!json.contains("network_detail"));

    delayed_report.read_at_unix_secs = now - 900;
    delayed_report.host.kernel = "stale-replay-must-not-win".to_owned();
    delayed_report.samples = vec![LoadSample {
        window_start_unix_secs: now - 930,
        window_end_unix_secs: now - 900,
        ..delayed_report.samples[0].clone()
    }];
    let replayed = db
        .store
        .record_load_report("net-observe", delayed_report)
        .await
        .unwrap();
    assert_eq!(replayed.accepted_samples, 1);
    let current_host: serde_json::Value = sqlx::query_scalar(
        "SELECT load_host_facts FROM node_agent_state WHERE node_id = 'net-observe'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        current_host["kernel"], "6.8.0",
        "historical replay must fill the series without replacing current host facts"
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn sustained_cpu_steal_opens_deduplicates_and_recovers_one_machine_incident() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    sqlx::query("INSERT INTO tenants (id, name) VALUES ('platform', 'Platform')")
        .execute(db.pool())
        .await
        .unwrap();
    insert_basic_node(db.pool(), "steal-observe", "platform", "10.66.0.91", 51991).await;
    db.store
        .configure_webhook_notification_channel(true)
        .await
        .unwrap();
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let host = HostFacts {
        kernel: "6.8.0".to_owned(),
        cpu_model: "test".to_owned(),
        cores: 2,
        cpu_freq_max_mhz: None,
        cpu_governor: None,
        cc_algo: "bbr".to_owned(),
        available_cc: vec!["bbr".to_owned()],
        default_qdisc: "fq".to_owned(),
        nic_qdisc: "fq".to_owned(),
        nic: "eth0".to_owned(),
        nic_mtu: Some(1500),
        mem_total_bytes: 4096,
        disk_total_bytes: 8192,
        disk_mount: None,
        disk_filesystem: None,
        disk_device: None,
        disk_read_only: None,
        conntrack_max: Some(262_144),
        ephemeral_port_low: None,
        ephemeral_port_high: None,
        ephemeral_port_capacity: None,
        sysctl_managed: true,
        arch: "aarch64".to_owned(),
        os_pretty: "Linux".to_owned(),
        virt: "KVM".to_owned(),
        rmem_max: 4096,
        wmem_max: 4096,
        somaxconn: 4096,
    };
    let sample = |start: i64, steal: f32, has_gap: bool| LoadSample {
        window_start_unix_secs: start,
        window_end_unix_secs: start + 30,
        has_gap,
        cpu_user_pct: 1.0,
        cpu_sys_pct: 1.0,
        cpu_softirq_pct: 1.0,
        cpu_peak_pct: 4.0,
        cpu_steal_pct: steal,
        load1: 0.1,
        cpu_detail: None,
        mem_available_bytes: 1024,
        swap_used_bytes: 0,
        memory_detail: None,
        oom_kills: 0,
        disk_free_bytes: 2048,
        disk_inode_free_pct: 99.0,
        disk_detail: None,
        nic_rx_bps: 100,
        nic_tx_bps: 200,
        nic_rx_drop: 0,
        nic_tx_drop: 0,
        nic_err: 0,
        conntrack_count: Some(1200),
        network_detail: None,
        uptime_secs: 3600,
    };
    let report = |read_at_unix_secs: i64, samples: Vec<LoadSample>| LoadReportRequest {
        read_at_unix_secs,
        sent_at_unix_secs: Some(read_at_unix_secs),
        btime_unix_secs: now - 3600,
        host: host.clone(),
        samples,
        processes: vec![],
        hops: vec![],
    };

    let high = vec![sample(now - 60, 82.0, false), sample(now - 30, 89.4, false)];
    let accepted = db
        .store
        .record_load_report("steal-observe", report(now, high.clone()))
        .await
        .unwrap();
    assert_eq!(accepted.accepted_samples, 2);
    let active = db.store.machine_events(&system_admin(), 10).await.unwrap();
    assert_eq!(active.active.len(), 1);
    assert_eq!(active.active[0].incident_kind, "cpu_steal");
    assert_eq!(active.active[0].current_value, Some(89.4));
    assert_eq!(active.active[0].peak_value, Some(89.4));
    assert_eq!(active.events.len(), 1);
    assert_eq!(active.events[0].event_kind, "cpu_steal_started");
    assert_eq!(active.events[0].metric_threshold, Some(80.0));

    let duplicate = db
        .store
        .record_load_report("steal-observe", report(now, high))
        .await
        .unwrap();
    assert_eq!(duplicate.accepted_samples, 0);
    assert_eq!(
        db.store
            .machine_events(&system_admin(), 10)
            .await
            .unwrap()
            .events
            .len(),
        1,
        "a retry must not emit a second opening event"
    );

    db.store
        .record_load_report(
            "steal-observe",
            report(now + 30, vec![sample(now, 0.0, true)]),
        )
        .await
        .unwrap();
    assert_eq!(
        db.store
            .machine_events(&system_admin(), 10)
            .await
            .unwrap()
            .active
            .len(),
        1,
        "a low gap window must not recover the incident"
    );

    db.store
        .record_load_report(
            "steal-observe",
            report(
                now + 120,
                vec![
                    sample(now + 30, 79.0, false),
                    sample(now + 60, 78.0, false),
                    sample(now + 90, 77.0, false),
                ],
            ),
        )
        .await
        .unwrap();
    let recovered = db.store.machine_events(&system_admin(), 10).await.unwrap();
    assert!(recovered.active.is_empty());
    assert_eq!(recovered.events.len(), 2);
    assert_eq!(recovered.events[0].event_kind, "cpu_steal_recovered");
    assert_eq!(recovered.events[0].metric_value, Some(77.0));
    assert_eq!(recovered.events[0].metric_peak_value, Some(89.4));
    assert_eq!(recovered.events[0].metric_threshold, Some(80.0));
    let pending: i64 =
        sqlx::query_scalar("SELECT count(*) FROM notification_deliveries WHERE status = 'pending'")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(pending, 2, "opening and recovery each queue one webhook");
}

