/// Moving a domain to a different CA makes every certificate under it due again.
///
/// The operator's complaint this exists for: the directory was switched from staging to
/// production, the console showed production, and the fleet went on serving staging certificates
/// that no client trusts — because the only thing that made a certificate due was its expiry, and
/// these had months left. The account was correctly thrown away on the switch; the certificates
/// were not, and they are the part that is actually wrong.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn changing_the_ca_makes_the_certificates_it_issued_due_again() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    // Sealing refuses to store anything without a key, and the DNS credential has to be stored
    // for a domain to be issuable at all. Set here rather than expected from the environment: a
    // test that quietly skips when a variable is missing is a test that passes everywhere and
    // checks nothing.
    std::env::set_var(
        brocade_store::secrets::SECRET_KEY_ENV,
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    );

    let domain = |directory: &str| CertDomainInput {
        domain: "example.test".to_owned(),
        signing_method: Default::default(),
        dns_credential: Some("token".to_owned()),
        acme_directory: Some(directory.to_owned()),
        acme_contact: Some("ops@example.test".to_owned()),
        renew_before_days: Some(30),
    };
    let staging = "https://acme-staging-v02.api.letsencrypt.org/directory";
    let production = "https://acme-v02.api.letsencrypt.org/directory";

    let created = db
        .store
        .upsert_cert_domain(&system_admin(), domain(staging))
        .await
        .unwrap();
    let _ = &created;

    // Issued against staging, and nowhere near expiry.
    issue_certificate_for(&db, "n1", "(STAGING) Pretend Pear").await;
    assert!(
        db.store.certificates_due(0).await.unwrap().is_empty(),
        "刚签好、离过期还早，不该再排队"
    );

    db.store
        .upsert_cert_domain(&system_admin(), domain(production))
        .await
        .unwrap();

    let due = db.store.certificates_due(0).await.unwrap();
    assert_eq!(due.len(), 1, "换了 CA 之后应该重新排队：{due:#?}");
    assert_eq!(due[0].acme_directory, production);
}

/// A new entrance declares its guard explicitly, and changing what it refuses is a model change.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn an_entrance_requires_a_guard_and_changing_it_stamps_a_revision() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    db.store
        .upsert_chain(
            &system_admin(),
            "app-main",
            CreateChainRequest {
                id: "chn-b2c3-d4e5".to_owned(),
                tenant_id: "platform.acme".to_owned(),
                name: "Guard Defaults".to_owned(),
                subscription_country: None,
                note: None,
            },
        )
        .await
        .unwrap();

    let current = serde_json::json!({
        "id": "ing-b2c3",
        "chain_id": "chn-b2c3-d4e5",
        "node_id": "n1",
        "bind": "0.0.0.0",
        "port": 8443,
        "reality": {
            "fallback_mode": "global-site",
            "fallback_limits": { "mode": "off" },
            "fallback_guard": true,
            "dest": "www.example.com:443",
            "server_names": ["www.example.com"],
            "fingerprint": "chrome"
        },
        "wires": { "vless": { "kind": "vless-reality" } },
        "projection": {},
        "guard": {
            "no_private": true,
            "no_bittorrent": true,
            "no_mail": true,
            "no_udp_amplification": true,
            "tcp_and_quic_only": false,
            "cn_source_block": "ipv4-and-ipv6"
        }
    });
    let mut missing_guard = current.clone();
    missing_guard.as_object_mut().unwrap().remove("guard");
    assert!(serde_json::from_value::<CreateIngressRequest>(missing_guard).is_err());
    let request: CreateIngressRequest = serde_json::from_value(current).unwrap();

    let created = db
        .store
        .upsert_ingress(&system_admin(), "app-main", request.clone())
        .await
        .unwrap();

    let stored: (bool, bool, bool, bool, bool, String) = sqlx::query_as(
        "SELECT guard_no_private, guard_no_bittorrent, guard_no_mail,
                guard_no_udp_amplification, guard_tcp_and_quic_only,
                guard_cn_source_block
           FROM ingresses WHERE id = 'ing-b2c3'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        stored,
        (true, true, true, true, false, "ipv4-and-ipv6".to_owned())
    );

    // Re-sending the identical request burns no revision — the guard columns join the row
    // comparison rather than sitting outside it, which would have made every save look like a
    // change.
    let unchanged = db
        .store
        .upsert_ingress(&system_admin(), "app-main", request.clone())
        .await
        .unwrap();
    assert_eq!(
        unchanged.revision_id, created.revision_id,
        "一模一样地再存一次不该盖修订"
    );

    // Turning one off is a real change, and the model reads back what was asked for.
    let opened = CreateIngressRequest {
        guard: brocade_core::model::IngressGuard {
            no_bittorrent: false,
            ..Default::default()
        },
        ..request
    };
    let after = db
        .store
        .upsert_ingress(&system_admin(), "app-main", opened)
        .await
        .unwrap();
    assert!(
        after.revision_id > created.revision_id,
        "改了拦什么就是改了模型，必须盖修订"
    );

    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let ingress = snapshot
        .apps
        .iter()
        .flat_map(|app| app.ingresses.iter())
        .find(|ingress| ingress.id == "ing-b2c3")
        .expect("ing-b2c3 在快照里");
    assert!(!ingress.guard.no_bittorrent);
    assert!(ingress.guard.no_private, "没动的那几条要原样留着");
    assert_eq!(
        ingress.guard.cn_source_block,
        brocade_core::model::CnSourceBlock::Off,
        "来源阻断的三态值也要跟随整张策略保存"
    );
}

/// The column takes an https URL and nothing else.
///
/// Guarded in the store rather than left to the CHECK constraint, because the message matters: a
/// typo here points the fleet at a CA that does not exist, and the failure surfaces one node at a
/// time, half an hour apart. Self-signing is selected explicitly; its internal marker is not a
/// public-CA directory value, so an empty or sentinel directory is a refusal rather than fallback.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn the_directory_takes_an_https_url_and_nothing_else() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    std::env::set_var(
        brocade_store::secrets::SECRET_KEY_ENV,
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    );

    let with_directory = |directory: &str| CertDomainInput {
        domain: "lab.test".to_owned(),
        signing_method: Default::default(),
        dns_credential: None,
        acme_directory: Some(directory.to_owned()),
        acme_contact: None,
        renew_before_days: Some(30),
    };

    assert!(db
        .store
        .upsert_cert_domain(&system_admin(), with_directory("self-signed"))
        .await
        .is_err());
    assert!(db
        .store
        .upsert_cert_domain(&system_admin(), with_directory("http://insecure.test/dir"))
        .await
        .is_err());
    // An absent directory is refused rather than defaulted: a fleet that never chose a CA must
    // not be pointed at one, and there is no longer a setting that works with nothing supplied.
    assert!(db
        .store
        .upsert_cert_domain(
            &system_admin(),
            CertDomainInput {
                domain: "lab.test".to_owned(),
                signing_method: Default::default(),
                dns_credential: None,
                acme_directory: None,
                acme_contact: None,
                renew_before_days: Some(30),
            }
        )
        .await
        .is_err());
    assert!(db
        .store
        .upsert_cert_domain(
            &system_admin(),
            with_directory(brocade_store::ACME_LETSENCRYPT)
        )
        .await
        .is_ok());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn a_self_signed_domain_needs_no_dns_credential() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    std::env::set_var(
        brocade_store::secrets::SECRET_KEY_ENV,
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    );

    let domain = db
        .store
        .upsert_cert_domain(
            &system_admin(),
            CertDomainInput {
                domain: "private.apple.com".to_owned(),
                signing_method: brocade_store::CertificateSigningMethod::SelfSigned,
                dns_credential: None,
                acme_directory: None,
                acme_contact: None,
                renew_before_days: Some(30),
            },
        )
        .await
        .unwrap();
    assert_eq!(domain.acme_directory, brocade_store::SELF_SIGNED_DIRECTORY);
    assert!(!domain.has_credential);
    let label_id = db
        .store
        .create_cert_label(&system_admin(), &domain.id, "Self-signed", None)
        .await
        .unwrap();
    let due = db.store.certificates_due(0).await.unwrap();
    assert_eq!(due.len(), 1);
    assert_eq!(due[0].label_id, label_id);
    assert_eq!(due[0].acme_directory, brocade_store::SELF_SIGNED_DIRECTORY);

    // A freshly created certificate is still pending and has no issuing directory of its own.
    // Listing the settings page must use the group's configured method instead of trying to
    // decode that expected NULL as a string.
    let groups = db.store.cert_groups(&system_admin()).await.unwrap();
    let group = groups.iter().find(|group| group.id == label_id).unwrap();
    assert_eq!(group.certificates.len(), 1);
    assert_eq!(
        group.certificates[0].signing_method,
        brocade_store::CertificateSigningMethod::SelfSigned
    );

    let stale_root_columns: i64 = sqlx::query_scalar(
        "SELECT count(*)
           FROM information_schema.columns
          WHERE table_schema = current_schema()
            AND table_name = 'cert_domains'
            AND column_name LIKE 'self_signed_root_%'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(stale_root_columns, 0);
}

