/// Cascading deletes: deleting a middle hop removes the whole subtree reachable beneath it and
/// clears the rules referencing it; deleting the head deletes the whole chain (ingress, grants,
/// chain declaration).
///
/// Both paths are verified: the direct delete (`delete_step`, behind HTTP DELETE) and the draft
/// commit (`apply_draft` with `DeleteStep`, which is what the UI's delete takes).
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn delete_step_cascades_subtree_and_whole_chain() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    for (id, ip, wg, port) in [
        ("n2", "10.66.0.2", "wg-private-2", 51822),
        ("n3", "10.66.0.3", "wg-private-3", 51823),
        ("n4", "10.66.0.4", "wg-private-4", 51824),
    ] {
        sqlx::query(
            "INSERT INTO nodes (
                id, tenant_id, name, public_ipv4, overlay_addr,
                wg_private_key, wg_public_key, wg_listen_port,
                api_port, overlay, egress_allowed, dns_kind, dns_servers
             ) VALUES ($1, 'platform.acme', $1, $1 || '.example.net', $2::inet,
                       $3, $3 || '-pub', $4,
                       10100, TRUE, TRUE, 'servers', '[\"1.1.1.1\"]'::jsonb)",
        )
        .bind(id)
        .bind(ip)
        .bind(wg)
        .bind(port)
        .execute(db.pool())
        .await
        .unwrap();
    }
    db.store
        .upsert_chain(
            &system_admin(),
            "app-main",
            CreateChainRequest {
                id: "chn-e5f6-0718".to_owned(),
                tenant_id: "platform.acme".to_owned(),
                name: "Sub".to_owned(),
                subscription_country: None,
                note: None,
            },
        )
        .await
        .unwrap();

    // A chain must carry an ingress (chain.no-ingress is a compilation error); it sits on n1,
    // which makes n1 the head.
    sqlx::query(
        "INSERT INTO ingresses (
            id, app_id, chain_id, node_id, bind, port, front_id, transport_kind,
            reality_private_key, reality_public_key, reality_short_ids,
            reality_dest, reality_server_names, reality_flow,
            reality_fallback_mode
         ) VALUES (
            'ing-e5f6', 'app-main', 'chn-e5f6-0718', 'n1', '0.0.0.0', 8444, NULL, 'vless-reality',
            'reality-private', 'reality-public', '[\"8337a0bf\"]'::jsonb,
            'www.example.com:443', '[\"www.example.com\"]'::jsonb, 'xtls-rprx-vision',
            'custom-site'
         )",
    )
    .execute(db.pool())
    .await
    .unwrap();

    async fn put(db: &TestPg, chain: &str, node: &str, to: &[&str]) {
        let mut rules = to
            .iter()
            .map(|to| Rule {
                dest_match: DestMatch::Any,
                action: Action::Forward {
                    to: to.to_string(),
                    dial: HopDial::Overlay,
                    pool: HopPool::None,
                },
            })
            .collect::<Vec<_>>();
        if to.is_empty() {
            rules.push(Rule {
                dest_match: DestMatch::Any,
                action: Action::Egress { send_through: None },
            });
        }
        put_step_draft(
            db,
            "app-main",
            chain,
            node,
            PutStepRequest {
                accept: Some(StepAcceptRequest {
                    uuid: None,
                    label: None,
                }),
                hop_in: Some(HopInRequest {
                    port: 20000,
                    security: Some(HopWireRequest::Encryption),
                }),
                rules,
                note: None,
            },
        )
        .await;
    }
    async fn steps_of(db: &TestPg, chain: &str) -> Vec<String> {
        sqlx::query("SELECT node_id FROM steps WHERE chain_id = $1 ORDER BY node_id")
            .bind(chain)
            .fetch_all(db.pool())
            .await
            .unwrap()
            .iter()
            .map(|row| row.try_get::<String, _>("node_id").unwrap())
            .collect()
    }
    async fn forward_targets(db: &TestPg, chain: &str, node: &str) -> Vec<String> {
        let rules: serde_json::Value =
            sqlx::query("SELECT rules FROM steps WHERE chain_id = $1 AND node_id = $2")
                .bind(chain)
                .bind(node)
                .fetch_one(db.pool())
                .await
                .unwrap()
                .try_get("rules")
                .unwrap();
        rules
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|rule| {
                rule.get("a")?.get("t")?.as_str().and_then(|t| {
                    (t == "forward")
                        .then(|| rule["a"]["to"].as_str().unwrap_or_default().to_owned())
                })
            })
            .collect()
    }

    // ── (1) Deleting a middle hop: the whole subtree is removed and references cleared ──
    // n1 → n2 → n3, with n2 also forking to n4. Deleting n2 removes the n2/n3/n4 rows and clears
    // the Forward → n2 entry from n1's rule table.
    put(&db, "chn-e5f6-0718", "n1", &["n2"]).await;
    put(&db, "chn-e5f6-0718", "n2", &["n3", "n4"]).await;
    put(&db, "chn-e5f6-0718", "n3", &[]).await;
    put(&db, "chn-e5f6-0718", "n4", &[]).await;

    let removed = db
        .store
        .delete_step(&system_admin(), "app-main", "chn-e5f6-0718", "n2")
        .await
        .unwrap();
    assert!(removed.deleted, "删中间跳必须真删掉东西");
    assert!(!removed.chain_removed);
    assert_eq!(removed.removed_steps, vec!["n2", "n3", "n4"]);
    assert_eq!(
        steps_of(&db, "chn-e5f6-0718").await,
        vec!["n1"],
        "子树之外只剩 n1"
    );
    assert!(
        forward_targets(&db, "chn-e5f6-0718", "n1").await.is_empty(),
        "n1 规则表里指向 n2 的 Forward 必须被清掉"
    );

    // After the delete the compile must be green: no dangling references and no unreachable
    // members.
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let output = compile(&snapshot);
    assert_eq!(output.summary.errors, 0, "{:#?}", output.diagnostics);

    // Idempotent: deleting again is a no-op and the revision number falls back.
    let again = db
        .store
        .delete_step(&system_admin(), "app-main", "chn-e5f6-0718", "n2")
        .await
        .unwrap();
    assert!(!again.deleted);

    // ── (2) Deleting the head: the whole chain goes (declaration, ingress, grants) ──
    // chn-a1b2-c3d4's ingress ing-a1b2 sits on n1, which makes n1 the head.
    // A historical usage row referencing ing-a1b2 is inserted first: since 0001's section 0026,
    // usage_samples has no foreign key to ingresses, and a record of historical fact does not
    // block deleting the model.
    sqlx::query(
        "INSERT INTO usage_samples (
            sampled_at, window_start, window_end, node_id, tenant_id, user_id,
            ingress_id, grant_label, uplink_bytes, downlink_bytes
         ) VALUES (now(), now() - interval '1 hour', now(), 'n1',
                   'platform.acme', 'alice', 'ing-a1b2', 'alice@ing-a1b2', 100, 200)",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let head = db
        .store
        .delete_step(&system_admin(), "app-main", "chn-a1b2-c3d4", "n1")
        .await
        .unwrap();
    assert!(head.deleted);
    assert!(head.chain_removed, "删链头 = 整条链删除");
    assert_eq!(head.removed_steps, vec!["n1"], "chn-a1b2-c3d4 链的成员清单");

    let chains_left: i64 = sqlx::query("SELECT count(*) FROM chains WHERE id = 'chn-a1b2-c3d4'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    assert_eq!(chains_left, 0, "链声明随链头删除一起消失");
    let ingresses_left: i64 = sqlx::query("SELECT count(*) FROM ingresses WHERE id = 'ing-a1b2'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    assert_eq!(ingresses_left, 0, "接入面随链删除");
    let grants_left: i64 = sqlx::query("SELECT count(*) FROM grants WHERE ingress_id = 'ing-a1b2'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    assert_eq!(grants_left, 0, "授权关系随接入面删除");
    let usage: Option<String> =
        sqlx::query("SELECT ingress_id::text FROM usage_samples WHERE node_id = 'n1'")
            .fetch_one(db.pool())
            .await
            .unwrap()
            .try_get(0)
            .unwrap();
    assert_eq!(
        usage.as_deref(),
        Some("ing-a1b2"),
        "历史用量样本保留，ingress_id 原值不动（0026 段起就无外键，是事实记录）"
    );

    // ── (3) The draft-commit path: the same DeleteStep op, the same cascade ──
    put(&db, "chn-e5f6-0718", "n1", &["n2"]).await;
    put(&db, "chn-e5f6-0718", "n2", &[]).await;
    let applied = db
        .store
        .apply_draft(
            &system_admin(),
            vec![brocade_store::ModelOp::DeleteStep {
                app_id: "app-main".to_owned(),
                chain_id: "chn-e5f6-0718".to_owned(),
                node_id: "n2".to_owned(),
            }],
            None,
        )
        .await
        .unwrap();
    assert_eq!(applied.changed, 1);
    assert_eq!(steps_of(&db, "chn-e5f6-0718").await, vec!["n1"]);
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let output = compile(&snapshot);
    assert_eq!(output.summary.errors, 0, "{:#?}", output.diagnostics);

    // ── (3.5) A dead chain blocks the release: the head may not exit and the subtree was removed
    // (the hole in the rule table got a Block fallback) ──
    // This is exactly the "cascade killed the chain" scenario. Compilation reports
    // chain.no-egress-path and create_deployment is blocked — the user must give the head a new
    // exit or delete the whole chain.
    sqlx::query("UPDATE nodes SET egress_allowed = FALSE WHERE id = 'n1'")
        .execute(db.pool())
        .await
        .unwrap();
    let blocked = db
        .store
        .create_deployment(
            &system_admin(),
            create_deployment_request(applied.revision_id, "deploy-dead"),
        )
        .await;
    assert!(
        matches!(&blocked, Err(StoreError::InvalidData(m)) if m.contains("deployment blocked by compiler: 1 error(s)")),
        "死链必须挡发布：{blocked:?}",
    );
    // No release happened, and the deployments table holds no row for it.
    let deployments: i64 =
        sqlx::query("SELECT count(*) FROM deployments WHERE idempotency_key = 'deploy-dead'")
            .fetch_one(db.pool())
            .await
            .unwrap()
            .try_get(0)
            .unwrap();
    assert_eq!(deployments, 0);

    // ── (4) The explicit DeleteChain draft operation: the whole chain goes without touching the
    // head, grants cleared along with it ──
    // The list page's delete button takes this path; the head detection in delete_step is merely
    // its convenience entrance.
    sqlx::query(
        "INSERT INTO grants (app_id, tenant_id, user_id, ingress_id)
         VALUES ('app-main', 'platform.acme', 'alice', 'ing-e5f6')",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let applied = db
        .store
        .apply_draft(
            &system_admin(),
            vec![brocade_store::ModelOp::DeleteChain {
                app_id: "app-main".to_owned(),
                chain_id: "chn-e5f6-0718".to_owned(),
            }],
            None,
        )
        .await
        .unwrap();
    assert_eq!(applied.changed, 1);
    let c: i64 = sqlx::query("SELECT count(*) FROM chains WHERE id = 'chn-e5f6-0718'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    let i: i64 = sqlx::query("SELECT count(*) FROM ingresses WHERE id = 'ing-e5f6'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    let g: i64 = sqlx::query("SELECT count(*) FROM grants WHERE ingress_id = 'ing-e5f6'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    let s: i64 = sqlx::query("SELECT count(*) FROM steps WHERE chain_id = 'chn-e5f6-0718'")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    assert_eq!((c, i, g, s), (0, 0, 0, 0), "链、接入面、授权、成员行全清");
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn listener_references_preserve_and_protect_the_owned_subtree() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    for (id, ip, wg, port) in [
        ("n2", "10.66.0.2", "wg-private-2", 51822),
        ("n3", "10.66.0.3", "wg-private-3", 51823),
    ] {
        sqlx::query(
            "INSERT INTO nodes (
                id, tenant_id, name, public_ipv4, overlay_addr,
                wg_private_key, wg_public_key, wg_listen_port,
                api_port, overlay, egress_allowed, dns_kind, dns_servers
             ) VALUES ($1, 'platform.acme', $1, $1 || '.example.net', $2::inet,
                       $3, $3 || '-pub', $4,
                       10100, TRUE, TRUE, 'servers', '[\"1.1.1.1\"]'::jsonb)",
        )
        .bind(id)
        .bind(ip)
        .bind(wg)
        .bind(port)
        .execute(db.pool())
        .await
        .unwrap();
    }
    let owner_chain = "chn-b2c3-d4e5";
    db.store
        .upsert_chain(
            &system_admin(),
            "app-main",
            CreateChainRequest {
                id: owner_chain.to_owned(),
                tenant_id: "platform.acme".to_owned(),
                name: "Listener owner".to_owned(),
                subscription_country: None,
                note: None,
            },
        )
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO ingresses (
            id, app_id, chain_id, node_id, bind, port, front_id, transport_kind,
            reality_private_key, reality_public_key, reality_short_ids,
            reality_dest, reality_server_names, reality_flow, reality_fallback_mode
         ) VALUES (
            'ing-b2c3', 'app-main', $1, 'n2', '0.0.0.0', 8444, NULL, 'vless-reality',
            'reality-private', 'reality-public', '[\"8337a0bf\"]'::jsonb,
            'www.example.com:443', '[\"www.example.com\"]'::jsonb,
            'xtls-rprx-vision', 'custom-site'
         )",
    )
    .bind(owner_chain)
    .execute(db.pool())
    .await
    .unwrap();

    let egress = |accept: bool, hop_in: bool| PutStepRequest {
        accept: accept.then_some(StepAcceptRequest {
            uuid: None,
            label: None,
        }),
        hop_in: hop_in.then_some(HopInRequest {
            port: 22003,
            security: Some(HopWireRequest::Encryption),
        }),
        rules: vec![Rule {
            dest_match: DestMatch::Any,
            action: Action::Egress { send_through: None },
        }],
        note: None,
    };
    put_step_draft(&db, "app-main", owner_chain, "n2", egress(false, false)).await;
    put_step_draft(&db, "app-main", owner_chain, "n3", egress(true, true)).await;
    put_step_draft(
        &db,
        "app-main",
        "chn-a1b2-c3d4",
        "n1",
        PutStepRequest {
            accept: None,
            hop_in: None,
            rules: vec![Rule {
                dest_match: DestMatch::Any,
                action: Action::ReuseListener {
                    listener: ListenerRef {
                        chain: owner_chain.to_owned(),
                        node: "n3".to_owned(),
                    },
                    dial: ListenerDial::Overlay,
                    pool: HopPool::None,
                },
            }],
            note: None,
        },
    )
    .await;

    let compiled = compile(&db.store.materialize_snapshot(None).await.unwrap());
    assert_eq!(compiled.summary.errors, 0, "{:#?}", compiled.diagnostics);

    let pruned = db
        .store
        .prune_chain(&system_admin(), "app-main", owner_chain)
        .await
        .unwrap();
    assert!(
        !pruned.removed_steps.iter().any(|node| node == "n3"),
        "外部引用是 owner 链的第二个根，不能被裁掉"
    );
    let kept: (Option<i32>, bool) = sqlx::query_as(
        "SELECT hop_in_port, accept_uuid IS NOT NULL
           FROM steps WHERE chain_id = $1 AND node_id = 'n3'",
    )
    .bind(owner_chain)
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(kept, (Some(22003), true));

    let delete_listener = db
        .store
        .delete_step(&system_admin(), "app-main", owner_chain, "n3")
        .await
        .unwrap_err();
    assert!(
        matches!(&delete_listener, StoreError::Conflict(message) if message.contains("仍被引用")),
        "{delete_listener:?}"
    );
    let delete_owner = db
        .store
        .apply_draft(
            &system_admin(),
            vec![ModelOp::DeleteChain {
                app_id: "app-main".to_owned(),
                chain_id: owner_chain.to_owned(),
            }],
            None,
        )
        .await
        .unwrap_err();
    assert!(
        matches!(&delete_owner, StoreError::Conflict(message) if message.contains("其它线路引用")),
        "{delete_owner:?}"
    );

    // Once the source rule releases the reference, ordinary pruning owns the lifecycle again.
    put_step_draft(&db, "app-main", "chn-a1b2-c3d4", "n1", egress(false, false)).await;
    let pruned = db
        .store
        .prune_chain(&system_admin(), "app-main", owner_chain)
        .await
        .unwrap();
    assert!(pruned.removed_steps.iter().any(|node| node == "n3"));
}

/// Stranded steps are removed by `PruneChain` once the whole rule tree has landed.
///
/// What this test watches is the order. The console saving a rule tree is a run of `PutStep`s
/// replayed one at a time by the draft, and every intermediate state is incomplete. The browser
/// used to compute who was stranded itself and wedge a `DeleteStep` into the middle of that run,
/// so that:
///
/// - it saw only the current table's draft while the others held the database's old rules;
/// - `DeleteStep` also clears whatever is unreachable from the head, and at that instant the new
///   target's `PutStep` had landed while the rule pointing at it had not — so the new target was
///   deleted on the spot as a dangling row.
///
/// The symptom is compilation reporting `relay.no-accept` after committing: a rule points at that
/// machine and its step is gone.
///
/// The shape now is "every `PutStep` lands, then one `PruneChain`", with the test on the server,
/// which sees the whole chain. Both stages are verified.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn prune_chain_drops_stranded_steps_after_whole_tree_lands() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    for (id, ip, wg, port) in [
        ("n2", "10.66.0.2", "wg-private-2", 51822),
        ("n3", "10.66.0.3", "wg-private-3", 51823),
        ("n4", "10.66.0.4", "wg-private-4", 51824),
    ] {
        sqlx::query(
            "INSERT INTO nodes (
                id, tenant_id, name, public_ipv4, overlay_addr,
                wg_private_key, wg_public_key, wg_listen_port,
                api_port, overlay, egress_allowed, dns_kind, dns_servers
             ) VALUES ($1, 'platform.acme', $1, $1 || '.example.net', $2::inet,
                       $3, $3 || '-pub', $4,
                       10100, TRUE, TRUE, 'servers', '[\"1.1.1.1\"]'::jsonb)",
        )
        .bind(id)
        .bind(ip)
        .bind(wg)
        .bind(port)
        .execute(db.pool())
        .await
        .unwrap();
    }

    // One PutStep draft operation. An empty `to` means exiting from this machine.
    fn put(node: &str, to: &[&str]) -> brocade_store::ModelOp {
        let mut rules = to
            .iter()
            .map(|to| Rule {
                dest_match: DestMatch::Any,
                action: Action::Forward {
                    to: to.to_string(),
                    dial: HopDial::Overlay,
                    pool: HopPool::None,
                },
            })
            .collect::<Vec<_>>();
        if to.is_empty() {
            rules.push(Rule {
                dest_match: DestMatch::Any,
                action: Action::Egress { send_through: None },
            });
        }
        brocade_store::ModelOp::PutStep {
            app_id: "app-main".to_owned(),
            chain_id: "chn-a1b2-c3d4".to_owned(),
            node_id: node.to_owned(),
            step: PutStepRequest {
                accept: Some(StepAcceptRequest {
                    uuid: None,
                    label: None,
                }),
                hop_in: Some(HopInRequest {
                    port: 20000,
                    security: Some(HopWireRequest::Encryption),
                }),
                rules,
                note: None,
            },
        }
    }
    fn put_reverse(node: &str, to: &str, port: u16) -> brocade_store::ModelOp {
        brocade_store::ModelOp::PutStep {
            app_id: "app-main".to_owned(),
            chain_id: "chn-a1b2-c3d4".to_owned(),
            node_id: node.to_owned(),
            step: PutStepRequest {
                accept: Some(StepAcceptRequest {
                    uuid: None,
                    label: None,
                }),
                hop_in: Some(HopInRequest {
                    port,
                    security: Some(HopWireRequest::Encryption),
                }),
                rules: vec![Rule {
                    dest_match: DestMatch::Any,
                    action: Action::Forward {
                        to: to.to_owned(),
                        dial: HopDial::Reverse(IpFamily::V4),
                        pool: HopPool::None,
                    },
                }],
                note: None,
            },
        }
    }
    let prune = || brocade_store::ModelOp::PruneChain {
        app_id: "app-main".to_owned(),
        chain_id: "chn-a1b2-c3d4".to_owned(),
    };
    async fn steps_of(db: &TestPg) -> Vec<String> {
        sqlx::query("SELECT node_id FROM steps WHERE chain_id = 'chn-a1b2-c3d4' ORDER BY node_id")
            .fetch_all(db.pool())
            .await
            .unwrap()
            .iter()
            .map(|row| row.try_get::<String, _>("node_id").unwrap())
            .collect()
    }
    async fn hop_ports_of(db: &TestPg) -> Vec<(String, Option<i32>)> {
        sqlx::query(
            "SELECT node_id, hop_in_port FROM steps
              WHERE chain_id = 'chn-a1b2-c3d4' ORDER BY node_id",
        )
        .fetch_all(db.pool())
        .await
        .unwrap()
        .iter()
        .map(|row| {
            (
                row.try_get::<String, _>("node_id").unwrap(),
                row.try_get::<Option<i32>, _>("hop_in_port").unwrap(),
            )
        })
        .collect()
    }

    // Starting point: n1 (the head) → n2 → n3, with n2 also forking to n4.
    db.store
        .apply_draft(
            &system_admin(),
            vec![
                put("n1", &["n2"]),
                put("n2", &["n3", "n4"]),
                put("n3", &[]),
                put("n4", &[]),
            ],
            None,
        )
        .await
        .unwrap();
    assert_eq!(steps_of(&db).await, ["n1", "n2", "n3", "n4"]);

    // ── (1) Rerouting to a machine not yet on the chain ──
    // n1 moves from pointing at n2 to pointing at n4 (which is still n2's downstream at that
    // moment), stranding n2 and n3. Pruning after the whole run lands: n2 and n3 are removed, n4
    // stays, and the compile is green.
    db.store
        .apply_draft(&system_admin(), vec![put("n1", &["n4"]), prune()], None)
        .await
        .unwrap();
    assert_eq!(
        steps_of(&db).await,
        ["n1", "n4"],
        "n2/n3 落单摘掉；n4 是新的下游，必须留着"
    );
    assert_eq!(
        hop_ports_of(&db).await,
        [("n1".to_owned(), None), ("n4".to_owned(), Some(20000))],
        "入口不监听普通跳，残留的 hop_in 应在整链保存末尾清掉"
    );
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let output = compile(&snapshot);
    assert_eq!(output.summary.errors, 0, "{:#?}", output.diagnostics);

    // ── (2) Two tables changed together: one detaches and the other attaches ──
    // This is the relay.no-accept scenario verbatim. n1 → n2 → n3 with n2 also pointing at n4,
    // changed so that n1 attaches n4 directly and n2 keeps only n3. Not one machine should be
    // lost — n4 merely changed upstreams.
    db.store
        .apply_draft(
            &system_admin(),
            vec![
                put("n1", &["n2"]),
                put("n2", &["n3", "n4"]),
                put("n3", &[]),
                prune(),
            ],
            None,
        )
        .await
        .unwrap();
    assert_eq!(steps_of(&db).await, ["n1", "n2", "n3", "n4"]);

    db.store
        .apply_draft(
            &system_admin(),
            vec![put("n1", &["n2", "n4"]), put("n2", &["n3"]), prune()],
            None,
        )
        .await
        .unwrap();
    assert_eq!(
        steps_of(&db).await,
        ["n1", "n2", "n3", "n4"],
        "n4 换了上游，不是落单——从前这里会被误摘，然后编译报 relay.no-accept"
    );
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let output = compile(&snapshot);
    assert_eq!(output.summary.errors, 0, "{:#?}", output.diagnostics);

    // ── (3) On an already clean chain it is a no-op and the revision number falls back ──
    let before: i64 = sqlx::query("SELECT max(id) FROM revisions")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    let applied = db
        .store
        .apply_draft(&system_admin(), vec![prune()], None)
        .await
        .unwrap();
    assert_eq!(applied.changed, 0, "没有落单的就什么都不该删");
    let after: i64 = sqlx::query("SELECT max(id) FROM revisions")
        .fetch_one(db.pool())
        .await
        .unwrap()
        .try_get(0)
        .unwrap();
    assert_eq!(before, after, "空操作不留修订");

    // ── (4) Calling the HTTP path (prune_chain) directly behaves the same ──
    // Pressing "clean up stranded steps" takes this route: no draft involved, computed from the
    // database as it stands.
    db.store
        .apply_draft(&system_admin(), vec![put("n1", &["n2"])], None)
        .await
        .unwrap();
    let pruned = db
        .store
        .prune_chain(&system_admin(), "app-main", "chn-a1b2-c3d4")
        .await
        .unwrap();
    assert_eq!(pruned.removed_steps, ["n4"], "n1 不指 n4 了，它就落单了");
    assert_eq!(
        pruned.cleared_hop_ins,
        ["n1"],
        "直接清理同样会移除入口残留端口"
    );
    assert_eq!(steps_of(&db).await, ["n1", "n2", "n3"]);

    // ── (5) Reversing a hop moves the listener from `to` to `from` ──
    // n2 remains reachable and keeps forwarding to n3, but it only dials n1 for the reverse edge;
    // its old normal-hop inbound must therefore be cleared rather than retained as a fake socket.
    db.store
        .apply_draft(
            &system_admin(),
            vec![put_reverse("n1", "n2", 20005), prune()],
            None,
        )
        .await
        .unwrap();
    assert_eq!(
        hop_ports_of(&db).await,
        [
            ("n1".to_owned(), Some(20005)),
            ("n2".to_owned(), None),
            ("n3".to_owned(), Some(20000)),
        ],
        "反向上游保留监听端口，反向拨号端的旧端口清掉"
    );
}

/// Link views are scoped by visibility rather than gated by rank.
///
/// These two used to be system-admin only, on the grounds that the backbone is one global network
/// and cannot be scoped. It can: nodes have owners, and probe rows filter by node ownership. And
/// gating them costs a global read-only role — the very role that inspects with them — every last
/// number.
///
/// The two are scoped differently, and that difference is what this test watches:
/// - the node table is scoped strictly (it answers whose MTU should change, and the place to
///   change it is in view anyway);
/// - the link table keeps rows where at least one end is in view (a path's suggestion is decided
///   by both ends together, and filtering out rows whose peer is out of view raises the remaining
///   minimum — too large means large packets silently dropped).
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn link_mtu_view_is_scoped_by_tenant_not_gated_by_role() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    for id in ["platform.acme", "platform.other"] {
        sqlx::query("INSERT INTO tenants (id, name) VALUES ($1, $1)")
            .bind(id)
            .execute(db.pool())
            .await
            .unwrap();
    }
    for id in ["hk-01", "sg-01", "out-01"] {
        db.store
            .provision_node(&system_admin(), provision_node_request(id))
            .await
            .unwrap();
    }
    // out-01 moves to another branch. The tenant at provision time is fixed, and only ownership
    // moves here.
    sqlx::query("UPDATE nodes SET tenant_id = 'platform.other' WHERE id = 'out-01'")
        .execute(db.pool())
        .await
        .unwrap();
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();

    db.store
        .record_link_probe(
            "hk-01",
            LinkProbeRequest {
                probed_at_unix_secs: now,
                links: vec![
                    LinkProbe {
                        peer_node_id: "sg-01".to_owned(),
                        endpoint_host: "sg1.example.net".to_owned(),
                        status: LinkProbeStatus::Ok,
                        path_mtu: Some(1500),
                        suggested_wg_mtu: Some(1440),
                    },
                    // The cross-branch one: its peer is out of view, and it is the path holding
                    // hk-01 down
                    LinkProbe {
                        peer_node_id: "out-01".to_owned(),
                        endpoint_host: "out1.example.net".to_owned(),
                        status: LinkProbeStatus::Ok,
                        path_mtu: Some(1258),
                        suggested_wg_mtu: Some(1198),
                    },
                ],
            },
        )
        .await
        .unwrap();

    // readonly can read it too — this used to be Forbidden.
    let readonly = AdminContext::new("vis", AdminRole::Readonly, Some("platform.acme".to_owned()));
    let view = db.store.link_mtu_view(&readonly).await.unwrap();

    let ids: Vec<&str> = view.nodes.iter().map(|n| n.node_id.as_str()).collect();
    assert_eq!(ids, vec!["hk-01", "sg-01"], "节点表裁死在自己这一支");

    let hk = view.nodes.iter().find(|n| n.node_id == "hk-01").unwrap();
    assert_eq!(
        hk.suggested_mtu,
        Some(1198),
        "跨支那条路照样把建议值压下来——滤掉它的话这里会是 1440，偏大 242"
    );
    assert_eq!(hk.tightest_peer.as_deref(), Some("out-01"));
    assert_eq!(view.links.len(), 2, "两条都留着：各有一端在视野里");

    // A global operator sees everything.
    let all = db.store.link_mtu_view(&system_admin()).await.unwrap();
    assert_eq!(all.nodes.len(), 3);
}

/// A first start against a server that has no such database creates it, and a second start finds
/// it already there.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn a_missing_database_is_created_and_then_left_alone() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    let url = db.url_for("brocade_fresh_install");

    let created = PgStore::create_database_if_absent(&url)
        .await
        .expect("建库不该失败");
    assert_eq!(
        created.as_deref(),
        Some("brocade_fresh_install"),
        "第一次要报出建了哪个库——main.rs 靠这个名字把打错的 DATABASE_URL 喊出来"
    );

    assert_eq!(
        PgStore::create_database_if_absent(&url).await.unwrap(),
        None,
        "第二次不该报建过"
    );

    let store = PgStore::connect(&url).await.expect("连得上新建的库");
    store.migrate().await.expect("迁得动");
    let revisions = store
        .list_revisions(&system_admin(), 10)
        .await
        .expect("读得了");
    let baseline = revisions.revisions.first().expect("新库该有基线修订");
    assert_eq!(baseline.note.as_deref(), Some("initial schema revision"));
    assert!(baseline.current, "基线就是当前修订");
}

/// The dangerous half. "Cannot connect" covers a wrong password just as much as a missing database,
/// and mistaking one for the other would quietly stand up a second, empty database next to the real
/// one while the operator stares at a console that has lost everything.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn a_wrong_password_is_not_mistaken_for_a_missing_database() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    let wrong = db.url_for("brocade_never_created").replace(
        "postgres://postgres:postgres@",
        "postgres://postgres:not-the-password@",
    );

    let error = PgStore::create_database_if_absent(&wrong)
        .await
        .expect_err("密码错了就该报错");
    let text = error.to_string();
    assert!(
        text.contains("password") || text.contains("authenticat"),
        "报出来的该是认证失败，实际是：{text}"
    );

    let exists: bool = sqlx::query_scalar(
        "select exists (select 1 from pg_database where datname = 'brocade_never_created')",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert!(!exists, "密码错了却把库建出来了");
}

/// The nine QUIC columns, from the console request down to what the compiler reads back.
///
/// Worth a database rather than a unit test for the reason `pg_reality_guard` states: this INSERT
/// takes positional parameters, and these nine were appended after `created_revision` precisely so
/// that nothing before them shifts. A column inserted in the wrong place produces no compile error
/// and no failure anywhere else — the ingress simply comes back with its neighbour's value. Every
/// field here carries a distinct number so a swap cannot pass.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn hysteria2_quic_tuning_round_trips_field_by_field() {
    use brocade_core::model::{HysteriaBbrProfile, HysteriaQuic};

    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;

    let tuned = HysteriaQuic {
        init_stream_receive_window: Some(131_072),
        max_stream_receive_window: Some(262_144),
        init_connection_receive_window: Some(327_680),
        max_connection_receive_window: Some(655_360),
        max_idle_timeout_secs: Some(45),
        keep_alive_period_secs: Some(15),
        max_incoming_streams: Some(64),
        disable_path_mtu_discovery: true,
    };
    let face = |quic: HysteriaQuic, profile: HysteriaBbrProfile| CreateIngressRequest {
        wires: WiresRequest {
            vless_encryption: None,
            vless: None,
            anytls: None,
            hysteria2: Some(Hysteria2 {
                port: 50000,
                hop: None,
                bandwidth: HysteriaBandwidth::default(),
                congestion: HysteriaCongestion::Reno,
                bbr_profile: profile,
                quic,
                obfs: None,
                masquerade: HysteriaMasquerade::NotFound,
            }),
            mtproto: None,
        },
        id: "ing-a1b2".to_owned(),
        chain_id: "chn-a1b2-c3d4".to_owned(),
        node_id: "n1".to_owned(),
        bind: "0.0.0.0".parse().unwrap(),
        port: 8443,
        guard: brocade_core::model::IngressGuard::OPEN,
        reality: CreateRealityIngressRequest {
            fallback_mode: RealityFallbackMode::GlobalSite,
            fallback_limits: RealityFallbackLimits::Balanced,
            fallback_guard: true,
            dest: None,
            server_names: Vec::new(),
            fingerprint: None,
            flow: None,
        },
        projection: Projection::default(),
        note: None,
    };

    db.store
        .upsert_ingress(
            &system_admin(),
            "app-main",
            face(tuned, HysteriaBbrProfile::Aggressive),
        )
        .await
        .unwrap();

    // Read through the compiler's path, not the write's echo — the echo can be right while the
    // row is not.
    let read_back = || async {
        let snapshot = db.store.materialize_snapshot(None).await.unwrap();
        snapshot
            .apps
            .iter()
            .flat_map(|app| &app.ingresses)
            .find(|ingress| ingress.id == "ing-a1b2")
            .and_then(|ingress| ingress.wires.hysteria2().cloned())
            .expect("接入面还在")
    };
    let stored = read_back().await;
    assert_eq!(stored.quic, tuned, "九个字段有一个对不上就是绑定错位了");
    assert_eq!(stored.bbr_profile, HysteriaBbrProfile::Aggressive);
    assert_eq!(
        stored.congestion,
        HysteriaCongestion::Reno,
        "reno 是本次新加的第四档"
    );

    // Clearing goes back to all-absent rather than sticking at whatever landed first.
    db.store
        .upsert_ingress(
            &system_admin(),
            "app-main",
            face(HysteriaQuic::default(), HysteriaBbrProfile::Standard),
        )
        .await
        .unwrap();
    let cleared = read_back().await;
    assert_eq!(cleared.quic, HysteriaQuic::default());
    assert_eq!(cleared.bbr_profile, HysteriaBbrProfile::Standard);

    // The CHECKs are the durable half of the range rules; the compiler's diagnostic is the other.
    let below_floor = HysteriaQuic {
        init_stream_receive_window: Some(1024),
        ..HysteriaQuic::default()
    };
    let rejected = db
        .store
        .upsert_ingress(
            &system_admin(),
            "app-main",
            face(below_floor, HysteriaBbrProfile::Standard),
        )
        .await;
    assert!(rejected.is_err(), "小于 16384 的窗口应当被列约束挡下");
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn proxy_outbound_anytls_and_deletion_are_sealed_scoped_and_reference_safe() {
    std::env::set_var(
        brocade_store::secrets::SECRET_KEY_ENV,
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    );
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let request = UpsertExternalOutboundRequest {
        target_strategy: None,
        id: "custom-4444-4444".to_owned(),
        tenant_id: "platform.acme".to_owned(),
        name: "AnyTLS Proxy".to_owned(),
        address: "edge.example.com".to_owned(),
        port: 443,
        protocol: ExternalOutboundProtocol::Anytls {
            credential: "anytls-secret".to_owned(),
        },
        security: ExternalOutboundSecurity::Tls {
            allow_insecure: true,
            alpn: Vec::new(),
            ech_config_list: None,
            pinned_peer_cert_sha256: None,
            verify_peer_cert_by_name: None,
            server_name: "edge.example.com".to_owned(),
            fingerprint: "chrome".to_owned(),
        },
        note: None,
    };
    db.store
        .apply_draft(
            &system_admin(),
            vec![ModelOp::UpsertExternalOutbound {
                outbound: request.clone(),
            }],
            None,
        )
        .await
        .unwrap();
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let proxy = snapshot
        .external_outbounds
        .iter()
        .find(|o| o.id == request.id)
        .unwrap();
    assert_eq!(proxy.protocol, request.protocol);
    assert_eq!(proxy.security, request.security);
    let sealed: String =
        sqlx::query_scalar("SELECT credential_sealed FROM external_outbounds WHERE id = $1")
            .bind(&request.id)
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert!(sealed.starts_with("v1."));
    assert!(!sealed.contains("anytls-secret"));
    let redacted = db
        .store
        .redacted_snapshot(&system_admin(), None)
        .await
        .unwrap();
    let value = redacted.snapshot["external_outbounds"]
        .as_array()
        .unwrap()
        .iter()
        .find(|o| o["id"] == request.id)
        .unwrap();
    assert_eq!(value["protocol"]["v"]["credential"], "<redacted>");
    assert_eq!(value["security"]["v"]["allow_insecure"], true);
    let mut update = request.clone();
    update.protocol.set_credential("<redacted>".to_owned());
    update.name = "Updated".to_owned();
    db.store
        .apply_draft(
            &system_admin(),
            vec![ModelOp::UpsertExternalOutbound { outbound: update }],
            None,
        )
        .await
        .unwrap();
    assert_eq!(
        db.store
            .materialize_snapshot(None)
            .await
            .unwrap()
            .external_outbounds
            .iter()
            .find(|o| o.id == request.id)
            .unwrap()
            .protocol
            .credential(),
        "anytls-secret"
    );
    let delete = ModelOp::DeleteExternalOutbound {
        tenant_id: request.tenant_id.clone(),
        id: request.id.clone(),
    };
    let stranger = AdminContext::new(
        "stranger",
        brocade_store::AdminRole::TenantAdmin,
        Some("platform.other".to_owned()),
    );
    assert!(db
        .store
        .apply_draft(&stranger, vec![delete.clone()], None)
        .await
        .is_err());
    assert!(db
        .store
        .apply_draft(
            &system_admin(),
            vec![ModelOp::DeleteExternalOutbound {
                tenant_id: "platform.other".to_owned(),
                id: request.id.clone()
            }],
            None
        )
        .await
        .is_err());
    for action_key in ["action", "a"] {
        let rules = serde_json::json!([{ "m": { "t": "any" }, action_key: { "t": "proxy", "outbound": request.id } }]);
        sqlx::query("UPDATE steps SET rules = $1 WHERE node_id = 'n1'")
            .bind(rules)
            .execute(db.pool())
            .await
            .unwrap();
        let err = db
            .store
            .apply_draft(&system_admin(), vec![delete.clone()], None)
            .await
            .unwrap_err();
        assert!(err.to_string().contains("仍被规则或前置组引用"), "{err}");
    }
    sqlx::query("UPDATE steps SET rules = '[]'::jsonb WHERE node_id = 'n1'")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query("INSERT INTO fronts (id, app_id, tenant_id, name, strategy) VALUES ('proxy-front', 'app-main', 'platform.acme', 'Proxy front', 'select')").execute(db.pool()).await.unwrap();
    sqlx::query("INSERT INTO front_external_vias (front_id, outbound_id, ordinal) VALUES ('proxy-front', $1, 0)").bind(&request.id).execute(db.pool()).await.unwrap();
    assert!(db
        .store
        .apply_draft(&system_admin(), vec![delete.clone()], None)
        .await
        .unwrap_err()
        .to_string()
        .contains("仍被规则或前置组引用"));
    sqlx::query("DELETE FROM fronts WHERE id = 'proxy-front'")
        .execute(db.pool())
        .await
        .unwrap();
    // Preview rolls back; commit removes the resource and is idempotent on replay.
    db.store
        .preview_draft(&system_admin(), vec![delete.clone()])
        .await
        .unwrap();
    assert!(db
        .store
        .materialize_snapshot(None)
        .await
        .unwrap()
        .external_outbounds
        .iter()
        .any(|o| o.id == request.id));
    db.store
        .apply_draft(&system_admin(), vec![delete.clone()], None)
        .await
        .unwrap();
    assert!(!db
        .store
        .materialize_snapshot(None)
        .await
        .unwrap()
        .external_outbounds
        .iter()
        .any(|o| o.id == request.id));
    db.store
        .apply_draft(&system_admin(), vec![delete], None)
        .await
        .unwrap();
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn vless_encryption_ingress_round_trips_with_configurable_port_and_stable_keys() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    sqlx::query("UPDATE apps SET id = 'app-ab12' WHERE id = 'app-main'")
        .execute(db.pool())
        .await
        .unwrap();
    let mut ports = db
        .store
        .materialize_snapshot(None)
        .await
        .unwrap()
        .settings
        .ports;
    assert_eq!(ports.vless_encryption_base, 13800);
    ports.vless_encryption_base = 49000;
    db.store
        .update_port_settings(&system_admin(), ports)
        .await
        .unwrap();
    assert_eq!(
        db.store
            .materialize_snapshot(None)
            .await
            .unwrap()
            .settings
            .ports
            .vless_encryption_base,
        49000
    );
    let request: CreateIngressRequest = serde_json::from_value(json!({
        "id": "ing-a1b2", "chain_id": "chn-a1b2-c3d4", "node_id": "n1",
        "bind": "0.0.0.0", "port": 443,
        "reality": {
            "fallback_mode": "global-site",
            "fallback_limits": { "mode": "balanced" },
            "fallback_guard": true
        },
        "wires": { "vless_encryption": { "port": 49000 } },
        "projection": {},
        "guard": {
            "no_private": true,
            "no_bittorrent": true,
            "no_mail": true,
            "no_udp_amplification": true,
            "tcp_and_quic_only": false
        }
    }))
    .unwrap();
    let first = db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", request.clone())
        .await
        .unwrap();
    assert_eq!(first.ingress["wires"]["vless_encryption"]["port"], 49000);
    assert!(first.ingress["wires"]["vless_encryption"]
        .get("private_key")
        .is_none());
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let first_wire = snapshot.apps[0].ingresses[0]
        .wires
        .vless_encryption()
        .unwrap()
        .clone();
    assert_eq!(first_wire.private_key.len(), 43);
    assert_eq!(first_wire.public_key.len(), 43);
    assert!(snapshot.apps[0].ingresses[0].wires.vless().is_none());
    assert!(!snapshot.apps[0].ingresses[0].wires.needs_node_certificate());
    let compiled = brocade_core::compile::compile(&snapshot);
    assert!(compiled.can_publish(), "{:?}", compiled.diagnostics);
    // An unchanged save must keep the revision and both keys.
    let same = db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", request.clone())
        .await
        .unwrap();
    assert_eq!(same.revision_id, first.revision_id);
    let mut moved = request.clone();
    moved.wires.vless_encryption.as_mut().unwrap().port = 49001;
    let custom: brocade_core::model::VlessEncryptionOptions = serde_json::from_value(json!({
        "appearance": "random", "ticket_lifetime": "120-480s", "client_mode": "1rtt",
        "server_padding": "100-35-80.50-0-20.50-0-100", "client_padding": "100-40-90"
    }))
    .unwrap();
    moved.wires.vless_encryption.as_mut().unwrap().options = custom.clone();
    db.store
        .upsert_ingress(&system_admin(), "app-ab12", moved.clone())
        .await
        .unwrap();
    let snapshot = db.store.materialize_snapshot(None).await.unwrap();
    let moved_wire = snapshot.apps[0].ingresses[0]
        .wires
        .vless_encryption()
        .unwrap();
    assert_eq!(moved_wire.port, 49001);
    assert_eq!(moved_wire.options, custom);
    let echo = db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", moved.clone())
        .await
        .unwrap();
    assert_eq!(
        echo.ingress["wires"]["vless_encryption"]["options"],
        serde_json::to_value(&custom).unwrap()
    );
    let repeat = db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", moved.clone())
        .await
        .unwrap();
    assert_eq!(echo.revision_id, repeat.revision_id);
    let mut bad_options = moved.clone();
    bad_options
        .wires
        .vless_encryption
        .as_mut()
        .unwrap()
        .options
        .client_padding = "100-1-10".to_owned();
    assert!(db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", bad_options)
        .await
        .is_err());
    assert_eq!(moved_wire.private_key, first_wire.private_key);
    assert_eq!(moved_wire.public_key, first_wire.public_key);
    let mut invalid = moved;
    invalid.wires.vless_encryption.as_mut().unwrap().port = 0;
    assert!(db
        .store
        .upsert_ingress(&system_admin(), "app-ab12", invalid)
        .await
        .is_err());
}

#[tokio::test]
async fn reverse_health_settings_round_trip_and_validate() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    let mut settings = db.store.settings().await.unwrap();
    assert_eq!(
        settings.reverse_health,
        brocade_core::model::ReverseHealth::default()
    );
    settings.reverse_health.probe_interval_ms = 1500;
    settings.reverse_health.tuning.recovery_successes = 3;
    settings.reverse_health_overrides = vec![brocade_core::model::ReverseHealthOverride {
        chain: "test-chain".into(),
        from: "a".into(),
        to: "b".into(),
        health: brocade_core::model::ReverseHealth {
            tuning: brocade_core::model::ReverseHealthTuning {
                max_sessions_per_worker: 4,
                ..Default::default()
            },
            probe_interval_ms: 2000,
            health_lease_ms: 4000,
            ..Default::default()
        },
    }];
    let saved = db
        .store
        .update_settings(&system_admin(), settings.clone())
        .await
        .unwrap();
    assert_eq!(saved.settings.reverse_health, settings.reverse_health);
    assert_eq!(
        db.store.settings().await.unwrap().reverse_health_overrides,
        settings.reverse_health_overrides
    );
    let materialized = db.store.materialize_snapshot(None).await.unwrap();
    assert_eq!(
        materialized.settings.reverse_health,
        settings.reverse_health
    );
    assert_eq!(
        materialized.settings.reverse_health_overrides,
        settings.reverse_health_overrides
    );
    settings.reverse_health.probe_timeout_ms = 2000;
    assert!(db
        .store
        .update_settings(&system_admin(), settings)
        .await
        .is_err());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn traffic_accounting_mode_compatibility_preserves_legacy_rows_and_defaults() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    sqlx::raw_sql(
        "INSERT INTO node_traffic_policy (node_id, updated_by)
         VALUES ('n1', 'legacy');
         INSERT INTO node_traffic_calibrations (
             node_id, target_total_bytes, accounted_total_bytes, calibrated_by
         ) VALUES ('n1', 100, 80, 'legacy');
         INSERT INTO node_traffic_forecasts (
             node_id, day, taken_at, period_start, period_end,
             used_bytes, p50_bytes, p90_bytes
         ) VALUES ('n1', current_date, now(), current_date, current_date + 1,
                   10, 20, 30);
         ALTER TABLE users DROP COLUMN traffic_accounting_mode;
         ALTER TABLE node_traffic_policy DROP COLUMN accounting_mode;
         ALTER TABLE node_traffic_calibrations
             DROP COLUMN accounting_mode,
             DROP COLUMN accounted_rx_bytes,
             DROP COLUMN accounted_tx_bytes;
         ALTER TABLE node_traffic_forecasts DROP COLUMN accounting_mode;",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let script = include_str!("../../../scripts/compat-traffic-accounting-modes.sql")
        .lines()
        .filter(|line| !line.starts_with('\\'))
        .collect::<Vec<_>>()
        .join("\n")
        .replace(":\"app_role\"", "postgres");
    sqlx::raw_sql(&script).execute(db.pool()).await.unwrap();

    let user_mode: String = sqlx::query_scalar(
        "SELECT traffic_accounting_mode FROM users
         WHERE tenant_id = 'platform.acme' AND id = 'alice'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(user_mode, "single");
    let modes: (String, String, String) = sqlx::query_as(
        "SELECT policy.accounting_mode, calibration.accounting_mode, forecast.accounting_mode
           FROM node_traffic_policy policy
           JOIN node_traffic_calibrations calibration USING (node_id)
           JOIN node_traffic_forecasts forecast USING (node_id)
          WHERE policy.node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(
        modes,
        (
            "bidirectional_sum".to_owned(),
            "bidirectional_sum".to_owned(),
            "bidirectional_sum".to_owned(),
        )
    );
    let directions: (Option<String>, Option<String>) = sqlx::query_as(
        "SELECT accounted_rx_bytes::text, accounted_tx_bytes::text
           FROM node_traffic_calibrations WHERE node_id = 'n1'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(directions, (None, None));
    assert!(sqlx::query(
        "INSERT INTO node_traffic_calibrations (
             node_id, target_total_bytes, accounted_total_bytes, accounting_mode,
             accounted_rx_bytes, accounted_tx_bytes, calibrated_by
         ) VALUES ('n1', 100, 80, 'bidirectional_max', 40, NULL, 'invalid')",
    )
    .execute(db.pool())
    .await
    .is_err());
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn node_traffic_is_idempotent_across_restart_calibration_and_reboot() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let now: i64 = sqlx::query_scalar("SELECT extract(epoch FROM now())::bigint")
        .fetch_one(db.pool())
        .await
        .unwrap();
    let meter = "0123456789abcdef0123456789abcdef";
    let reading = |sequence, rx_bytes, tx_bytes, discontinuities| NodeTrafficReading {
        meter_id: meter.to_owned(),
        sequence,
        interface: "eth0".to_owned(),
        boot_id: "11111111-2222-3333-4444-555555555555".to_owned(),
        rx_bytes,
        tx_bytes,
        discontinuities,
        sampled_at_unix_secs: None,
        day_boundaries: Vec::new(),
    };

    // First absolute reading is a baseline. Only later monotonic differences enter the ledger.
    db.store
        .record_node_traffic("n1", now - 4, &reading(1, 0, 0, 0))
        .await
        .unwrap();
    db.store
        .record_node_traffic("n1", now - 3, &reading(2, 100, 200, 0))
        .await
        .unwrap();
    // A delayed duplicate cannot charge the bytes a second time or replace the newer baseline.
    db.store
        .record_node_traffic("n1", now - 2, &reading(2, 9_999, 9_999, 0))
        .await
        .unwrap();

    let before = db.store.node_traffic(&system_admin()).await.unwrap();
    let before = before
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(
        (before.rx_bytes.as_str(), before.tx_bytes.as_str()),
        ("100", "200")
    );
    assert_eq!(before.total_bytes, "300");
    assert!(
        before.has_gap,
        "tracking began after this UTC period started"
    );

    db.store
        .update_node_traffic(
            &system_admin(),
            "n1",
            UpdateNodeTrafficRequest {
                cycle_kind: NodeTrafficCycleKind::Monthly,
                accounting_mode: Some(brocade_store::NodeTrafficAccountingMode::BidirectionalSum),
                reset_month: None,
                reset_day: 1,
                quota_bytes: Some("10995116277760".to_owned()),
                calibrated_total_bytes: Some("1073741824".to_owned()),
            },
        )
        .await
        .unwrap();
    let calibrated = db.store.node_traffic(&system_admin()).await.unwrap();
    let calibrated = calibrated
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(calibrated.total_bytes, "1073741824");
    assert_eq!(calibrated.quota_bytes.as_deref(), Some("10995116277760"));
    let capacity = db
        .store
        .machine_traffic_model(&system_admin())
        .await
        .unwrap();
    let capacity = capacity
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(capacity.quota_bytes.as_deref(), Some("10995116277760"));
    // Seconds of tracking: no complete day yet, so the rate is the 300 bytes over the one-hour
    // floor, and no machine has history for a measured error.
    assert_eq!(
        (capacity.daily_rate_bytes.as_str(), capacity.rate_days),
        ("7200", 0)
    );
    assert_eq!(capacity.band.basis, MachineTrafficBandBasis::Default);
    assert_eq!(capacity.confidence, MachineTrafficConfidence::Low);
    assert!(
        !capacity.needs_calibration,
        "the calibration follows the late tracking start"
    );
    // The chart reads the same ledger the totals use: one UTC day holding the 300 accounted
    // bytes, in whichever window that day falls, plus the anchors that explain the total.
    let ledger = capacity
        .days
        .iter()
        .chain(&capacity.previous_days)
        .map(|day| (day.day_start_unix_secs, day.bytes.as_str()))
        .collect::<Vec<_>>();
    assert_eq!(ledger, vec![((now - 3).div_euclid(86_400) * 86_400, "300")]);
    assert_eq!(
        capacity.previous_period_start_unix_secs,
        2 * capacity.period_start_unix_secs - capacity.period_end_unix_secs
    );
    assert_eq!(capacity.tracking_started_at_unix_secs, Some(now - 4));
    assert!(capacity.calibrated_at_unix_secs.is_some());
    assert_eq!(capacity.gap_reason, None);
    assert!(
        !calibrated.has_gap,
        "calibration clears only preceding uncertainty"
    );

    db.store
        .record_node_traffic("n1", now + 1, &reading(3, 150, 250, 0))
        .await
        .unwrap();
    let mut reboot = reading(4, 160, 260, 1);
    reboot.boot_id = "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee".to_owned();
    db.store
        .record_node_traffic("n1", now + 2, &reboot)
        .await
        .unwrap();
    let after = db.store.node_traffic(&system_admin()).await.unwrap();
    let after = after
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(after.total_bytes, "1073741944");
    assert!(after.has_gap, "a reboot after calibration remains visible");
    assert_eq!(after.last_gap_reason.as_deref(), Some("machine-reboot"));
    // The Agent reported right up to the reboot, so the forecast keeps trusting the total.
    let capacity = db
        .store
        .machine_traffic_model(&system_admin())
        .await
        .unwrap();
    let capacity = capacity
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert!(!capacity.needs_calibration);
    assert_eq!(capacity.gap_reason, None);

    // A mode switch never reuses a calibration made under a different formula. Max is taken over
    // the whole period's direction totals: max(160, 260), not the sum of daily maxima.
    db.store
        .update_node_traffic(
            &system_admin(),
            "n1",
            UpdateNodeTrafficRequest {
                cycle_kind: NodeTrafficCycleKind::Monthly,
                accounting_mode: Some(NodeTrafficAccountingMode::BidirectionalMax),
                reset_month: None,
                reset_day: 1,
                quota_bytes: Some("10995116277760".to_owned()),
                calibrated_total_bytes: None,
            },
        )
        .await
        .unwrap();
    let switched = db.store.node_traffic(&system_admin()).await.unwrap();
    let switched = switched
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(
        switched.accounting_mode,
        NodeTrafficAccountingMode::BidirectionalMax
    );
    assert_eq!(switched.total_bytes, "260");
    assert_eq!(switched.calibrated_at_unix_secs, None);

    db.store
        .update_node_traffic(
            &system_admin(),
            "n1",
            UpdateNodeTrafficRequest {
                cycle_kind: NodeTrafficCycleKind::Monthly,
                accounting_mode: Some(NodeTrafficAccountingMode::BidirectionalMax),
                reset_month: None,
                reset_day: 1,
                quota_bytes: Some("10995116277760".to_owned()),
                calibrated_total_bytes: Some("1000".to_owned()),
            },
        )
        .await
        .unwrap();
    db.store
        .record_node_traffic("n1", now + 3, &reading(5, 190, 280, 1))
        .await
        .unwrap();
    let recalibrated = db.store.node_traffic(&system_admin()).await.unwrap();
    let recalibrated = recalibrated
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(recalibrated.total_bytes, "1030");

    // An older already-open UI has no mode field. Its quota edit must preserve the selected mode
    // and that mode's calibration instead of silently resetting both to the legacy default.
    db.store
        .update_node_traffic(
            &system_admin(),
            "n1",
            UpdateNodeTrafficRequest {
                cycle_kind: NodeTrafficCycleKind::Monthly,
                accounting_mode: None,
                reset_month: None,
                reset_day: 1,
                quota_bytes: Some("12345".to_owned()),
                calibrated_total_bytes: None,
            },
        )
        .await
        .unwrap();
    let legacy_write = db.store.node_traffic(&system_admin()).await.unwrap();
    let legacy_write = legacy_write
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(
        legacy_write.accounting_mode,
        NodeTrafficAccountingMode::BidirectionalMax
    );
    assert_eq!(legacy_write.total_bytes, "1030");
    assert_eq!(legacy_write.quota_bytes.as_deref(), Some("12345"));
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn machine_traffic_forecasts_are_recorded_daily_and_reviewed_after_the_period() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let (today, this_start, previous_start): (i64, i64, i64) = sqlx::query_as(
        "SELECT extract(epoch FROM (now() AT TIME ZONE 'UTC')::date::timestamp
                    AT TIME ZONE 'UTC')::bigint,
                extract(epoch FROM date_trunc('month', (now() AT TIME ZONE 'UTC')::date::timestamp)
                    AT TIME ZONE 'UTC')::bigint,
                extract(epoch FROM (date_trunc('month', (now() AT TIME ZONE 'UTC')::date::timestamp)
                    - interval '1 month') AT TIME ZONE 'UTC')::bigint",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    let day = 86_400;
    let previous_days = (this_start - previous_start) / day;
    // Seventy days of 1000 bytes, tracked from the first of them; the meter matches the ledger.
    sqlx::query(
        "INSERT INTO node_traffic_daily (node_id, day, rx_bytes, tx_bytes)
         SELECT 'n1', (now() AT TIME ZONE 'UTC')::date - back, 600, 400
           FROM generate_series(0, 69) AS back",
    )
    .execute(db.pool())
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO node_traffic_state (
            node_id, meter_id, sequence, interface, boot_id, agent_rx_bytes, agent_tx_bytes,
            accounted_rx_bytes, accounted_tx_bytes, discontinuities, tracking_started_at,
            last_reported_at
         ) VALUES (
            'n1', '0123456789abcdef0123456789abcdef', 1, 'eth0',
            '11111111-2222-3333-4444-555555555555', 0, 0, 42000, 28000, 0,
            ((now() AT TIME ZONE 'UTC')::date - 69)::timestamp AT TIME ZONE 'UTC', now()
         )",
    )
    .execute(db.pool())
    .await
    .unwrap();
    // A reboot between two reporting days loses nothing a calibration would need to restore.
    sqlx::query(
        "INSERT INTO node_traffic_gaps (node_id, occurred_at, reason)
         VALUES ('n1', now() - interval '1 minute', 'machine-reboot')",
    )
    .execute(db.pool())
    .await
    .unwrap();

    // Three forecasts recorded during the previous month, and one old enough to be pruned.
    let actual = previous_days * 1000;
    for (offset, p50, p90) in [
        (0, actual * 11 / 10, actual * 12 / 10),
        (1, actual * 9 / 10, actual * 95 / 100),
        (2, actual, actual),
    ] {
        sqlx::query(
            "INSERT INTO node_traffic_forecasts (
                node_id, day, taken_at, period_start, period_end, used_bytes, p50_bytes, p90_bytes
             ) VALUES (
                'n1', (to_timestamp($1) AT TIME ZONE 'UTC')::date + $2::int, now(),
                (to_timestamp($1) AT TIME ZONE 'UTC')::date,
                (to_timestamp($3) AT TIME ZONE 'UTC')::date, 0, $4, $5
             )",
        )
        .bind(previous_start as f64)
        .bind(offset)
        .bind(this_start as f64)
        .bind(p50)
        .bind(p90)
        .execute(db.pool())
        .await
        .unwrap();
    }
    sqlx::query(
        "INSERT INTO node_traffic_forecasts (
            node_id, day, taken_at, period_start, period_end, used_bytes, p50_bytes, p90_bytes
         ) VALUES (
            'n1', (now() AT TIME ZONE 'UTC')::date - 900, now() - interval '900 days',
            (now() AT TIME ZONE 'UTC')::date - 930, (now() AT TIME ZONE 'UTC')::date - 900,
            0, 1, 1
         )",
    )
    .execute(db.pool())
    .await
    .unwrap();

    let model = db
        .store
        .machine_traffic_model(&system_admin())
        .await
        .unwrap();
    let node = model
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(
        (node.daily_rate_bytes.as_str(), node.rate_days),
        ("1000", 28)
    );
    assert!(!node.needs_calibration);
    assert_eq!(node.gap_reason, None);
    assert_eq!(
        node.last_period_accuracy,
        Some(MachineTrafficAccuracy {
            period_start_unix_secs: previous_start,
            period_end_unix_secs: this_start,
            actual_bytes: actual.to_string(),
            forecasts: 3,
            // (10% + 10% + 0%) / 3
            p50_error_basis_points: 667,
            p90_covered: 2,
        })
    );
    let outside = db
        .store
        .machine_traffic_model(&tenant_admin("platform.other"))
        .await
        .unwrap();
    assert!(outside.nodes.is_empty());

    assert_eq!(
        db.store.record_machine_traffic_forecasts().await.unwrap(),
        1
    );
    assert_eq!(
        db.store.record_machine_traffic_forecasts().await.unwrap(),
        0,
        "the first record of a day stands"
    );
    let (used, p50, p90): (String, String, String) = sqlx::query_as(
        "SELECT used_bytes::text, p50_bytes::text, p90_bytes::text
           FROM node_traffic_forecasts
          WHERE node_id = 'n1' AND day = (now() AT TIME ZONE 'UTC')::date",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(used, node.used_bytes);
    assert!(p50.parse::<u64>().unwrap() >= used.parse::<u64>().unwrap());
    assert!(p90.parse::<u64>().unwrap() >= p50.parse::<u64>().unwrap());
    assert_eq!(
        db.store.prune_machine_traffic_forecasts(800).await.unwrap(),
        1
    );
    let kept: i64 = sqlx::query_scalar("SELECT count(*) FROM node_traffic_forecasts")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(kept, 4);

    // A calibration inside the closed period sets its total: the target plus what the meter
    // accounted from then until the period ended.
    let calibrated_at = previous_start + 5 * day;
    sqlx::query(
        "INSERT INTO node_traffic_calibrations (
            node_id, calibrated_at, target_total_bytes, accounted_total_bytes, calibrated_by
         ) VALUES ('n1', to_timestamp($1), 50000, $2, 'test')",
    )
    .bind(calibrated_at as f64)
    .bind((calibrated_at - (today - 69 * day)) / day * 1000)
    .execute(db.pool())
    .await
    .unwrap();
    let model = db
        .store
        .machine_traffic_model(&system_admin())
        .await
        .unwrap();
    let node = model
        .nodes
        .iter()
        .find(|node| node.node_id == "n1")
        .unwrap();
    assert_eq!(
        node.last_period_accuracy
            .as_ref()
            .map(|accuracy| accuracy.actual_bytes.clone()),
        Some((50_000 + (previous_days - 5) * 1000).to_string())
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn delayed_regrant_cannot_overtake_a_newer_revoke() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    store_current_model_snapshot(db.pool(), &db.store).await;
    db.store
        .create_deployment(
            &system_admin(),
            create_deployment_request(1, "review-delayed-regrant-base"),
        )
        .await
        .unwrap();
    let base = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .unwrap();
    db.store
        .report_target_result(applied_report(&base))
        .await
        .unwrap();

    let grant = |enabled| CreateGrantRequest {
        app_id: "app-main".to_owned(),
        tenant_id: "platform.acme".to_owned(),
        user_id: "alice".to_owned(),
        ingress_id: "ing-a1b2".to_owned(),
        enabled,
        note: None,
    };
    db.store
        .upsert_grant(&system_admin(), grant(false))
        .await
        .unwrap();
    let revoke_order = db.store.process_grant_automation().await.unwrap();
    assert!(revoke_order.deployment_id.is_some());

    let regrant_revision = db
        .store
        .upsert_grant(&system_admin(), grant(true))
        .await
        .unwrap();
    let blocked = db.store.process_grant_automation().await.unwrap();
    assert!(blocked.waiting.is_some());
    // Freeze the retry deadline so this ordering does not depend on CI machine speed.
    sqlx::query("UPDATE jobs SET run_after = now() + interval '1 hour' WHERE status = 'queued' AND kind = 'grants-deployment'")
        .execute(db.pool()).await.unwrap();

    let revoke = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .unwrap();
    db.store
        .report_target_result(applied_report(&revoke))
        .await
        .unwrap();

    // A third click revokes again while the older re-grant is still backing off.
    let latest = db
        .store
        .upsert_grant(&system_admin(), grant(false))
        .await
        .unwrap();
    let newest = db.store.process_grant_automation().await.unwrap();
    assert_eq!(newest.revision_id, Some(latest.revision_id));
    assert_eq!(
        newest.deployment_id, None,
        "the node already applied the first revoke"
    );
    assert_eq!(
        serving_permissions_revision(db.pool()).await,
        latest.revision_id
    );

    // The older deadline now expires, just as the 5-second production retry would.
    sqlx::query(
        "UPDATE jobs SET run_after = now() WHERE status = 'queued' AND kind = 'grants-deployment'",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let late = db.store.process_grant_automation().await.unwrap();
    if late.deployment_id.is_some() {
        let unwanted = db
            .store
            .claim_desired_for_node("n1")
            .await
            .unwrap()
            .unwrap();
        let reenabled_alice = match &unwanted.desired.grants {
            DesiredGrants::Present { inbounds } => inbounds
                .iter()
                .flat_map(|inbound| &inbound.clients)
                .any(|client| client.email == "alice@platform.acme#ing-a1b2"),
            _ => false,
        };
        db.store
            .report_target_result(applied_report(&unwanted))
            .await
            .unwrap();
        assert!(
            !reenabled_alice,
            "stale re-grant revision {} re-enabled Alice after newer revoke {}; serving is now {}",
            regrant_revision.revision_id,
            latest.revision_id,
            serving_permissions_revision(db.pool()).await
        );
    }
    assert_eq!(
        serving_permissions_revision(db.pool()).await,
        latest.revision_id
    );
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn permission_retry_deadlines_do_not_partition_the_revision_queue() {
    for delay_newest in [false, true] {
        let Some(db) = TestPg::start_if_enabled().await else {
            return;
        };
        db.store.migrate().await.unwrap();
        insert_minimal_fixture(db.pool()).await;
        store_current_model_snapshot(db.pool(), &db.store).await;
        db.store
            .create_deployment(
                &system_admin(),
                create_deployment_request(1, "retry-queue-base"),
            )
            .await
            .unwrap();
        let base = db
            .store
            .claim_desired_for_node("n1")
            .await
            .unwrap()
            .unwrap();
        db.store
            .report_target_result(applied_report(&base))
            .await
            .unwrap();
        let grant = |enabled| CreateGrantRequest {
            app_id: "app-main".to_owned(),
            tenant_id: "platform.acme".to_owned(),
            user_id: "alice".to_owned(),
            ingress_id: "ing-a1b2".to_owned(),
            enabled,
            note: None,
        };
        let older = db
            .store
            .upsert_grant(&system_admin(), grant(false))
            .await
            .unwrap();
        let newest = db
            .store
            .upsert_grant(&system_admin(), grant(true))
            .await
            .unwrap();
        sqlx::query("UPDATE jobs SET run_after = now() + interval '1 hour' WHERE kind = 'grants-deployment'")
            .execute(db.pool()).await.unwrap();
        assert_eq!(
            db.store
                .process_grant_automation()
                .await
                .unwrap()
                .merged_jobs,
            0,
            "an entirely backed-off queue must not run on every wake"
        );
        let due = if delay_newest {
            older.revision_id
        } else {
            newest.revision_id
        };
        sqlx::query("UPDATE jobs SET run_after = now() WHERE kind = 'grants-deployment' AND (payload->>'revision_id')::bigint = $1")
            .bind(i64::try_from(due).unwrap()).execute(db.pool()).await.unwrap();
        let batch = db.store.process_grant_automation().await.unwrap();
        assert_eq!(batch.merged_jobs, 2);
        assert_eq!(batch.revision_id, Some(newest.revision_id));
        assert_eq!(
            batch.deployment_id, None,
            "the latest intent still matches the baseline"
        );
        assert_eq!(
            serving_permissions_revision(db.pool()).await,
            newest.revision_id
        );
        let queued: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM jobs WHERE kind = 'grants-deployment' AND status = 'queued'",
        )
        .fetch_one(db.pool())
        .await
        .unwrap();
        assert_eq!(
            queued, 0,
            "no historical retry may survive the newer intent"
        );
    }
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn grants_order_recovery_is_idempotent_and_halted_orders_keep_jobs_pending() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    store_current_model_snapshot(db.pool(), &db.store).await;
    db.store
        .create_deployment(
            &system_admin(),
            create_deployment_request(1, "retry-recovery-base"),
        )
        .await
        .unwrap();
    let base = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .unwrap();
    db.store
        .report_target_result(applied_report(&base))
        .await
        .unwrap();
    let grant = |enabled| CreateGrantRequest {
        app_id: "app-main".to_owned(),
        tenant_id: "platform.acme".to_owned(),
        user_id: "alice".to_owned(),
        ingress_id: "ing-a1b2".to_owned(),
        enabled,
        note: None,
    };
    db.store
        .upsert_grant(&system_admin(), grant(false))
        .await
        .unwrap();
    let first = db
        .store
        .process_grant_automation()
        .await
        .unwrap()
        .deployment_id
        .unwrap();
    // Model a crash after committing the immutable order but before finishing its durable job.
    sqlx::query("UPDATE jobs SET status = 'queued', run_after = now(), payload = payload - 'deployment_id' WHERE kind = 'grants-deployment'")
        .execute(db.pool()).await.unwrap();
    let restarted = PgStore::connect(&db.url).await.unwrap();
    let recovered = restarted.process_grant_automation().await.unwrap();
    assert_eq!(recovered.deployment_id, Some(first));
    assert!(recovered.waiting.is_none());
    let orders: i64 = sqlx::query_scalar("SELECT count(*) FROM deployments WHERE kind = 'grants'")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(orders, 1);
    db.store
        .halt_deployment(&system_admin(), first)
        .await
        .unwrap();
    let newest = db
        .store
        .upsert_grant(&system_admin(), grant(true))
        .await
        .unwrap();
    let pending = restarted.process_grant_automation().await.unwrap();
    assert_eq!(pending.revision_id, Some(newest.revision_id));
    assert!(pending.waiting.is_some());
    let status = db.store.grant_automation_status().await.unwrap();
    assert_eq!(status.pending_jobs, 1);
    assert_eq!(status.retrying_jobs, 0);
    assert_eq!(serving_permissions_revision(db.pool()).await, 1);
}

async fn serving_permissions_revision(pool: &PgPool) -> u64 {
    sqlx::query_scalar::<_, i64>(
        "SELECT permissions_revision_id FROM subscription_serving_state WHERE id = TRUE",
    )
    .fetch_one(pool)
    .await
    .unwrap()
    .try_into()
    .unwrap()
}

// A re-grant planned while the revoke order was still unclaimed used to compare against n1's
// pre-revoke report, find nothing to ship, and mark its revision serving; the revoke order then
// landed over it and nothing queued the re-grant again.
#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn regrant_waits_for_an_unsettled_revoke_order() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    store_current_model_snapshot(db.pool(), &db.store).await;

    db.store
        .create_deployment(
            &system_admin(),
            create_deployment_request(1, "regrant-race-base"),
        )
        .await
        .unwrap();
    let base = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .unwrap();
    db.store
        .report_target_result(applied_report(&base))
        .await
        .unwrap();
    let serving_before = serving_permissions_revision(db.pool()).await;
    let probe_items_before = db
        .store
        .user_grant_probe_plan(&system_admin(), "platform.acme", "alice")
        .await
        .unwrap()
        .items
        .len();

    let alice = |enabled: bool| CreateGrantRequest {
        app_id: "app-main".to_owned(),
        tenant_id: "platform.acme".to_owned(),
        user_id: "alice".to_owned(),
        ingress_id: "ing-a1b2".to_owned(),
        enabled,
        note: None,
    };

    let revoked = db
        .store
        .upsert_grant(&system_admin(), alice(false))
        .await
        .unwrap();
    let revoke_order = db
        .store
        .process_grant_automation()
        .await
        .unwrap()
        .deployment_id
        .expect("the revoke becomes a grants order");

    let regranted = db
        .store
        .upsert_grant(&system_admin(), alice(true))
        .await
        .unwrap();
    let blocked = db.store.process_grant_automation().await.unwrap();
    assert_eq!(blocked.deployment_id, None);
    assert!(
        blocked
            .waiting
            .as_deref()
            .unwrap()
            .contains(&format!("#{revoke_order}")),
        "the job names the order it waits for: {blocked:?}"
    );
    assert_eq!(
        serving_permissions_revision(db.pool()).await,
        serving_before,
        "a job waiting behind an order must not advance serving"
    );
    let (queued, attempts): (i64, i64) = sqlx::query_as(
        "SELECT count(*), COALESCE(max(attempts), 0)::bigint
         FROM jobs WHERE kind = 'grants-deployment' AND status = 'queued'",
    )
    .fetch_one(db.pool())
    .await
    .unwrap();
    assert_eq!(queued, 1);
    assert_eq!(
        attempts, 0,
        "waiting behind an order is not a failed attempt"
    );

    let revoke = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .expect("the revoke order is claimable");
    assert_eq!(revoke.deployment_id, revoke_order);
    db.store
        .report_target_result(applied_report(&revoke))
        .await
        .unwrap();
    assert_eq!(
        serving_permissions_revision(db.pool()).await,
        revoked.revision_id
    );

    sqlx::query(
        "UPDATE jobs SET run_after = now()
         WHERE kind = 'grants-deployment' AND status = 'queued'",
    )
    .execute(db.pool())
    .await
    .unwrap();
    let released = db.store.process_grant_automation().await.unwrap();
    assert_eq!(released.revision_id, Some(regranted.revision_id));
    assert!(released.waiting.is_none());
    let regrant = db
        .store
        .claim_desired_for_node("n1")
        .await
        .unwrap()
        .expect("the re-grant ships once the revoke has landed");
    assert_eq!(Some(regrant.deployment_id), released.deployment_id);
    let DesiredGrants::Present { ref inbounds } = regrant.desired.grants else {
        panic!("grants should be present");
    };
    assert!(inbounds
        .iter()
        .flat_map(|inbound| &inbound.clients)
        .any(|client| client.email == "alice@platform.acme#ing-a1b2"));
    db.store
        .report_target_result(applied_report(&regrant))
        .await
        .unwrap();

    assert_eq!(
        serving_permissions_revision(db.pool()).await,
        regranted.revision_id
    );
    let probe_items_after = db
        .store
        .user_grant_probe_plan(&system_admin(), "platform.acme", "alice")
        .await
        .unwrap()
        .items
        .len();
    assert_eq!(probe_items_after, probe_items_before);
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn user_machine_usage_preserves_accounting_history_and_operator_scope() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let base = usage_report_base_unix();
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), base - 60).await;
    db.store
        .record_usage_report("n1", current_usage(generation, 1, base, "epoch", 10, 20))
        .await
        .unwrap();
    let report = current_usage(generation, 2, base + 30, "epoch", 110, 220);
    db.store
        .record_usage_report("n1", report.clone())
        .await
        .unwrap();
    assert!(
        db.store
            .record_usage_report("n1", report)
            .await
            .unwrap()
            .duplicate
    );
    db.store
        .record_usage_report(
            "n1",
            current_usage(generation, 3, base + 60, "epoch", 110, 220),
        )
        .await
        .unwrap();
    // Forwarding already has durable user/machine daily attribution, including first readings
    // with no measured interval. This query must add it once and expose that uncertainty.
    let rule:i64=sqlx::query_scalar("INSERT INTO forwarding_rules(tenant_id,user_id,node_id,name,protocol,listen_port,target_host,target_port) VALUES('platform.acme','alice','n1','Test','tcp',20042,'192.0.2.1',443) RETURNING id").fetch_one(db.pool()).await.unwrap();
    sqlx::query("INSERT INTO forwarding_usage_rollups(period_start,node_id,tenant_id,user_id,rule_id,uplink_bytes,downlink_bytes,has_gap) VALUES(date_trunc('day',to_timestamp($1) AT TIME ZONE 'Asia/Hong_Kong') AT TIME ZONE 'Asia/Hong_Kong','n1','platform.acme','alice',$2,30,70,false)").bind(base as f64).bind(rule).execute(db.pool()).await.unwrap();
    sqlx::query("INSERT INTO forwarding_usage_samples(node_id,rule_id,tenant_id,user_id,read_at,uplink_bytes,downlink_bytes) VALUES('n1',$1,'platform.acme','alice',to_timestamp($2),30,70)").bind(rule).bind(base as f64).execute(db.pool()).await.unwrap();
    for period in [
        SiteUsagePeriod::Day,
        SiteUsagePeriod::Week,
        SiteUsagePeriod::Month,
    ] {
        let view = db
            .store
            .user_machine_usage(&system_admin(), "platform.acme", "alice", period)
            .await
            .unwrap();
        let row = view
            .rows
            .iter()
            .find(|row| row.node_id.as_deref() == Some("n1"))
            .unwrap();
        assert_eq!(
            (row.uplink_bytes, row.downlink_bytes, row.forwarding_bytes),
            (130, 270, 100)
        );
        assert_eq!(row.points.iter().map(|p| p.1 + p.2).sum::<u64>(), 400);
        assert!(row.points.iter().any(|p| p.5));
        if period != SiteUsagePeriod::Month {
            assert!(
                row.points.iter().any(|p| p.4),
                "unknown forwarding interval"
            );
        }
        assert_eq!((view.range_start_unix_secs + 8 * 3600) % 86400, 0);
        assert_eq!(view.bucket_secs, period.bucket_secs());
    }
    // Historic attribution is not a join to today's grants.
    sqlx::query("DELETE FROM grants WHERE user_id='alice'")
        .execute(db.pool())
        .await
        .unwrap();
    let historical = db
        .store
        .user_machine_usage(
            &system_admin(),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Month,
        )
        .await
        .unwrap();
    assert_eq!(historical.rows[0].uplink_bytes, 130);
    assert!(!historical.rows[0].expected);
    // Data older than retained detail remains in the ledger, but cannot be assigned to a node.
    sqlx::query("UPDATE usage_rollups SET uplink_bytes=uplink_bytes+11,downlink_bytes=downlink_bytes+22 WHERE user_id='alice'").execute(db.pool()).await.unwrap();
    let legacy = db
        .store
        .user_machine_usage(
            &system_admin(),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Month,
        )
        .await
        .unwrap();
    let unknown = legacy
        .rows
        .iter()
        .find(|row| row.node_id.is_none())
        .unwrap();
    assert_eq!((unknown.uplink_bytes, unknown.downlink_bytes), (11, 22));
    assert_eq!(unknown.points.iter().map(|p| p.1 + p.2).sum::<u64>(), 33);
    let day = db
        .store
        .user_machine_usage(
            &system_admin(),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Day,
        )
        .await
        .unwrap();
    assert!(
        day.rows
            .iter()
            .find(|row| row.node_id.is_none())
            .unwrap()
            .points
            .is_empty(),
        "do not invent hourly placement"
    );
    sqlx::query("DELETE FROM usage_samples")
        .execute(db.pool())
        .await
        .unwrap();
    let retained = db
        .store
        .user_machine_usage(
            &system_admin(),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Month,
        )
        .await
        .unwrap();
    assert_eq!(
        retained.rows[0].uplink_bytes, 130,
        "month survives raw retention"
    );
    for actor in traffic_readers("platform.acme") {
        let visible = db
            .store
            .user_machine_usage(&actor, "platform.acme", "alice", SiteUsagePeriod::Month)
            .await
            .unwrap();
        assert!(
            !visible.rows.is_empty(),
            "{:?} can read scoped traffic",
            actor.role()
        );
    }
    for actor in [
        AdminContext::new("public", AdminRole::Readonly, None),
        tenant_admin("platform.other"),
        ordinary_user("platform.acme"),
    ] {
        assert!(matches!(
            db.store
                .user_machine_usage(&actor, "platform.acme", "alice", SiteUsagePeriod::Month)
                .await,
            Err(StoreError::Forbidden(_))
        ));
    }
    assert!(db
        .store
        .user_machine_usage(
            &tenant_admin("platform"),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Week
        )
        .await
        .is_ok());
    assert!(matches!(
        db.store
            .user_machine_usage(
                &system_admin(),
                "platform.acme",
                "missing",
                SiteUsagePeriod::Day
            )
            .await,
        Err(StoreError::NotFound(_))
    ));
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn user_machine_usage_backfill_and_write_failure_are_atomic() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let base = usage_report_base_unix();
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), base - 60).await;
    db.store
        .record_usage_report("n1", current_usage(generation, 1, base, "epoch", 10, 20))
        .await
        .unwrap();
    let report = current_usage(generation, 2, base + 30, "epoch", 110, 220);
    sqlx::query(
        "ALTER TABLE usage_user_node_rollups ADD CONSTRAINT test_reject CHECK (uplink_bytes=0)",
    )
    .execute(db.pool())
    .await
    .unwrap();
    assert!(db
        .store
        .record_usage_report("n1", report.clone())
        .await
        .is_err());
    let charged: i64 =
        sqlx::query_scalar("SELECT coalesce(sum(uplink_bytes),0)::bigint FROM usage_rollups")
            .fetch_one(db.pool())
            .await
            .unwrap();
    assert_eq!(
        charged, 0,
        "projection failure rolls back ledger and receipt"
    );
    sqlx::query("ALTER TABLE usage_user_node_rollups DROP CONSTRAINT test_reject")
        .execute(db.pool())
        .await
        .unwrap();
    db.store
        .record_usage_report("n1", report.clone())
        .await
        .unwrap();
    sqlx::query("DROP TABLE usage_user_node_rollups")
        .execute(db.pool())
        .await
        .unwrap();
    let script = include_str!("../../../scripts/compat-user-machine-usage.sql")
        .lines()
        .filter(|line| !line.starts_with('\\'))
        .collect::<Vec<_>>()
        .join("\n")
        .replace(":\"app_role\"", "postgres");
    sqlx::raw_sql(&script).execute(db.pool()).await.unwrap();
    assert!(
        db.store
            .record_usage_report("n1", report)
            .await
            .unwrap()
            .duplicate
    );
    let view = db
        .store
        .user_machine_usage(
            &system_admin(),
            "platform.acme",
            "alice",
            SiteUsagePeriod::Month,
        )
        .await
        .unwrap();
    assert_eq!(
        (view.rows[0].uplink_bytes, view.rows[0].downlink_bytes),
        (100, 200)
    );
    let zero = current_usage(generation, 3, base + 60, "epoch", 110, 220);
    db.store.record_usage_report("n1", zero).await.unwrap();
    let count: i64 = sqlx::query_scalar("SELECT count(*) FROM usage_samples")
        .fetch_one(db.pool())
        .await
        .unwrap();
    assert_eq!(count, 1, "sparse zero windows remain sparse");
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn node_inflow_usage_attributes_chains_forwarding_history_and_scope() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let base = usage_report_base_unix();
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), base - 60).await;
    db.store
        .record_usage_report("n1", current_usage(generation, 1, base, "epoch", 10, 20))
        .await
        .unwrap();
    let report = current_usage(generation, 2, base + 30, "epoch", 110, 220);
    db.store
        .record_usage_report("n1", report.clone())
        .await
        .unwrap();
    assert!(
        db.store
            .record_usage_report("n1", report)
            .await
            .unwrap()
            .duplicate,
        "a retried report must not count twice"
    );
    let rule:i64=sqlx::query_scalar("INSERT INTO forwarding_rules(tenant_id,user_id,node_id,name,protocol,listen_port,target_host,target_port) VALUES('platform.acme','alice','n1','Test','tcp',20042,'192.0.2.1',443) RETURNING id").fetch_one(db.pool()).await.unwrap();
    sqlx::query("INSERT INTO forwarding_usage_rollups(period_start,node_id,tenant_id,user_id,rule_id,uplink_bytes,downlink_bytes,has_gap) VALUES(date_trunc('day',to_timestamp($1) AT TIME ZONE 'Asia/Hong_Kong') AT TIME ZONE 'Asia/Hong_Kong','n1','platform.acme','alice',$2,30,70,false)").bind(base as f64).bind(rule).execute(db.pool()).await.unwrap();
    sqlx::query("INSERT INTO users (tenant_id, id, uuid) VALUES ('platform.acme', 'bob', 'f6a8d5bb-3a5f-4f61-9b0e-2b7f0d8c4e11')")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query("INSERT INTO grants (app_id, tenant_id, user_id, ingress_id) VALUES ('app-main', 'platform.acme', 'bob', 'ing-a1b2')")
        .execute(db.pool())
        .await
        .unwrap();
    let totals = |view: &brocade_store::NodeInflowUsage, source: NodeInflowSource| {
        view.rows
            .iter()
            .filter(|row| row.source == source)
            .map(|row| (row.uplink_bytes, row.downlink_bytes))
            .fold((0, 0), |sum, row| (sum.0 + row.0, sum.1 + row.1))
    };
    for period in [
        SiteUsagePeriod::Day,
        SiteUsagePeriod::Week,
        SiteUsagePeriod::Month,
    ] {
        let view = db
            .store
            .node_inflow_usage(&system_admin(), "n1", period)
            .await
            .unwrap();
        assert_eq!(view.period, period);
        assert_eq!((view.range_start_unix_secs + 8 * 3600) % 86_400, 0);
        let chain = view
            .rows
            .iter()
            .find(|row| row.source == NodeInflowSource::Chain)
            .unwrap();
        assert_eq!(
            (
                chain.user_id.as_str(),
                chain.app_id.as_deref(),
                chain.chain_id.as_deref(),
                chain.ingress_id.as_deref(),
            ),
            ("alice", Some("app-main"), Some("chn-a1b2-c3d4"), None)
        );
        assert_eq!((chain.uplink_bytes, chain.downlink_bytes), (100, 200));
        assert_eq!(totals(&view, NodeInflowSource::Forwarding), (30, 70));
        assert_eq!(totals(&view, NodeInflowSource::Unattributed), (0, 0));
        assert_eq!(
            view.idle_users
                .iter()
                .map(|user| user.user_id.as_str())
                .collect::<Vec<_>>(),
            vec!["bob"],
            "granted without inflow is idle, not zero rows"
        );
        assert!(view.latest_report_unix_secs.is_some());
    }

    // The chain was frozen at insert: moving the ingress later does not move its history.
    sqlx::query("INSERT INTO chains (id, app_id, tenant_id, name, position) VALUES ('chn-later', 'app-main', 'platform.acme', 'Later', 1)")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query("UPDATE ingresses SET chain_id='chn-later' WHERE id='ing-a1b2'")
        .execute(db.pool())
        .await
        .unwrap();
    let frozen = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    assert!(frozen
        .rows
        .iter()
        .any(|row| row.chain_id.as_deref() == Some("chn-a1b2-c3d4")));

    // An ingress already gone at insert keeps only its id; the bytes are not dropped.
    sqlx::query("UPDATE usage_user_ingress_rollups SET chain_id=NULL, ingress_id='ing-gone'")
        .execute(db.pool())
        .await
        .unwrap();
    let orphan = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    let row = orphan
        .rows
        .iter()
        .find(|row| row.source == NodeInflowSource::Chain)
        .unwrap();
    assert_eq!(
        (row.chain_id.as_deref(), row.ingress_id.as_deref()),
        (None, Some("ing-gone"))
    );
    assert_eq!((row.uplink_bytes, row.downlink_bytes), (100, 200));

    // Reusing a previously missing ingress id must not assign its old traffic to a new chain.
    sqlx::query("UPDATE usage_user_ingress_rollups SET ingress_id='ing-a1b2'")
        .execute(db.pool())
        .await
        .unwrap();
    let reused = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    let reused = reused
        .rows
        .iter()
        .find(|row| row.source == NodeInflowSource::Chain)
        .unwrap();
    assert_eq!(
        (reused.chain_id.as_deref(), reused.ingress_id.as_deref()),
        (None, Some("ing-a1b2"))
    );

    // Days before per-chain accounting stay whole as the unattributed remainder.
    sqlx::query("DELETE FROM usage_user_ingress_rollups")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query("UPDATE usage_user_node_rollups SET has_gap=true WHERE node_id='n1'")
        .execute(db.pool())
        .await
        .unwrap();
    let legacy = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    assert_eq!(totals(&legacy, NodeInflowSource::Chain), (0, 0));
    assert_eq!(totals(&legacy, NodeInflowSource::Unattributed), (100, 200));

    assert!(legacy
        .rows
        .iter()
        .filter(|row| row.source == NodeInflowSource::Unattributed)
        .all(|row| row.has_gap));

    // A chain projection larger than the machine projection is reported, never clamped.
    sqlx::query("INSERT INTO usage_user_ingress_rollups (node_id,period_start,tenant_id,user_id,ingress_id,app_id,chain_id,uplink_bytes,downlink_bytes) SELECT node_id,period_start,tenant_id,user_id,'ing-a1b2','app-main','chn-a1b2-c3d4',uplink_bytes+1,downlink_bytes FROM usage_user_node_rollups")
        .execute(db.pool())
        .await
        .unwrap();
    assert!(matches!(
        db.store
            .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
            .await,
        Err(StoreError::InvalidData(_))
    ));
    sqlx::query("UPDATE usage_user_ingress_rollups SET uplink_bytes=uplink_bytes-1")
        .execute(db.pool())
        .await
        .unwrap();

    // Signed-in operators read their own subtree; visitors and ordinary users are refused.
    let outside = db
        .store
        .node_inflow_usage(&tenant_admin("platform.other"), "n1", SiteUsagePeriod::Day)
        .await
        .unwrap();
    assert!(outside.rows.is_empty() && outside.idle_users.is_empty());
    let inside = db
        .store
        .node_inflow_usage(&tenant_admin("platform"), "n1", SiteUsagePeriod::Day)
        .await
        .unwrap();
    assert!(!inside.rows.is_empty());
    for actor in traffic_readers("platform.acme") {
        let visible = db
            .store
            .node_inflow_usage(&actor, "n1", SiteUsagePeriod::Day)
            .await
            .unwrap();
        assert!(
            !visible.rows.is_empty(),
            "{:?} can read scoped traffic",
            actor.role()
        );
    }
    for actor in [
        AdminContext::new("public", AdminRole::Readonly, None),
        ordinary_user("platform.acme"),
    ] {
        assert!(matches!(
            db.store
                .node_inflow_usage(&actor, "n1", SiteUsagePeriod::Day)
                .await,
            Err(StoreError::Forbidden(_))
        ));
    }
}

#[tokio::test]
#[ignore = "requires BROCADE_RUN_PG_TESTS=1 and PostgreSQL"]
async fn node_inflow_usage_backfill_matches_retained_detail_once() {
    let Some(db) = TestPg::start_if_enabled().await else {
        return;
    };
    db.store.migrate().await.unwrap();
    insert_minimal_fixture(db.pool()).await;
    let base = usage_report_base_unix();
    let generation =
        install_usage_generation(db.pool(), "n1", alice_usage_bindings(), base - 60).await;
    db.store
        .record_usage_report("n1", current_usage(generation, 1, base, "epoch", 10, 20))
        .await
        .unwrap();
    let report = current_usage(generation, 2, base + 30, "epoch", 110, 220);
    db.store
        .record_usage_report("n1", report.clone())
        .await
        .unwrap();
    // A failed projection rolls back the whole accepted window, including its receipt.
    sqlx::query("DROP TABLE usage_user_ingress_rollups")
        .execute(db.pool())
        .await
        .unwrap();
    sqlx::query("DROP INDEX user_site_usage_hourly_by_node")
        .execute(db.pool())
        .await
        .unwrap();
    assert!(db
        .store
        .record_usage_report(
            "n1",
            current_usage(generation, 3, base + 60, "epoch", 150, 260)
        )
        .await
        .is_err());
    let script = include_str!("../../../scripts/compat-user-ingress-usage.sql")
        .lines()
        .filter(|line| !line.starts_with('\\'))
        .collect::<Vec<_>>()
        .join("\n")
        .replace(":\"app_role\"", "postgres");
    sqlx::raw_sql(&script).execute(db.pool()).await.unwrap();
    let view = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    let chain = view
        .rows
        .iter()
        .find(|row| row.source == NodeInflowSource::Chain)
        .unwrap();
    assert_eq!(
        (
            chain.chain_id.as_deref(),
            chain.uplink_bytes,
            chain.downlink_bytes
        ),
        (Some("chn-a1b2-c3d4"), 100, 200),
        "backfill equals the retained detail"
    );
    assert!(view
        .rows
        .iter()
        .all(|row| row.source != NodeInflowSource::Unattributed));
    // psql stops on the error and ends the session; a pooled connection must roll back itself.
    let mut connection = db.pool().acquire().await.unwrap();
    assert!(
        sqlx::raw_sql(&script)
            .execute(&mut *connection)
            .await
            .is_err(),
        "a second run must fail instead of double counting"
    );
    sqlx::query("ROLLBACK")
        .execute(&mut *connection)
        .await
        .unwrap();
    drop(connection);
    assert!(
        db.store
            .record_usage_report("n1", report)
            .await
            .unwrap()
            .duplicate
    );
    db.store
        .record_usage_report(
            "n1",
            current_usage(generation, 3, base + 60, "epoch", 150, 260),
        )
        .await
        .unwrap();
    let after = db
        .store
        .node_inflow_usage(&system_admin(), "n1", SiteUsagePeriod::Month)
        .await
        .unwrap();
    let chain = after
        .rows
        .iter()
        .find(|row| row.source == NodeInflowSource::Chain)
        .unwrap();
    assert_eq!((chain.uplink_bytes, chain.downlink_bytes), (140, 240));
}

